do end
-- JSON encoder/decoder for CC-opencode.
-- Written by hand rather than using textutils so that null is a distinct value
-- (an assistant message with `content: null` is meaningful) and encoding is
-- deterministic, which cache keys rely on.

local M = {}

M.null = setmetatable({}, { __tostring = function() return "null" end })

local ARRAY_MT = { __isarray = true }

--- Mark a table so it encodes as a JSON array even when empty.
function M.array(t)
  return setmetatable(t or {}, ARRAY_MT)
end

--- True when `v` is the sentinel produced for a JSON `null`.
function M.isNull(v)
  return v == M.null
end

--- Replace every `json.null` inside a table with nil, so the result only holds
-- keys the encoder will emit.
function M.dropNulls(t)
  if type(t) ~= "table" then return t end
  for k, v in pairs(t) do
    if v == M.null then
      t[k] = nil
    elseif type(v) == "table" then
      M.dropNulls(v)
    end
  end
  return t
end

local ESCAPES = {
  ['"'] = '\\"',
  ['\\'] = '\\\\',
  ['\b'] = '\\b',
  ['\f'] = '\\f',
  ['\n'] = '\\n',
  ['\r'] = '\\r',
  ['\t'] = '\\t',
}

local UNESCAPES = {
  ['"'] = '"',
  ['\\'] = '\\',
  ['/'] = '/',
  b = '\b',
  f = '\f',
  n = '\n',
  r = '\r',
  t = '\t',
}

for char, escape in pairs(ESCAPES) do
  UNESCAPES[escape] = char
end

local function encodeString(s)
  return '"' .. s:gsub('[%z\1-\31\\"]', function(char)
    return ESCAPES[char] or string.format('\\u%04x', char:byte())
  end) .. '"'
end

local function encodeNumber(n)
  if n ~= n or n == math.huge or n == -math.huge then
    error("Cannot encode " .. tostring(n) .. " as JSON")
  end
  if n == math.floor(n) and math.abs(n) < 1e15 then
    return string.format("%d", n)
  end
  return string.format("%.14g", n)
end

--- Scan a table to decide array vs object, returning the highest array index.
--
-- A table is an array when every key is a positive integer. Holes are kept, and
-- encode them as null, because a model that sent `["a", null, "b"]` must get the
-- same array back. An empty table is ambiguous and encodes as an object unless it
-- was marked with `json.array`.
local function arrayLength(t)
  if getmetatable(t) == ARRAY_MT then
    return #t
  end
  local length = 0
  local keys = 0
  for key in pairs(t) do
    keys = keys + 1
    if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then
      return nil
    end
    if key > length then
      length = key
    end
  end
  if keys == 0 then
    return nil
  end
  return length
end

local function sortedKeys(t)
  local keys = {}
  for key in pairs(t) do
    keys[#keys + 1] = key
  end
  table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
  return keys
end

local function encodeInto(value, out, indent, depth)
  local kind = type(value)

  if value == nil or value == M.null then
    out[#out + 1] = "null"
    return
  end
  if kind == "boolean" then
    out[#out + 1] = tostring(value)
    return
  end
  if kind == "number" then
    out[#out + 1] = encodeNumber(value)
    return
  end
  if kind == "string" then
    out[#out + 1] = encodeString(value)
    return
  end
  if kind ~= "table" then
    error("Cannot encode " .. kind .. " as JSON")
  end
  if depth > 64 then
    error("JSON nesting is too deep")
  end

  local newline, pad, innerPad = "", "", ""
  if indent then
    newline = "\n"
    pad = string.rep(indent, depth)
    innerPad = string.rep(indent, depth + 1)
  end

  local length = arrayLength(value)
  if length then
    if length == 0 then
      out[#out + 1] = "[]"
      return
    end
    out[#out + 1] = "[" .. newline
    for i = 1, length do
      out[#out + 1] = innerPad
      encodeInto(value[i], out, indent, depth + 1)
      out[#out + 1] = i < length and ("," .. newline) or newline
    end
    out[#out + 1] = pad .. "]"
    return
  end

  local keys = sortedKeys(value)
  if #keys == 0 then
    out[#out + 1] = "{}"
    return
  end
  out[#out + 1] = "{" .. newline
  for i = 1, #keys do
    local key = keys[i]
    out[#out + 1] = innerPad .. encodeString(tostring(key)) .. ":" .. (indent and " " or "")
    encodeInto(value[key], out, indent, depth + 1)
    out[#out + 1] = i < #keys and ("," .. newline) or newline
  end
  out[#out + 1] = pad .. "}"
end

--- Encode a Lua value as JSON. Pass `indent` for pretty output.
function M.encode(value, indent)
  local out = {}
  local ok, err = pcall(encodeInto, value, out, indent, 0)
  if not ok then
    return nil, err
  end
  return table.concat(out)
end

local function utf8Encode(code)
  if code < 0x80 then
    return string.char(code)
  end
  if code < 0x800 then
    return string.char(0xC0 + math.floor(code / 0x40), 0x80 + code % 0x40)
  end
  if code < 0x10000 then
    return string.char(
      0xE0 + math.floor(code / 0x1000),
      0x80 + math.floor(code / 0x40) % 0x40,
      0x80 + code % 0x40
    )
  end
  return string.char(
    0xF0 + math.floor(code / 0x40000),
    0x80 + math.floor(code / 0x1000) % 0x40,
    0x80 + math.floor(code / 0x40) % 0x40,
    0x80 + code % 0x40
  )
end

local function decodeString(s, i)
  local out = {}
  i = i + 1
  while true do
    local char = s:sub(i, i)
    if char == "" then
      return nil, "unterminated string"
    end
    if char == '"' then
      return table.concat(out), i + 1
    end
    if char == "\\" then
      local escape = s:sub(i + 1, i + 1)
      local literal = UNESCAPES[escape]
      if literal then
        out[#out + 1] = literal
        i = i + 2
      elseif escape == "u" then
        local hex = s:sub(i + 2, i + 5)
        local code = tonumber(hex, 16)
        if not code then
          return nil, "invalid unicode escape at byte " .. i
        end
        i = i + 6
        if code >= 0xD800 and code <= 0xDBFF then
          -- A high surrogate is only half a character; pair it with the low one
          -- that follows, if there is one.
          local low = tonumber(s:sub(i + 2, i + 5), 16)
          if s:sub(i, i) == "\\" and s:sub(i + 1, i + 1) == "u" and low and low >= 0xDC00 and low <= 0xDFFF then
            code = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00)
            i = i + 6
          end
        end
        out[#out + 1] = utf8Encode(code)
      else
        return nil, "invalid escape at byte " .. i
      end
    else
      local stop = s:find('["\\]', i) or #s + 1
      out[#out + 1] = s:sub(i, stop - 1)
      i = stop
    end
  end
end

local WHITESPACE = { [" "] = true, ["\t"] = true, ["\n"] = true, ["\r"] = true }

local decodeValue

local function skipWhitespace(s, i)
  while WHITESPACE[s:sub(i, i)] do
    i = i + 1
  end
  return i
end

local function decodeObject(s, i, depth)
  local out = {}
  i = skipWhitespace(s, i + 1)
  if s:sub(i, i) == "}" then
    return out, i + 1
  end
  while true do
    if s:sub(i, i) ~= '"' then
      return nil, "expected object key at byte " .. i
    end
    local key, next_i = decodeString(s, i)
    if not key then
      return nil, next_i
    end
    i = skipWhitespace(s, next_i)
    if s:sub(i, i) ~= ":" then
      return nil, "expected ':' at byte " .. i
    end
    local value, next_i = decodeValue(s, skipWhitespace(s, i + 1), depth + 1)
    if value == nil then
      return nil, next_i
    end
    out[key] = value
    i = skipWhitespace(s, next_i)
    local char = s:sub(i, i)
    if char == "," then
      i = skipWhitespace(s, i + 1)
    elseif char == "}" then
      return out, i + 1
    else
      return nil, "expected ',' or '}' at byte " .. i
    end
  end
end

local function decodeArray(s, i, depth)
  local out = M.array({})
  i = skipWhitespace(s, i + 1)
  if s:sub(i, i) == "]" then
    return out, i + 1
  end
  while true do
    local value, next_i = decodeValue(s, skipWhitespace(s, i), depth + 1)
    if value == nil then
      return nil, next_i
    end
    out[#out + 1] = value
    i = skipWhitespace(s, next_i)
    local char = s:sub(i, i)
    if char == "," then
      i = i + 1
    elseif char == "]" then
      return out, i + 1
    else
      return nil, "expected ',' or ']' at byte " .. i
    end
  end
end

local LITERALS = {
  { "true", true, 4 },
  { "false", false, 5 },
  { "null", M.null, 4 },
}

decodeValue = function(s, i, depth)
  if depth > 64 then
    return nil, "JSON nesting is too deep"
  end
  local char = s:sub(i, i)
  if char == "{" then
    return decodeObject(s, i, depth)
  end
  if char == "[" then
    return decodeArray(s, i, depth)
  end
  if char == '"' then
    return decodeString(s, i)
  end
  for _, literal in ipairs(LITERALS) do
    if s:sub(i, i + literal[3] - 1) == literal[1] then
      return literal[2], i + literal[3]
    end
  end
  local numberStart = s:find("^%-?%d+", i)
  if not numberStart then
    return nil, "unexpected character at byte " .. i
  end
  local finish = s:find("[^%d%.eE%+%-]", numberStart) or (#s + 1)
  local text = s:sub(numberStart, finish - 1)
  local number = tonumber(text)
  if not number then
    return nil, "invalid number '" .. text .. "'"
  end
  return number, finish
end

--- Decode a JSON string. Returns `nil, message` on failure.
function M.decode(s)
  if type(s) ~= "string" then
    return nil, "expected a string, got " .. type(s)
  end
  local start = skipWhitespace(s, 1)
  if start > #s then
    return nil, "empty input"
  end
  local value, i = decodeValue(s, start, 0)
  if value == nil then
    return nil, i
  end
  i = skipWhitespace(s, i)
  if i <= #s then
    return nil, "trailing content at byte " .. i
  end
  return value
end

return M

end

-- src/util.lua
__sources["util"] = function(...)
do end
-- Small helpers shared across CC-opencode modules.

local M = {}

local sequence = 0

--- Monotonic, human-readable id with a prefix, e.g. "msg_3f2a1b".
function M.id(prefix)
  sequence = sequence + 1
  return string.format("%s_%06x", prefix, os.time() * 4096 + sequence)
end

--- Split a string on newlines, keeping no trailing empty field for a final newline.
function M.lines(s)
  local out = {}
  if not s or s == "" then
    return out
  end
  for line in (s .. "\n"):gmatch("([^\n]*)\n") do
    out[#out + 1] = line
  end
  if out[#out] == "" then
    out[#out] = nil
  end
  return out
end

function M.join(lines, separator)
  return table.concat(lines, separator or "\n")
end

function M.trim(s)
  return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

function M.startswith(s, prefix)
  return s:sub(1, #prefix) == prefix
end

function M.endswith(s, suffix)
  return suffix == "" or s:sub(-#suffix) == suffix
end

--- Translate a shell glob to a Lua pattern: `*` is "anything", `?` is one character.
local function globToPattern(glob)
  return (glob:gsub("([%^%$%(%)%%%.%[%]%+%-%?%*])", function(char)
    if char == "*" then
      return ".*"
    end
    if char == "?" then
      return "."
    end
    return "%" .. char
  end))
end

--- Wildcard match for permission patterns, ported from opencode's `Wildcard.match`.
--
-- A pattern that ends in " *" matches both the bare command and the command with
-- arguments, so `"ls *"` allows `ls`, `ls -la`, and `ls foo bar` but not
-- `lstmeval`. Everywhere else `*` is plain "anything", which is why `"ls*"`
-- deliberately also matches `lstmeval`.
function M.wildcard(value, pattern)
  if pattern == "*" then
    return true
  end
  value = value:gsub("\\", "/")
  pattern = pattern:gsub("\\", "/")

  if string.find(value, "^" .. globToPattern(pattern) .. "$") then
    return true
  end

  -- A pattern ending in " *" also matches the command with no arguments at all,
  -- so "ls *" allows "ls" as well as "ls -la".
  if M.endswith(pattern, " *") then
    return string.find(value, "^" .. globToPattern(pattern:sub(1, -3)) .. "$") ~= nil
  end
  return false
end

--- Case-insensitive "does one string contain the other", used for read's did-you-mean.
function M.fuzzyContains(a, b)
  return a:lower():find(b:lower(), 1, true) ~= nil
end

function M.copy(t)
  local out = {}
  for k, v in pairs(t) do
    out[k] = v
  end
  return out
end

--- Recursive copy. Config loading merges into a copy of the defaults, so a
--- shallow copy would let one loaded config rewrite the defaults for every later
--- load in the same process.
function M.deepCopy(t)
  if type(t) ~= "table" then
    return t
  end
  local out = {}
  for k, v in pairs(t) do
    out[k] = M.deepCopy(v)
  end
  return out
end

--- Count entries in a table without #, which is undefined for sparse arrays.
function M.count(t)
  local n = 0
  for _ in pairs(t) do
    n = n + 1
  end
  return n
end

--- Yield to the ComputerCraft event loop for `seconds`, keeping the terminal responsive.
function M.sleep(seconds)
  if os.sleep then
    return os.sleep(seconds)
  end
  -- Newer CC builds expose os.sleep; on the rest, block on our own timer.
  os.pullEvent("timer", os.startTimer(seconds))
end

--- #s characters starting at `i` (1-indexed).
function M.substr(s, i, length)
  return string.sub(s, i, i + (length or 1) - 1)
end

--- Human readable byte count, e.g. 51200 -> "50 KB".
function M.byteLabel(bytes)
  if bytes % (1024 * 1024) == 0 then
    return string.format("%d MB", bytes / (1024 * 1024))
  end
  if bytes % 1024 == 0 then
    return string.format("%d KB", bytes / 1024)
  end
  return string.format("%d bytes", bytes)
end

--- Break text into lines no wider than `width`, preferring to break at a space.
--
-- ComputerCraft's `write` does not wrap: anything past the right edge is not
-- merely ugly, it is discarded, and the rest of the line does not appear on the
-- next row. A computer's terminal is 51 columns, which is narrower than a url
-- and narrower than most error messages, so without this the interesting end of
-- a long line is exactly the part that never arrives.
--
-- A hard cut is the fallback rather than the rule. Most messages have a space
-- near the margin, and breaking there keeps the first line readable instead of
-- ending it mid-word.
function M.wrap(text, width)
  width = math.max(8, math.floor(tonumber(width) or 51))
  local lines = {}
  -- The trailing newline guarantees the last paragraph is seen, so text without
  -- one is not silently dropped.
  for paragraph in (tostring(text) .. "\n"):gmatch("([^\n]*)\n") do
    if paragraph == "" then
      lines[#lines + 1] = ""
    else
      local rest = paragraph
      while #rest > width do
        -- The last space at or before the margin. `.*` is greedy, so this finds
        -- the last one rather than the first.
        local space = rest:sub(1, width + 1):match("^.*()%s")
        local take
        if space and space >= math.floor(width / 2) then
          take = space - 1 -- stop before the space, and let the next line have it
        else
          -- No space, or one so early that breaking there would leave a scrap of
          -- a line. Either way, fill this one and keep the progress.
          take = width
        end
        lines[#lines + 1] = rest:sub(1, take)
        rest = (rest:sub(take + 1):gsub("^%s+", ""))
      end
      lines[#lines + 1] = rest
    end
  end
  return lines
end

return M

end

-- src/http.lua
__sources["http"] = function(...)
do end
-- HTTP with retries, built on ComputerCraft's synchronous `http.get`/`http.post`.
--
-- There is no incremental streaming here, and the reason is the shape of CC's
-- api rather than a choice. The response handle only exists once the whole
-- response has arrived, so there is nothing to hand on as it comes in. A request
-- that asks for `stream = true` is therefore buffered and then reassembled from
-- SSE frames by the LLM client; what that costs is the wait, since the terminal
-- stays quiet until the last byte lands.

local json = require("json")
local util = require("util")

local M = {}

M.DEFAULT_TIMEOUT = 60
M.RETRYABLE = { [408] = true, [409] = true, [429] = true, [500] = true, [502] = true, [503] = true, [504] = true, [529] = true }
M.MAX_ATTEMPTS = 3
M.BASE_DELAY = 1
M.MAX_DELAY = 16

--- Split a `data:` payload stream into its individual SSE frame strings.
function M.parseSse(body)
  local frames = {}
  for frame in (body or ""):gmatch("data:%s*([^\n]*)\n") do
    frame = frame:gsub("\r$", "")
    if frame ~= "" and frame ~= "[DONE]" then
      frames[#frames + 1] = frame
    end
  end
  return frames
end

--- Read a CC handle to completion, capping the result at `maxBytes`.
local function readHandle(handle, maxBytes)
  local body = handle.readAll and handle.readAll() or handle.read("*a")
  handle.close()
  if not maxBytes or #body <= maxBytes then
    return body or ""
  end
  return body:sub(1, maxBytes)
end

--- Whether a thrown error is the server refusing the host outright.
--
-- ComputerCraft keeps an allowlist of hosts a computer may reach, and a host
-- that is not on it is refused before any request is made. That is a different
-- kind of failure from a network fault: it is not transient, it is not the
-- caller's doing, and no amount of retrying will change the answer. The wording
-- has changed between CC versions, so both parts are matched rather than the
-- whole phrase.
local function isBlockedHost(reason)
  local lower = tostring(reason):lower()
  return lower:find("domain", 1, true) ~= nil and lower:find("not permitted", 1, true) ~= nil
end

--- What to tell someone whose host is not on the allowlist.
--
-- The bare CC error names the symptom and nothing else, and the thing that has
-- to change is a config file on the server rather than anything the caller can
-- do, so naming the file is the difference between a fixable problem and a
-- mysterious one.
local function blockedMessage(url)
  local host = url:match("^https?://([^/]+)") or url
  return "the server's http allowlist does not permit " .. host
    .. "\n  it needs an entry in serverconfig/computercraft-server.toml, as"
    .. "\n  [[http.rules]] with host = \"" .. host .. "\" and action = \"allow\","
    .. "\n  then a server restart. A host on your own network is refused by the"
    .. "\n  default $private deny rule whatever its name, so check that too."
end

--- Case-insensitive header lookup; CC normalises header names but not reliably.
local function lookup(headers, name)
  if not headers then
    return nil
  end
  local direct = headers[name]
  if direct then
    return direct
  end
  local lowered = name:lower()
  for key, value in pairs(headers) do
    if key:lower() == lowered then
      return value
    end
  end
  return nil
end

--- Seconds to wait before retrying, honouring Retry-After when the server sent it.
local function backoff(attempt, headers)
  local retryAfter = lookup(headers, "retry-after-ms") or lookup(headers, "retry-after")
  if retryAfter then
    local ms = tonumber(retryAfter)
    if ms then
      return math.min(60, ms / 1000)
    end
    local date = tonumber(retryAfter)
    if date and date > os.time() then
      return math.min(60, date - os.time())
    end
  end
  return math.min(M.MAX_DELAY, M.BASE_DELAY * 2 ^ (attempt - 1)) * (0.75 + math.random() * 0.5)
end

--- Perform a request, retrying 429 and 5xx responses.
--
-- Returns `response` on success, or `nil, message` on failure. A non-2xx status
-- is returned as a normal response so callers can read the provider's error body;
-- only transport failures, exhausted retries, and a request table CC refuses
-- become errors.
function M.request(url, options)
  options = options or {}
  local attempts = options.attempts or M.MAX_ATTEMPTS
  local lastError = "no attempt was made"

  for attempt = 1, attempts do
    -- `http.get` or `http.post`, never `http.request`.
    --
    -- `http.request` is the asynchronous half of CC's API: it starts the request,
    -- returns immediately, and delivers the response later as an `http_success`
    -- event. Its own source describes the return value as "for legacy reasons"
    -- and undocumented. It is a boolean, so reading a response out of it raises
    -- "attempt to index local 'handle' (a boolean value)" and nothing is ever
    -- fetched. The synchronous pair wraps that identical call in an `os.pullEvent`
    -- loop, and that loop is the whole difference.
    --
    -- `get` refuses a body and `post` allows one, so the entry point follows the
    -- presence of a body rather than the other way round. A body-less DELETE goes
    -- through `get`, which passes `method` on to the socket regardless.
    --
    -- The url goes *inside* the table, which is the documented options form.
    -- CC dispatches on the type of the first argument, and a string puts it in the
    -- legacy positional signature, where argument 2 is the body and must be a
    -- string -- so a table in second place is refused outright with "bad argument
    -- #2 (string expected, got table)".
    --
    -- The keys are spelled out rather than merged from `options` because a nil
    -- value is not the same as an absent key: `headers = nil` through a table
    -- constructor drops the key, but a caller that built the options table itself
    -- cannot be relied on to have done the same.
    local request = {
      url = url,
      method = options.method or "GET",
      timeout = options.timeout or M.DEFAULT_TIMEOUT,
    }
    if options.headers then
      request.headers = options.headers
    end
    if options.body then
      request.body = options.body
    end
    local ok, handle, reason, failed = pcall(request.body and http.post or http.get, request)

    if not ok then
      -- A throw here is CC checking the shape of the table, which is our bug and
      -- not the network's: an unusable method, a timeout that is not a number.
      -- Retrying it three times would spend three requests to learn the same
      -- thing, so say what it is instead of dressing it up as a network fault.
      return nil, "internal error: " .. tostring(handle)
    end

    -- A 2xx comes back as the first value. A 4xx or 5xx comes back as the third,
    -- with the message in the second, and both are real responses worth reading:
    -- a provider's own error text exists only in that body, and a 429's
    -- Retry-After header only with it. Only a transport failure has neither.
    local answer = handle or failed
    if answer then
      local status = answer.getResponseCode and answer.getResponseCode() or 200
      local headers = answer.getResponseHeaders and answer.getResponseHeaders() or {}
      local response = { status = status, headers = headers, body = readHandle(answer, options.maxBytes) }
      if not (M.RETRYABLE[status] and attempt < attempts) then
        return response
      end
      lastError = "HTTP " .. status
      if attempt < attempts then
        util.sleep(backoff(attempt, headers))
      end
    else
      -- The socket failed and nothing answered. This is also where a host missing
      -- from the server's allowlist lands, since CC refuses it before the request
      -- is ever made -- so the wording is checked here as well as on a throw.
      if isBlockedHost(reason) then
        -- Fail now rather than twice more: the answer cannot change, and the
        -- backoff would turn a missing config line into a ten second wait.
        return nil, blockedMessage(url)
      end
      lastError = "could not reach " .. url .. " (" .. tostring(reason) .. ")"
      if attempt < attempts then
        util.sleep(backoff(attempt, nil))
      end
    end
  end

  return nil, lastError
end

--- Best-effort extraction of a human readable message from a failed response.
function M.errorMessage(response)
  local body = response.body or ""
  local decoded = json.decode(body)
  if type(decoded) == "table" then
    local message = decoded.error
    if type(message) == "table" then
      message = message.message
    end
    if type(message) == "string" and message ~= "" then
      return "HTTP " .. response.status .. ": " .. message
    end
  end
  local trimmed = util.trim(body)
  if trimmed == "" then
    trimmed = "(empty response body)"
  end
  if #trimmed > 400 then
    trimmed = trimmed:sub(1, 400) .. "..."
  end
  return "HTTP " .. response.status .. ": " .. trimmed
end

--- POST a JSON body. Returns a response table with `data` holding the decode.
--
-- `options.decode = false` leaves `data` unset, for callers that expect an
-- event stream rather than a JSON document.
function M.postJson(url, payload, options)
  options = options or {}
  local response, err = M.request(url, {
    method = "POST",
    headers = options.headers,
    body = options.raw or json.encode(payload),
    timeout = options.timeout,
    attempts = options.attempts,
    maxBytes = options.maxBytes,
  })
  if not response then
    return nil, err
  end
  if response.status < 200 or response.status >= 300 then
    return nil, M.errorMessage(response)
  end

  if options.decode == false then
    return response
  end
  response.data = json.decode(response.body or "")
  if not response.data then
    return nil, "could not parse the response as JSON: " .. tostring(response.body):sub(1, 200)
  end
  return response
end

return M

end

-- src/environment.lua
__sources["environment"] = function(...)
do end
-- ComputerCraft environment access.
--
-- Every CC API the project touches goes through this module so the rest of the
-- code has no direct `fs`/`shell`/`http` references. The test harness swaps in a
-- mock with the same surface, which is how the agent loop is exercised without
-- a Minecraft client.

-- `util` is the only project module this one reaches for, and only for its
-- word-breaking, because undoing a hardware habit belongs at the boundary with
-- the hardware. It requires nothing back, so the dependency is one-way.
local util = require("util")

local M = {}

M.isCC = type(shell) == "table" and type(fs) == "table"

-- Defined here rather than required from `util` so the environment layer stays
-- the one module that knows about the two string primitives it needs itself.
local function startswith(s, prefix)
  return s:sub(1, #prefix) == prefix
end

local function endswith(s, suffix)
  return suffix == "" or s:sub(-#suffix) == suffix
end

M.startswith, M.endswith = startswith, endswith

function M.cwd()
  if not M.isCC then
    return (os.getenv and os.getenv("PWD")) or "/"
  end
  return shell.dir()
end

function M.combine(...)
  if M.isCC then
    return fs.combine(...)
  end
  local parts = { ... }
  local out = "/"
  for _, part in ipairs(parts) do
    if part == nil or part == "" then
      -- skip
    elseif out == "/" then
      out = "/" .. tostring(part)
    else
      out = out .. "/" .. tostring(part)
    end
  end
  return (out:gsub("//+", "/"))
end

function M.dirname(path)
  if M.isCC then
    return fs.getDir(path)
  end
  local dir = path:match("^(.*)/[^/]*$")
  if not dir or dir == "" then
    return "/"
  end
  return dir
end

function M.basename(path)
  if M.isCC then
    return fs.getName(path)
  end
  return path:match("([^/]*)$") or path
end

function M.isAbsolute(path)
  return M.startswith(path or "", "/")
end

--- Resolve `path` against `base` and normalise "." and ".." segments.
function M.resolve(path, base)
  local absolute = M.isAbsolute(path) and path or M.combine(base or M.cwd(), path)
  local parts = {}
  for segment in absolute:gmatch("[^/]+") do
    if segment == "." then
      -- skip
    elseif segment == ".." then
      parts[#parts] = nil
    else
      parts[#parts + 1] = segment
    end
  end
  return "/" .. table.concat(parts, "/")
end

--- True when `path` is `root` or lives inside it.
function M.contains(root, path)
  if root == path then
    return true
  end
  if M.endswith(root, "/") then
    return M.startswith(path, root)
  end
  return M.startswith(path, root .. "/")
end

function M.exists(path)
  if M.isCC then
    return fs.exists(path)
  end
  local handle = io.open(path, "r")
  if handle then
    handle:close()
    return true
  end
  -- Directories are not readable as files, so fall back to a probe.
  local pipe = io.popen("test -e " .. M.quote(path) .. " && echo yes")
  if not pipe then
    return false
  end
  local out = pipe:read("*a")
  pipe:close()
  return out == "yes"
end

function M.isDir(path)
  if M.isCC then
    return fs.isDir(path)
  end
  local pipe = io.popen("test -d " .. M.quote(path) .. " && echo yes")
  if not pipe then
    return false
  end
  local out = pipe:read("*a")
  pipe:close()
  return out == "yes"
end

function M.size(path)
  if M.isCC then
    return fs.getSize(path)
  end
  local handle = io.open(path, "rb")
  if not handle then
    return 0
  end
  local size = handle:seek("end")
  handle:close()
  return size
end

function M.modified(path)
  if M.isCC then
    return fs.attributes(path, "modification") or 0
  end
  local pipe = io.popen("date -r " .. M.quote(path) .. " +%s 2>/dev/null")
  if not pipe then
    return 0
  end
  local out = pipe:read("*a")
  pipe:close()
  return tonumber(out) or 0
end

function M.mkdir(path)
  if M.isCC then
    return fs.makeDir(path)
  end
  return os.execute("mkdir -p " .. M.quote(path))
end

--- Create `path` and every missing parent, ignoring directories that already exist.
function M.mkdirs(path)
  local current = "/"
  for segment in path:gmatch("[^/]+") do
    current = current .. segment
    if not M.isDir(current) then
      M.mkdir(current)
    end
    current = current .. "/"
  end
  return M.isDir(path)
end

function M.read(path)
  if M.isCC then
    local handle = fs.open(path, "r")
    if not handle then
      return nil
    end
    local content = handle.readAll()
    handle.close()
    return content
  end
  local handle = io.open(path, "rb")
  if not handle then
    return nil
  end
  local content = handle:read("*a")
  handle:close()
  return content
end

--- Read at most `limit` bytes, reporting whether the file was cut short.
function M.readLimited(path, limit)
  local size = M.size(path)
  if limit and size > limit then
    if M.isCC then
      local handle = fs.open(path, "r")
      if not handle then
        return nil
      end
      local chunk = handle.read(limit) or ""
      handle.close()
      return chunk, true
    end
    local handle = io.open(path, "rb")
    if not handle then
      return nil
    end
    local chunk = handle:read(limit) or ""
    handle:close()
    return chunk, true
  end
  return M.read(path), false
end

function M.write(path, content)
  if M.isCC then
    local handle = fs.open(path, "w")
    if not handle then
      return false
    end
    handle.write(content)
    handle.close()
    return true
  end
  local handle = io.open(path, "wb")
  if not handle then
    return false
  end
  handle:write(content)
  handle:close()
  return true
end

function M.append(path, content)
  if M.isCC then
    local handle = fs.open(path, "a")
    if not handle then
      return false
    end
    handle.write(content)
    handle.close()
    return true
  end
  local handle = io.open(path, "ab")
  if not handle then
    return false
  end
  handle:write(content)
  handle:close()
  return true
end

function M.remove(path)
  if M.isCC then
    return fs.delete(path)
  end
  return os.remove(path)
end

function M.rename(from, to)
  if fs and fs.posix then
    local ok = fs.posix.rename(from, to)
    if ok then
      return true
    end
  end
  if not os.rename(from, to) then
    return false
  end
  return true
end

--- Entry names in a directory, sorted, excluding "." and "..".
function M.listDir(path)
  local names = {}
  if M.isCC then
    for _, name in ipairs(fs.dir(path)) do
      names[#names + 1] = name
    end
  else
    local pipe = io.popen("ls -A " .. M.quote(path) .. " 2>/dev/null")
    if pipe then
      for name in pipe:lines() do
        names[#names + 1] = name
      end
      pipe:close()
    end
  end
  table.sort(names)
  return names
end

--- Walk `path` depth-first, calling `onFile` and `onDir` with absolute paths.
-- `onDir` returning false skips that subtree.
function M.walk(path, options)
  local onFile = options.onFile or function() end
  local onDir = options.onDir or function() end
  local includeHidden = options.includeHidden
  local maxDepth = options.maxDepth or 32

  local function visit(dir, depth)
    if depth > maxDepth or not M.isDir(dir) then
      return
    end
    for _, name in ipairs(M.listDir(dir)) do
      if includeHidden or not M.startswith(name, ".") then
        local full = dir .. (dir == "/" and "" or "/") .. name
        if M.isDir(full) then
          if onDir(full, name) ~= false then
            visit(full, depth + 1)
          end
        else
          onFile(full, name)
        end
      end
    end
  end

  visit(path, 1)
end

--- Single-quote a value for the ComputerCraft shell.
function M.quote(value)
  return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
end

function M.now()
  if os.date then
    return os.date("%c")
  end
  return "unknown"
end

function M.today()
  if os.date then
    return os.date("%Y-%m-%d")
  end
  return "unknown"
end

function M.computerLabel()
  if M.isCC and os.getComputerLabel then
    return os.getComputerLabel() or "computer"
  end
  return "host"
end

--- A screen presenting the same methods whether it is a monitor or a terminal.
--
-- Monitors and terminals are nearly the same API, but neither is a superset of
-- the other, and the REPL should not have to care which one it got.
--
-- `write` is also where text is wrapped, and it is here rather than in the REPL
-- for two reasons. It is the one place every drawn character passes through —
-- a line of the conversation and a question from the permission prompt alike —
-- so a new caller cannot get it wrong by forgetting. And it is a property of the
-- hardware rather than of the interface: ComputerCraft does not carry a line
-- that overruns its screen, so a 51-column terminal loses the end of every long
-- line, the tail of every url, and the part of an error message that says what
-- to do about it. The column is carried between calls because a reply arrives in
-- pieces and each piece has to be broken knowing where the last one finished.
local function adapt(screen)
  -- ComputerCraft calls these with a dot — `term.write(text)`, not
  -- `term:write(text)` — so the screen must not be passed back in.
  local function call(name, ...)
    local method = screen[name]
    if not method then
      return nil
    end
    return method(...)
  end

  -- The column the next character will land in, counting from 1. Only what this
  -- screen has been told moves it: `read` echoes onto the terminal and puts the
  -- cursor somewhere this cannot see, which is why the REPL writes its blank
  -- line before the next prompt and so re-synchronises it for free.
  local column = 1

  --- The usable width: the screen's, less the last column.
  --
  -- The last column is left alone on purpose. Filling it is what puts a
  -- ComputerCraft screen in a state where what happens next depends on the
  -- version — continued on the next row, or thrown away — and neither is worth
  -- betting a line of output on.
  local function limit()
    local ok, width = pcall(function()
      return screen.getSize()
    end)
    if ok and type(width) == "number" and width >= 8 then
      return width - 1
    end
    return 50
  end

  --- Write `text`, wrapped, with the newlines in it honoured.
  local function write(text)
    if text == nil then
      return nil
    end
    text = tostring(text)
    local rows = {}
    local at = 1
    while at <= #text do
      local stop = text:find("\n", at, true)
      local piece = text:sub(at, (stop or (#text + 1)) - 1)
      if piece ~= "" then
        local room = limit() - column + 1
        -- Nothing worth wrapping into, so move along a row rather than break
        -- words two characters at a time.
        if room < 8 then
          rows[#rows + 1] = "\n"
          column = 1
          room = limit()
        end
        if #piece > room then
          -- Fill what is left of this row, breaking at a space where there is
          -- one, then wrap the remainder at the full width rather than at
          -- whatever happened to be left over. A reply that spills ten
          -- characters past the margin has to carry on at full width: wrapping
          -- the rest of it into a column ten wide would fit a third of it on
          -- the screen.
          local head = util.wrap(piece, room)[1]
          rows[#rows + 1] = head
          rows[#rows + 1] = "\n"
          local rest = util.wrap(util.trim(piece:sub(#head + 1)), limit())
          for i, row in ipairs(rest) do
            rows[#rows + 1] = row
            if i < #rest then
              rows[#rows + 1] = "\n"
            else
              column = #row + 1
            end
          end
        else
          rows[#rows + 1] = piece
          column = column + #piece
        end
      end
      if stop then
        rows[#rows + 1] = "\n"
        column = 1
        at = stop + 1
      else
        at = #text + 1
      end
    end
    return call("write", table.concat(rows))
  end

  return {
    raw = screen,
    isMonitor = screen ~= term,
    write = write,
    clear = function() return call("clear") end,
    scroll = function() return call("scroll") end,
    setCursorBlink = function(state) return call("setCursorBlink", state) end,
    setCursorPos = function(x, y) return call("setCursorPos", x, y) end,
    setTextColor = function(colour) return call("setTextColor", colour) end,
    getCursorPos = function() return call("getCursorPos") end,
    getSize = function() return call("getSize") end,
  }
end

--- Prepare a screen for drawing on, or nil.
--
-- `M.terminal` is the usual way in; this is for a screen the caller already has.
-- It exists so that there is no way to hand the program something it will draw
-- on without the text being wrapped: the wrapping is the adapter's, and a raw
-- screen is not adapted, so every path in has to come through here. Adapting an
-- adapted screen gives it straight back, so there is no order to get right.
function M.screen(raw)
  if raw == nil then
    return nil
  end
  if raw.raw ~= nil then
    return raw
  end
  return adapt(raw)
end

--- The best available screen, or nil when there is neither a monitor nor a
--- terminal. Monitors are preferred, so a multi-computer setup prints to the
--- monitor rather than to the computer nobody is looking at.
function M.terminal()
  if peripheral and peripheral.find then
    for _, name in ipairs({ "left", "right", "monitor_1", "monitor_2", "monitor_3" }) do
      local monitor = peripheral.find(name)
      if monitor then
        return adapt(monitor)
      end
    end
  end
  if term then
    return adapt(term)
  end
  return nil
end

--- The computer's own terminal, unwrapped, or nil.
--
-- `M.terminal` prefers a monitor, which is right for a program that prints and
-- exits but wrong for one the operator has to type into: CraftOS's keyboard
-- belongs to the terminal, and `read` reads the terminal whatever the program
-- happens to be drawing on. An input field drawn on a monitor is a field nobody
-- can reach, so the GUI draws here.
function M.console()
  if M.isCC and type(term) == "table" and type(term.getSize) == "function" then
    return term
  end
  return nil
end

--- The remaining CraftOS primitives, for the UI, each absent rather than broken.
--
-- A GUI needs to draw boxes (`paintutils`), name a key code (`keys`), and block
-- until the operator does something (`os.pullEvent`). All of them are read off the
-- globals once, and each is nil when this build of CraftOS does not have it, so
-- that a caller can ask "is there a screen to draw on" instead of calling into
-- nothing. The UI cannot do without `pullEvent`; the rest it degrades on.
function M.system()
  if not M.isCC then
    return {}
  end
  return {
    paint = type(paintutils) == "table" and paintutils or nil,
    keyName = (type(keys) == "table" and type(keys.getName) == "function") and keys.getName or nil,
    pullEvent = (type(os.pullEvent) == "function") and os.pullEvent or nil,
    startTimer = (type(os.startTimer) == "function") and os.startTimer or nil,
    cancelTimer = (type(os.cancelTimer) == "function") and os.cancelTimer or nil,
    -- Seconds since the computer started. `os.timer` is wall-clock and so keeps
    -- moving while the program is blocked on the network, which is where a reply
    -- streams in; `os.clock` is CPU time and only counts the program's own work.
    -- The UI throttles its repaints with the first and falls back to the second,
    -- where a repaint of a screen this small costs less than the reading around it.
    timer = (type(os.timer) == "function") and os.timer or nil,
    clock = (type(os.clock) == "function") and os.clock or nil,
  }
end

--- Read one line of input from the operator, or nil at end of input.
--
-- This is CraftOS's global `read`, not a method on a screen, and the difference
-- is the whole of it. The `term` module is blit, clear, getCursorPos, getSize,
-- native, redirect, scroll, setBackgroundColour, setCursorBlink, setCursorPos,
-- setTextColour, and write -- there is no `readLine` on it. A screen asked for one
-- answers nil, which is indistinguishable from the operator closing the program,
-- and both callers here treated nil that way: the REPL exited straight after the
-- banner, and every permission prompt denied without ever asking. CC's own shell
-- reads its line this way, and gets line editing, history and tab completion for
-- it, none of which a hand-rolled key loop would have matched.
--
-- Named `readLine` rather than `read` because `M.read` is already the file reader
-- that `config` uses to fetch a key from disk, and one function cannot be both.
--
-- Wrapped rather than called as a global so that every CC API the project touches
-- is still visible in this one file, and so the harness can stand in for it.
function M.readLine()
  if type(read) ~= "function" then
    return nil
  end
  return read()
end

return M

end

-- src/config.lua
__sources["config"] = function(...)
do end
-- Configuration loading.
--
-- Precedence, lowest to highest: built-in defaults, `opencode.json` in the
-- working directory, `/opencode.json`, then runtime overrides passed by the CLI.

local json = require("json")
local util = require("util")
local env = require("environment")

local M = {}

-- The gateway serves 82 models and exactly one of them answers without a
-- credential: `space-bunny-free`. The other ten ids ending in `-free` do not, and
-- refuse with 403 "OpenCode's free tier can only be used from within OpenCode" --
-- they are gated on the official client, not on being free. Everything else refuses
-- with 401 "Missing API key."
--
-- So the default is the one model that works on a computer that has never been
-- given a key, which is the state a fresh install is in. It is a single model on a
-- third-party gateway with no availability promise, so a key is worth having: set
-- `env` and change `model` to any of the other 81.
M.DEFAULT_MODEL = "opencode/space-bunny-free"
M.DEFAULT_SMALL_MODEL = "opencode/space-bunny-free"

M.DEFAULTS = {
  model = M.DEFAULT_MODEL,
  small_model = M.DEFAULT_SMALL_MODEL,
  tool_output = { max_lines = 2000, max_bytes = 50 * 1024 },
  compaction = { auto = true, reserved = 20 * 1024 },
  -- Name a session from its first question when it is saved. Set to false to
  -- skip the extra request.
  title = true,
  -- The one model that needs no credential, declared so the picker lists it and
  -- resolution knows to send the request without an `Authorization` header. Its
  -- context size is not published, so `limit` is left to the default rather than
  -- guessed at; declare one here if you find out.
  provider = {
    opencode = {
      models = {
        ["space-bunny-free"] = { name = "Space Bunny (free)", apiKey = false },
      },
    },
  },
  agent = {
    build = { steps = 25 },
    general = { steps = 15 },
    plan = { steps = 25 },
  },
  permission = {
    { permission = "*", pattern = "*", action = "allow" },
    { permission = "doom_loop", pattern = "*", action = "ask" },
    { permission = "external_directory", pattern = "*", action = "ask" },
    { permission = "read", pattern = "*.env", action = "ask" },
    { permission = "read", pattern = "*.env.*", action = "ask" },
    { permission = "read", pattern = "*.env.example", action = "allow" },
  },
}

--- Built-in OpenAI-compatible providers, mirroring opencode's profile table.
-- `env` lists the variable names the credential is read from in `config.env`,
-- which stands in for a real process environment.
M.PROFILES = {
  -- The gateway is on opencode.ai, not on models.opencode.ai. That looks like a
  -- near-miss and is not one: models.opencode.ai is the models.dev website, and
  -- it answers every path under it with a 302 to its front page, so a base url
  -- pointing there connects and then hands back HTML where a JSON reply should
  -- be. It needs a key for all but one of its models; that one is declared in
  -- M.DEFAULTS, and the key is issued on opencode.ai and goes in
  -- `env.OPENCODE_API_KEY`.
  opencode = { name = "opencode zen", base = "https://opencode.ai/zen/v1", env = { "OPENCODE_API_KEY" } },
  openai = { name = "OpenAI", base = "https://api.openai.com/v1", env = { "OPENAI_API_KEY" } },
  openrouter = { name = "OpenRouter", base = "https://openrouter.ai/api/v1", env = { "OPENROUTER_API_KEY" } },
  groq = { name = "Groq", base = "https://api.groq.com/openai/v1", env = { "GROQ_API_KEY" } },
  cerebras = { name = "Cerebras", base = "https://api.cerebras.ai/v1", env = { "CEREBRAS_API_KEY" } },
  deepinfra = { name = "DeepInfra", base = "https://api.deepinfra.com/v1/openai", env = { "DEEPINFRA_API_KEY" } },
  deepseek = { name = "DeepSeek", base = "https://api.deepseek.com/v1", env = { "DEEPSEEK_API_KEY" } },
  fireworks = { name = "Fireworks", base = "https://api.fireworks.ai/inference/v1", env = { "FIREWORKS_API_KEY" } },
  togetherai = { name = "Together AI", base = "https://api.together.xyz/v1", env = { "TOGETHER_API_KEY" } },
  xai = { name = "xAI", base = "https://api.x.ai/v1", env = { "XAI_API_KEY" } },
  ollama = { name = "Ollama", base = "http://localhost:11434/v1", env = { "OLLAMA_API_KEY" }, apiKey = "ollama" },
  lmstudio = { name = "LM Studio", base = "http://localhost:1234/v1", env = { "LMSTUDIO_API_KEY" }, apiKey = "lmstudio" },
}

--- Search paths for opencode.json, relative entries resolved against the cwd.
M.CONFIG_PATHS = { "opencode.json", "/opencode.json", "/.opencode/opencode.json" }

local function readConfigFile(path)
  local content = env.read(path)
  if not content then
    return nil
  end
  return json.decode(content)
end

local function merge(target, source)
  for key, value in pairs(source) do
    if type(value) == "table" and type(target[key]) == "table" then
      merge(target[key], value)
    else
      target[key] = value
    end
  end
  return target
end

local function readAll(cwd)
  local config = {}
  for _, candidate in ipairs(M.CONFIG_PATHS) do
    local path = util.startswith(candidate, "/") and candidate or env.combine(cwd, candidate)
    local parsed = readConfigFile(path)
    if type(parsed) == "table" then
      merge(config, parsed)
      config.__source = config.__source or path
    end
  end
  return config
end

--- Load configuration, applying `overrides` from the command line on top.
function M.load(cwd, overrides)
  local config = merge(util.deepCopy(M.DEFAULTS), readAll(cwd or env.cwd()))
  if overrides then
    merge(config, overrides)
  end
  config.cwd = cwd or env.cwd()
  return config
end

--- Read an API key from the config, a key file, or `config.env`.
function M.apiKey(config, provider)
  local options = provider.options or {}
  if type(options.apiKey) == "string" and options.apiKey ~= "" then
    return options.apiKey
  end
  if type(options.apiKeyFile) == "string" and options.apiKeyFile ~= "" then
    local path = util.startswith(options.apiKeyFile, "/") and options.apiKeyFile
      or env.combine(config.cwd, options.apiKeyFile)
    local content = env.read(path)
    if content then
      return util.trim(content)
    end
  end
  for _, name in ipairs(provider.env or {}) do
    local value = (config.env or {})[name]
    if type(value) == "string" and value ~= "" then
      return value
    end
  end
  -- Profiles that need no real credential (a public key, or a local server that
  -- ignores the header) carry one. It is the last resort so a supplied
  -- credential always wins.
  if type(provider.apiKey) == "string" and provider.apiKey ~= "" then
    return provider.apiKey
  end
  return nil
end

function M.toolOutputLimits(config)
  local options = config.tool_output or {}
  return {
    max_lines = options.max_lines or M.DEFAULTS.tool_output.max_lines,
    max_bytes = options.max_bytes or M.DEFAULTS.tool_output.max_bytes,
  }
end

return M

end

-- src/provider.lua
__sources["provider"] = function(...)
do end
-- Provider and model resolution.
--
-- Model ids are `provider/model`, split on the FIRST slash only, so nested ids
-- like `openrouter/anthropic/claude-sonnet-4` resolve to provider `openrouter`
-- with model id `anthropic/claude-sonnet-4`.

local config = require("config")
local util = require("util")

local M = {}

M.DEFAULT_LIMIT = { context = 128 * 1024, output = 8 * 1024 }

M.SSE_PATH = "/chat/completions"

--- Re-exported so callers only need this module to resolve a credential.
M.apiKey = config.apiKey

--- Split a model string into its provider and model halves.
function M.parseModel(model)
  local slash = model:find("/", 1, true)
  if not slash then
    return model, ""
  end
  return model:sub(1, slash - 1), model:sub(slash + 1)
end

--- Merge a built-in profile with any user override of the same provider id.
local function buildProfile(id, override)
  local profile = config.PROFILES[id] or {}
  local merged = util.deepCopy(profile)
  merged.id = id
  merged.base = (override and override.api) or profile.base
  merged.name = (override and override.name) or profile.name or id
  merged.env = (override and override.env) or profile.env
  merged.apiKey = profile.apiKey
  if override and override.options then
    merged.options = util.deepCopy(override.options)
  end
  return merged
end

--- All known providers: built-in profiles overlaid with `config.provider`.
function M.list(configValue)
  local providers = {}
  for id, _ in pairs(config.PROFILES) do
    providers[id] = buildProfile(id, (configValue.provider or {})[id])
  end
  for id, override in pairs(configValue.provider or {}) do
    providers[id] = buildProfile(id, override)
  end
  return providers
end

--- Resolved provider entry: base url, credential, and model metadata.
--
-- A missing credential is not an error here. Whether one is needed is a property of
-- the *model*: the gateway serves one model that answers unauthenticated, and a
-- local server may ignore the header. So the key is recorded as absent and
-- `M.model` decides, which is the only place that knows which model was asked for.
function M.get(configValue, providerID)
  local providers = M.list(configValue)
  local provider = providers[providerID]
  if not provider then
    return nil, "Unknown provider '" .. providerID .. "'. Add it under \"provider\" in opencode.json."
  end
  if not provider.base then
    return nil, "Provider '" .. providerID .. "' has no baseURL. Set options.baseURL in opencode.json."
  end
  provider.apiKeyResolved = config.apiKey(configValue, provider)
  return provider
end

local function mergeOptions(providerOptions, modelOptions)
  local out = util.deepCopy(providerOptions or {})
  for key, value in pairs(modelOptions or {}) do
    out[key] = value
  end
  return out
end

--- The advice given when a model needs a credential and none could be found.
--
-- It names the variable to set, because "no API key" on its own leaves the reader
-- to guess between three places it can go, and because the gateway's own 401 says
-- only "Missing API key." It also names the model, since on a gateway where one
-- model out of 82 needs no key, "no key" is not obviously the problem.
local function noCredential(providerID, provider, modelID)
  local names = table.concat(provider.env or {}, ", ")
  return "No API key for '" .. providerID .. "/" .. modelID .. "'."
    .. " Set options.apiKey, options.apiKeyFile, or env."
    .. (names ~= "" and (" (" .. names .. ")") or "")
end

--- Metadata for one model within a provider, merged with the provider defaults.
function M.model(configValue, providerID, modelID)
  local provider = M.get(configValue, providerID)
  if not provider then
    return nil, select(2, M.get(configValue, providerID))
  end
  local override = ((configValue.provider or {})[providerID] or {}).models or {}
  local entry = override[modelID] or {}
  local key = provider.apiKeyResolved
  if not key and entry.apiKey ~= false then
    -- No credential, and this model has not declared that it does without one.
    return nil, noCredential(providerID, provider, modelID)
  end
  return {
    providerID = providerID,
    id = modelID,
    name = entry.name or modelID,
    base = provider.base,
    -- Nil rather than empty: `llm` reads this to decide whether to send an
    -- `Authorization` header at all, and an empty one is not the same request.
    apiKey = key,
    api = provider.api,
    limit = entry.limit or M.DEFAULT_LIMIT,
    options = mergeOptions(provider.options, entry.options),
    headers = entry.headers or (provider.options or {}).headers,
  }
end

--- Resolve a full `provider/model` string, including default-model selection.
function M.resolve(configValue, modelString)
  if not modelString or modelString == "" then
    return nil, "No model configured. Set \"model\" in opencode.json, e.g. \"openrouter/anthropic/claude-sonnet-4\"."
  end
  local providerID, modelID = M.parseModel(modelString)
  if modelID == "" then
    return nil, "Model '" .. modelString .. "' has no model part. Use the form provider/model."
  end
  local model, err = M.model(configValue, providerID, modelID)
  if not model then
    return nil, err
  end
  return model
end

--- Full request url for a model: base with trailing slashes trimmed, plus the path.
function M.url(model, path)
  return model.base:gsub("/+$", "") .. (path or M.SSE_PATH)
end

--- Every `provider/model` pair the config can reach, for model pickers.
function M.availableModels(configValue)
  local out = {}
  for id, provider in pairs(M.list(configValue)) do
    local configured = ((configValue.provider or {})[id] or {}).models
    if configured and util.count(configured) > 0 then
      for modelID, entry in pairs(configured) do
        out[#out + 1] = {
          id = id .. "/" .. modelID,
          name = entry.name or modelID,
          provider = provider.name or id,
          -- Asked of `M.model` rather than of the provider, because "usable" is a
          -- property of the model: one of them needs no credential, and marking it
          -- `(no api key)` would flag the only model a fresh install can use as
          -- the one it cannot. Asking `M.model` also means the list and the
          -- request can never disagree about what is available.
          available = M.model(configValue, id, modelID) ~= nil,
        }
      end
    end
  end
  table.sort(out, function(a, b) return a.id < b.id end)
  return out
end

return M

end

-- src/llm.lua
__sources["llm"] = function(...)
do end
-- OpenAI-compatible chat completions client.
--
-- Mirrors opencode's OpenAI Chat protocol: `/chat/completions` on the trimmed
-- base URL, a bearer credential, and a body that omits empty fields. ComputerCraft
-- buffers whole responses, so a `stream: true` request is read in full and the SSE
-- frames are reassembled here.

local json = require("json")
local http = require("http")
local provider = require("provider")

local M = {}

M.FINISH = {
  stop = "stop",
  length = "length",
  content_filter = "content-filter",
  function_call = "tool-calls",
  tool_calls = "tool-calls",
}

local function headerValue(model, key, fallback)
  local headers = model.headers or {}
  local direct = headers[key]
  if direct then
    return direct
  end
  for name, value in pairs(headers) do
    if name:lower() == key:lower() then
      return value
    end
  end
  return fallback
end

--- Drop keys whose value is nil, json.null, or an empty array, as the protocol requires.
local function compact(table_)
  local out = {}
  for key, value in pairs(table_) do
    if value ~= nil and value ~= json.null then
      if type(value) ~= "table" or #value > 0 then
        out[key] = value
      end
    end
  end
  return out
end

--- Build the request body. Empty fields are omitted so we never send `tools: []`.
function M.body(request)
  local model = request.model
  local options = model.options or {}
  -- Per-request generation settings win over the provider defaults.
  local generation = request.generation or {}

  local body = compact({
    model = model.id,
    messages = request.messages or {},
    tools = request.tools and #request.tools > 0 and request.tools or nil,
    tool_choice = request.tool_choice,
    stream = request.stream and true or nil,
    max_tokens = generation.maxTokens or options.maxTokens,
    temperature = generation.temperature or options.temperature,
    top_p = generation.topP or options.topP,
    frequency_penalty = generation.frequencyPenalty,
    presence_penalty = generation.presencePenalty,
    seed = generation.seed,
    stop = generation.stop,
    reasoning_effort = options.reasoningEffort,
    store = options.store,
    prompt_cache_key = options.promptCacheKey,
  })

  if request.stream then
    body.stream_options = { include_usage = true }
  end
  return body
end

local function requestHeaders(model)
  local headers = {
    ["content-type"] = "application/json",
    ["accept"] = "text/event-stream",
  }
  if model.apiKey and model.apiKey ~= "" then
    headers["authorization"] = "Bearer " .. model.apiKey
  end
  for key, value in pairs(model.headers or {}) do
    headers[key:lower()] = value
  end
  headers["content-type"] = headerValue(model, "content-type", headers["content-type"])
  return headers
end

--- Collapse streamed deltas into the same shape the non-streamed path returns.
local function fromStream(response, onDelta)
  onDelta = onDelta or function() end
  local content, reasoning = {}, {}
  local toolCalls = {}
  local finish, usage

  for _, frame in ipairs(http.parseSse(response.body)) do
    local event = json.decode(frame)
    if type(event) == "table" then
      if event.usage and type(event.usage) == "table" then
        usage = event.usage
      end
      local choice = (event.choices or {})[1]
      if type(choice) == "table" then
        if type(choice.finish_reason) == "string" then
          finish = choice.finish_reason
        end
        local delta = choice.delta
        if type(delta) == "table" then
          if type(delta.reasoning_content) == "string" then
            reasoning[#reasoning + 1] = delta.reasoning_content
          end
          if type(delta.content) == "string" then
            content[#content + 1] = delta.content
            onDelta(delta.content)
          end
          for _, call in ipairs(delta.tool_calls or {}) do
            local index = call.index or (#toolCalls)
            local entry = toolCalls[index + 1] or { name = "", arguments = "" }
            if type(call.id) == "string" and call.id ~= "" then
              entry.id = call.id
            end
            if type(call["function"]) == "table" then
              if type(call["function"].name) == "string" and call["function"].name ~= "" then
                entry.name = entry.name .. call["function"].name
              end
              if type(call["function"].arguments) == "string" then
                entry.arguments = entry.arguments .. call["function"].arguments
              end
            end
            toolCalls[index + 1] = entry
          end
        end
      end
    end
  end

  return { content = table.concat(content), reasoning = table.concat(reasoning), toolCalls = toolCalls, finish = finish, usage = usage }
end

--- Normalise a non-streamed choice.
local function fromChoice(choice, usage)
  local message = choice.message
  local toolCalls = {}
  for index, call in ipairs(message.tool_calls or {}) do
    toolCalls[index] = {
      id = call.id,
      name = (call["function"] or {}).name,
      arguments = (call["function"] or {}).arguments or "",
    }
  end
  return {
    content = type(message.content) == "string" and message.content or "",
    reasoning = type(message.reasoning_content) == "string" and message.reasoning_content or "",
    toolCalls = toolCalls,
    finish = choice.finish_reason,
    usage = usage,
  }
end

--- Map the provider's finish_reason, mirroring opencode's translation table.
local function mapFinish(reason, hasToolCalls)
  local mapped = M.FINISH[reason or ""]
  if not mapped then
    return "unknown"
  end
  -- Many OpenAI-compatible servers report "stop" even when they emitted tool calls.
  if mapped == "stop" and hasToolCalls then
    return "tool-calls"
  end
  return mapped
end

--- Translate provider usage into the project's token shape.
local function mapUsage(usage)
  if type(usage) ~= "table" then
    return nil
  end
  local input = usage.prompt_tokens or 0
  local output = usage.completion_tokens or 0
  local cached = (usage.prompt_tokens_details or {}).cached_tokens
  local reasoning = (usage.completion_tokens_details or {}).reasoning_tokens
  return {
    input = input,
    output = output,
    reasoning = reasoning or 0,
    cacheRead = cached or 0,
    cacheWrite = 0,
    total = usage.total_tokens or (input + output),
  }
end

--- Run one chat completion.
--
-- `request.messages` is a list of already-lowered OpenAI wire messages, `request.tools`
-- a list of `{ type = "function", function = { name, description, parameters } }`.
-- `options.onDelta` streams text when the request asked for `stream`.
--
-- Returns a normalized result table, or `nil, message` on failure.
function M.chat(request, options)
  options = options or {}
  local model = request.model
  local stream = request.stream and true or false

  local response, err = http.postJson(provider.url(model, "/chat/completions"), M.body(request), {
    headers = requestHeaders(model),
    timeout = options.timeout or (model.options or {}).timeout or http.DEFAULT_TIMEOUT,
    maxBytes = options.maxBytes or 8 * 1024 * 1024,
    -- A streamed body is an event stream, not a JSON document, so it is left
    -- undecoded here and split into frames by `fromStream`.
    decode = not stream,
  })
  if not response then
    return nil, err
  end

  local result
  if stream then
    result = fromStream(response, options.onDelta)
  else
    local choice = (response.data.choices or {})[1]
    if type(choice) ~= "table" or type(choice.message) ~= "table" then
      return nil, "the response contained no choices"
    end
    result = fromChoice(choice, response.data.usage)
    if options.onDelta and #result.content > 0 then
      options.onDelta(result.content)
    end
  end

  result.finish = mapFinish(result.finish, #result.toolCalls > 0)
  result.usage = mapUsage(result.usage)
  result.raw = response.data
  return result
end

--- Decode the JSON arguments string a model attached to a tool call.
function M.parseArguments(raw)
  if raw == nil or raw == "" then
    return {}
  end
  if type(raw) == "table" then
    return json.dropNulls(raw)
  end
  local decoded, err = json.decode(raw)
  if type(decoded) ~= "table" then
    return nil, err or "arguments were not a JSON object"
  end
  return json.dropNulls(decoded)
end

return M

end

-- src/permission.lua
__sources["permission"] = function(...)
do end
-- Permission rules and the interactive approval prompt.
--
-- Evaluation follows opencode: the last matching rule across the ruleset wins,
-- and the default when nothing matches is "ask". Approvals granted for the
-- session are appended to the session ruleset so later calls are silent.

local util = require("util")
local env = require("environment")

local M = {}

M.ALLOW, M.DENY, M.ASK = "allow", "deny", "ask"

--- Last rule matching both permission and pattern, or an implicit "ask".
function M.evaluate(permission, pattern, ...)
  local rulesets = { ... }
  local found = nil
  for _, ruleset in ipairs(rulesets) do
    for _, rule in ipairs(ruleset or {}) do
      local rulePermission = rule.permission or rule[1] or "*"
      local rulePattern = rule.pattern or rule[2] or "*"
      if util.wildcard(permission, rulePermission) and util.wildcard(pattern, rulePattern) then
        found = { action = rule.action or rule[3] or M.ASK, permission = permission, pattern = pattern }
      end
    end
  end
  return found or { action = M.ASK, permission = permission, pattern = pattern }
end

--- Check a set of patterns at once, returning "allow", "deny" or "ask".
function M.evaluateAll(permission, patterns, ...)
  local needsAsk = false
  for _, pattern in ipairs(patterns) do
    local rule = M.evaluate(permission, pattern, ...)
    if rule.action == M.DENY then
      return M.DENY, pattern
    end
    if rule.action == M.ASK then
      needsAsk = true
    end
  end
  if needsAsk then
    return M.ASK
  end
  return M.ALLOW
end

--- Ask the operator one question, returning "n" at end of input.
--
-- The answer comes from CraftOS's `read`, not from a screen: `term` has no
-- `readLine`, so a screen answered nil here, and nil was read as "no" -- which
-- made every `ask` rule deny silently, with no question ever put to anyone. An
-- unattended denial is the safe direction to fail, but a prompt that cannot be
-- seen is not a prompt.
local function prompt(question, monitor)
  if not monitor or not term or not env.isCC then
    return "n"
  end
  monitor.write(question)
  local line = env.readLine()
  if line == nil then
    return "n"
  end
  return util.trim(line):lower()
end

--- Put the question on screen and get the answer back, whichever screen this is.
--
-- A UI screen is asked itself, because that is the whole reason it exists: `read`
-- draws nothing, so the question went to a monitor nobody was reading while the
-- answer was typed blind at the terminal. A plain screen is not, and the question
-- goes down the path above unchanged -- `--plain` is meant to be the screen this
-- program had before, byte for byte, and a change to its prompt would be a change
-- to what it is for.
--
-- The `ask` method is the interface, and the check is for its existence rather
-- than for this module knowing what kind of screen it has been handed.
local function askOn(screen, title, permission, patterns)
  if not screen or type(screen.ask) ~= "function" then
    return nil
  end
  local reply = screen:ask({ title = title, permission = permission, patterns = patterns })
  if reply == nil then
    return "n"
  end
  return util.trim(reply):lower()
end

--- Ask the operator to approve `permission` for `patterns`.
--
-- Returns "allow", "deny", or "feedback:<message>" — a rejection carrying the
-- operator's explanation, which the agent loop feeds back to the model so it can
-- correct course instead of retrying blindly.
function M.ask(input)
  if input.ruleset then
    local action = M.evaluateAll(input.permission, input.patterns, input.ruleset)
    if action ~= M.ASK then
      return action
    end
  end

  local patterns = input.patterns or { "*" }
  local monitor = input.monitor

  -- The plain path's question, a function so that a UI screen never builds it: the
  -- text here is four lines for a dialog, and a dialog that renders it as a dialog
  -- is not a dialog with a header, buttons and a hint line.
  local function plainQuestion()
    local shown = {}
    for index, pattern in ipairs(patterns) do
      if index > 4 then
        shown[#shown + 1] = string.format("  ...and %d more", #patterns - 4)
        break
      end
      shown[#shown + 1] = "  " .. pattern
    end

    local lines = { string.format("Permission required: %s", input.permission), table.concat(shown, "\n") }
    if input.title then
      lines[#lines + 1] = input.title
    end
    lines[#lines + 1] = "[y] once  [a] always  [n] no"
    return table.concat(lines, "\n") .. "\n> "
  end

  local reply = askOn(monitor, input.title, input.permission, patterns)
  if reply == nil then
    reply = prompt(plainQuestion(), monitor)
  end
  if reply == "y" or reply == "yes" then
    return M.ALLOW
  end
  if reply == "a" or reply == "always" then
    for _, pattern in ipairs(input.always or patterns) do
      input.session.permission[#input.session.permission + 1] = {
        permission = input.permission,
        pattern = pattern,
        action = M.ALLOW,
      }
    end
    return M.ALLOW
  end
  if reply == "n" or reply == "no" or reply == "" then
    return M.DENY
  end
  return "feedback:" .. reply
end

--- Normalise a config permission entry into a ruleset.
function M.ruleset(entries)
  local out = {}
  for _, entry in ipairs(entries or {}) do
    if type(entry) == "string" then
      out[#out + 1] = { permission = entry, pattern = "*", action = M.ALLOW }
    elseif type(entry) == "table" then
      out[#out + 1] = {
        permission = entry.permission or "*",
        pattern = entry.pattern or "*",
        action = entry.action or M.ALLOW,
      }
    end
  end
  return out
end

return M

end

-- src/truncate.lua
__sources["truncate"] = function(...)
do end
-- Tool output truncation.
--
-- Mirrors opencode: output over the line or byte limit is written to
-- `opencode/tool-output/` and the model gets a preview plus a pointer to the full
-- text. Direction matters — shell output is a tail so the most recent lines stay
-- visible, everything else is a head.

local env = require("environment")
local util = require("util")

local M = {}

M.MAX_LINES = 2000
M.MAX_BYTES = 50 * 1024

function M.directory()
  return env.combine(env.cwd(), "opencode", "tool-output")
end

--- Write `text` to the truncation directory and return the file path.
function M.write(text)
  local path = env.combine(M.directory(), util.id("tool") .. ".txt")
  if not env.mkdirs(M.directory()) then
    return nil
  end
  if env.write(path, text) then
    return path
  end
  return nil
end

--- Keep the first `maxLines` lines / `maxBytes` bytes of `text`.
local function head(text, maxLines, maxBytes)
  local kept, bytes = {}, 0
  for index, line in ipairs(util.lines(text)) do
    if index > maxLines then
      return table.concat(kept, "\n"), index - 1, "lines"
    end
    local size = #line + 1
    if bytes + size > maxBytes then
      return table.concat(kept, "\n"), nil, "bytes"
    end
    bytes = bytes + size
    kept[#kept + 1] = line
  end
  return text, nil, nil
end

--- Keep the last `maxLines` lines / `maxBytes` bytes of `text`.
local function tail(text, maxLines, maxBytes)
  local lines = util.lines(text)
  local kept, bytes = {}, 0
  for index = #lines, 1, -1 do
    if #kept >= maxLines then
      return table.concat(kept, "\n"), index, "lines"
    end
    local size = #lines[index] + 1
    if bytes + size > maxBytes then
      return table.concat(kept, "\n"), nil, "bytes"
    end
    bytes = bytes + size
    table.insert(kept, 1, lines[index])
  end
  return text, nil, nil
end

--- Clamp `text` to the limits, saving the full output when it does not fit.
--
-- Returns `text` unchanged, or the preview followed by a note naming the file
-- that holds the complete output.
function M.output(text, options)
  options = options or {}
  local maxLines = options.maxLines or M.MAX_LINES
  local maxBytes = options.maxBytes or M.MAX_BYTES
  local direction = options.direction or "head"

  if #text <= maxBytes and #util.lines(text) <= maxLines + 1 then
    return text
  end

  -- A single `and ... or ...` expression would collapse to one value, so the
  -- branch is chosen first and the result is unpacked separately.
  local preview, removed, unit
  if direction == "tail" then
    preview, removed, unit = tail(text, maxLines, maxBytes)
  else
    preview, removed, unit = head(text, maxLines, maxBytes)
  end
  local path = M.write(text)
  if not path then
    return preview
  end

  local note = string.format(
    "The tool call succeeded but the output was truncated. Full output saved to: %s\nUse Grep to search the full content or Read with offset/limit to view specific sections.",
    path
  )
  if direction == "tail" then
    return string.format("...%s %s truncated...\n\n%s\n\n%s", removed or "many", unit or "lines", note, preview)
  end
  return string.format("%s\n\n...%s %s truncated...\n\n%s", preview, removed or "many", unit or "lines", note)
end

return M

end

-- src/tool/bash.lua
__sources["tool/bash"] = function(...)
do end
-- The `bash` tool: run a command in the ComputerCraft shell.
--
-- CC's shell is not a POSIX shell, so the command runs through `shell.run`. Output
-- is redirected to a temp file so it can be captured and tail-truncated without
-- flooding the terminal. When the `shell` builtin exists the command is spawned
-- with `bg`, which gives us a pid to poll for the timeout and to kill.

local env = require("environment")
local util = require("util")
local truncate = require("truncate")
local registry = require("tool/registry")

local DEFAULT_TIMEOUT_MS = 120000

local DESCRIPTION = [[Executes a command in the ComputerCraft shell with an optional timeout.

Be aware: this is the ComputerCraft shell, not bash. Supported syntax is limited:
- pipes (|), redirection (> >> 2>&1), background (&), and simple sequencing with ;
- builtins: cd, dir/ls, mkdir, rm/del, cp, mv, type/cat, echo, clear, exit, and
  any program installed under /rom/programs or on PATH
- `&&` is not supported; chain dependent commands in a single call separated by `;`
  and check the output

Working directory:
All commands run in the session working directory. Use the `workdir` parameter
instead of a `cd` prefix, so the permission check sees the real target path.

Usage notes:
  - The command argument is required.
  - You can specify an optional timeout in milliseconds. Commands time out after
    120000ms by default.
  - Output longer than the truncation limit is tail-truncated, so the most recent
    lines stay visible and the full text is saved to a file you can grep or read.
  - Do not use this tool for reading, writing, or searching files; use the Read,
    Write, Edit, Glob, and Grep tools for those.
  - You can issue several independent bash calls in one message; they run in order
    but a single call per command keeps the output attributable.

# ComputerCraft specifics
- Programs are Lua programs in /rom/programs or in a directory on PATH. A computer
  is limited in CPU and memory: prefer small, bounded commands over large scans.
- `shell.run` returns immediately for backgrounded commands; the output file may
  still be growing when the tool returns.
- File paths always start with `/` and use `/` as the separator. There is no
  current-directory-relative shorthand, and there is no `which`-free shell.
- The `edit`/`write` tools are the right way to create or modify files. Using
  redirection through bash works but is not tracked by the permission system.]]

local function quote(value)
  return env.quote(value)
end

--- Commands whose first token changes the working directory, exempt from
--- permission checks because the workdir parameter covers that case.
local CD_COMMANDS = { cd = true, chdir = true, pushd = true, popd = true }

--- Split a command line on `;` so each segment can be permission checked.
local function segments(command)
  local out = {}
  for piece in command:gmatch("[^;]+") do
    local trimmed = util.trim(piece)
    if trimmed ~= "" then
      out[#out + 1] = trimmed
    end
  end
  return out
end

--- Derive the permission pattern for a command: `git status` -> `git status`,
--- and the always-pattern `git *` that covers its subcommands.
local function arityPatterns(segment)
  local tokens = {}
  for token in segment:gmatch("%S+") do
    tokens[#tokens + 1] = token:gsub("^%s+", "")
  end
  local name = tokens[1] and tokens[1]:gsub("[;&|].*$", "")
  if not name or name == "" then
    return segment, nil
  end
  local always = name
  if #tokens > 1 and not tokens[2]:match("^%-") then
    always = name .. " " .. tokens[2]
  end
  return segment, always .. " *"
end

--- Poll a spawned job until it finishes, the timeout expires, or we are aborted.
-- Returns whether the job timed out and whether it was aborted; the exit code is
-- read from `shell.getJobInfoEx`, which retains info after the job is reaped.
local function waitForJob(pid, timeoutMs, ctx)
  local deadline = os.time() + math.ceil(timeoutMs / 1000)
  while shell.getJobInfo(pid) do
    if os.time() >= deadline then
      shell.kill(pid)
      return true, false
    end
    if ctx and ctx.aborted and ctx.aborted() then
      shell.kill(pid)
      return false, true
    end
    util.sleep(0.1)
  end
  local info = shell.getJobInfoEx and shell.getJobInfoEx(pid)
  return false, false, type(info) == "table" and info.exitCode or nil
end

--- Run `command`, returning its exit code, captured output, and any failure note.
local function run(command, workdir, timeoutMs, ctx)
  local outputPath = env.combine(truncate.directory(), util.id("bash") .. ".out")
  if not env.mkdirs(truncate.directory()) then
    error("could not create the output directory " .. truncate.directory(), 0)
  end

  local line = command
  if workdir and workdir ~= "" then
    line = "cd " .. quote(workdir) .. " ; " .. line
  end
  line = line .. " > " .. quote(outputPath) .. " 2>&1"

  local notes = {}
  local exitCode

  if shell.which and shell.which("shell") and shell.getJobInfo and shell.getJobInfoEx then
    local pid = shell.run("bg shell " .. quote(line))
    if type(pid) ~= "number" or pid <= 0 then
      env.remove(outputPath)
      error("could not start the command", 0)
    end
    local timedOut, aborted
    timedOut, aborted, exitCode = waitForJob(pid, timeoutMs, ctx)
    if timedOut then
      notes[#notes + 1] = string.format(
        "the command was terminated after exceeding the timeout of %d ms. Retry with a larger timeout if it was not waiting for input.",
        timeoutMs
      )
    end
    if aborted then
      notes[#notes + 1] = "the user aborted the command"
    end
  else
    -- No cancellable job handle available. The command still runs with its output
    -- captured, but on timeout it cannot be killed and is reported as abandoned.
    local abandoned = false
    local coroutine = coroutine.create(function()
      exitCode = shell.run(line)
    end)
    local timer = os.startTimer(math.ceil(timeoutMs / 1000))
    local event = parallel.waitForAny({ coroutine, timer })
    if event == timer then
      abandoned = true
      notes[#notes + 1] = string.format(
        "the command was still running after the timeout of %d ms and was abandoned; its output file may still be growing.",
        timeoutMs
      )
    end
    if abandoned and shell.kill then
      shell.kill(tostring(coroutine))
    end
  end

  local captured = env.read(outputPath) or ""
  env.remove(outputPath)
  return exitCode, captured, notes
end

registry.define({
  id = "bash",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      command = { type = "string", description = "The command to execute" },
      timeout = {
        type = "number",
        description = "Optional timeout in milliseconds. Defaults to 120000.",
      },
      workdir = {
        type = "string",
        description = "The directory to run the command in. Defaults to the session working directory. Use this instead of a cd prefix.",
      },
    },
    required = { "command" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local command = args.command
    if type(command) ~= "string" or util.trim(command) == "" then
      error("The command argument is required.", 0)
    end
    local timeout = tonumber(args.timeout) or DEFAULT_TIMEOUT_MS
    if timeout < 0 then
      error("Invalid timeout value: " .. tostring(args.timeout) .. ". Timeout must be a positive number.", 0)
    end
    local workdir = args.workdir and env.resolve(args.workdir, ctx.cwd) or ctx.cwd

    local patterns, always = {}, {}
    for _, segment in ipairs(segments(command)) do
      local name = segment:match("^(%S+)")
      if not (name and CD_COMMANDS[name]) then
        local pattern, alwaysPattern = arityPatterns(segment)
        patterns[#patterns + 1] = pattern
        if alwaysPattern then
          always[#always + 1] = alwaysPattern
        end
      end
    end
    if not env.contains(ctx.root, workdir) then
      registry.guard(ctx, "external_directory", { workdir .. "/*" }, { workdir .. "/*" },
        "working outside " .. ctx.root)
    end
    registry.guard(ctx, "bash", patterns, always, command)

    local exitCode, captured, notes = run(command, workdir, timeout, ctx)

    local limits = registry.limits(ctx.config)
    local output = truncate.output(captured, {
      maxLines = limits.maxLines,
      maxBytes = limits.maxBytes,
      direction = "tail",
    })
    if output == "" then
      output = "(no output)"
    end
    if #notes > 0 then
      output = output .. "\n\n<shell_metadata>\n" .. table.concat(notes, "\n") .. "\n</shell_metadata>"
    end

    return {
      title = command,
      metadata = { output = output, exit = exitCode },
      output = output,
    }
  end,
})

return true

end

-- src/tool/read.lua
__sources["tool/read"] = function(...)
do end
-- The `read` tool: file contents or a directory listing.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DEFAULT_LIMIT = 2000
local MAX_LINE_LENGTH = 2000
local MAX_BYTES = 50 * 1024
local SAMPLE_BYTES = 4096

local DESCRIPTION = [[Read a file or directory from the filesystem. If the path does not exist, an error is returned.

Usage:
- The filePath parameter should be an absolute path. Relative paths resolve against
  the session working directory.
- By default, this tool returns up to 2000 lines from the start of the file.
- The offset parameter is the line number to start from (1-indexed).
- To read later sections, call this tool again with a larger offset.
- Use the grep tool to find specific content in large files or files with long lines.
- If you are unsure of the correct file path, use the glob tool to look up filenames.
- Contents are returned with each line prefixed by its line number as `<line>: <content>`.
  For example, a file containing "foo" returns "1: foo". For directories, entries are
  returned one per line, with a trailing `/` for subdirectories.
- Any line longer than 2000 characters is truncated.
- Read a larger window rather than many small slices; each call costs context.]]

local BINARY_EXTENSIONS = {
  zip = true, tar = true, gz = true, bz2 = true, xz = true, ["7z"] = true,
  exe = true, dll = true, so = true, class = true, jar = true, war = true,
  doc = true, docx = true, xls = true, xlsx = true, ppt = true, pptx = true,
  odt = true, ods = true, odp = true, bin = true, dat = true, obj = true,
  o = true, a = true, lib = true, wasm = true, pyc = true, pyo = true,
  png = true, jpg = true, jpeg = true, gif = true, webp = true, pdf = true,
  nbt = true, wav = true, ogg = true,
}

--- Extension-based first, then a content sample: a NUL byte or a high ratio of
--- non-printable bytes means we should not hand this to the model as text.
local function isBinary(path, sample)
  local extension = path:match("%.([%w]+)$")
  if extension and BINARY_EXTENSIONS[extension:lower()] then
    return true
  end
  if not sample or #sample == 0 then
    return false
  end
  if sample:find("\0", 1, true) then
    return true
  end
  local printable = 0
  for index = 1, #sample do
    local byte = sample:byte(index)
    if byte == 9 or byte == 10 or byte == 13 or (byte >= 32 and byte < 127) or byte >= 128 then
      printable = printable + 1
    end
  end
  return printable / #sample < 0.7
end

--- Suggest up to three sibling names that resemble the missing file's basename.
local function didYouMean(path)
  local directory = env.dirname(path)
  local base = env.basename(path)
  local suggestions = {}
  for _, name in ipairs(env.listDir(directory)) do
    if util.fuzzyContains(name, base) or util.fuzzyContains(base, name) then
      suggestions[#suggestions + 1] = env.combine(directory, name)
      if #suggestions == 3 then
        break
      end
    end
  end
  return suggestions
end

local function listDirectory(path, args)
  local names = env.listDir(path)
  local offset = math.max(1, tonumber(args.offset) or 1)
  local limit = tonumber(args.limit) or DEFAULT_LIMIT
  local start = offset - 1

  local entries = {}
  for index, name in ipairs(names) do
    if index > start and #entries < limit then
      local full = env.combine(path, name)
      entries[#entries + 1] = (env.isDir(full) and name .. "/" or name)
    end
  end

  local shown = #entries
  local more = start + shown < #names
  local footer = more
      and string.format(
        "\n(Showing %d of %d entries. Use 'offset' parameter to read beyond entry %d)",
        shown, #names, offset + shown
      )
    or string.format("\n(%d entries)", #names)

  return {
    title = path,
    metadata = { count = #names },
    output = table.concat({ "<path>" .. path .. "</path>", "<type>directory</type>", "<entries>",
      table.concat(entries, "\n"), footer, "</entries>" }, "\n"),
  }
end

registry.define({
  id = "read",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path to the file or directory to read" },
      offset = { type = "number", description = "The line number to start reading from (1-indexed)" },
      limit = { type = "number", description = "The maximum number of lines to read (defaults to 2000)" },
    },
    required = { "filePath" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "reading outside " .. ctx.root)
    end
    registry.guard(ctx, "read", { path }, { path })

    if env.isDir(path) then
      return listDirectory(path, args)
    end
    if not env.exists(path) then
      local suggestions = didYouMean(path)
      if #suggestions > 0 then
        error(string.format("File not found: %s\n\nDid you mean one of these?\n%s", path, table.concat(suggestions, "\n")), 0)
      end
      error("File not found: " .. path, 0)
    end

    local content, cut = env.readLimited(path, MAX_BYTES)
    if isBinary(path, content:sub(1, SAMPLE_BYTES)) then
      error("Cannot read binary file: " .. path, 0)
    end

    local lines = util.lines(content)
    local count = #lines
    local offset = math.max(1, tonumber(args.offset) or 1)
    local limit = tonumber(args.limit) or DEFAULT_LIMIT

    if count < offset and not (count == 0 and offset == 1) then
      error(string.format("Offset %d is out of range for this file (%d lines)", offset, count), 0)
    end

    local body = {}
    local bytes = 0
    local index = offset
    while index <= count and #body < limit do
      local line = lines[index]
      if bytes + #line > MAX_BYTES then
        cut = true
        break
      end
      if #line > MAX_LINE_LENGTH then
        line = line:sub(1, MAX_LINE_LENGTH) .. string.format("... (line truncated to %d chars)", MAX_LINE_LENGTH)
      end
      bytes = bytes + #line
      body[#body + 1] = string.format("%d: %s", index, line)
      index = index + 1
    end

    local last = index - 1
    local footer
    if cut then
      footer = string.format(
        "\n\n(Output capped at %s. Showing lines %d-%d. Use offset=%d to continue.)",
        util.byteLabel(MAX_BYTES), offset, last, last + 1
      )
    elseif last < count then
      footer = string.format(
        "\n\n(Showing lines %d-%d of %d. Use offset=%d to continue.)",
        offset, last, count, last + 1
      )
    else
      footer = string.format("\n\n(End of file - total %d lines)", count)
    end

    return {
      title = path,
      metadata = { lines = count },
      output = string.format("<path>%s</path>\n<type>file</type>\n<content>\n%s%s\n</content>",
        path, table.concat(body, "\n"), footer),
    }
  end,
})

return true

end

-- src/tool/write.lua
__sources["tool/write"] = function(...)
do end
-- The `write` tool: create or overwrite a file.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DESCRIPTION = [[Writes a file to the filesystem.

Usage:
- This tool overwrites the existing file at the provided path.
- Prefer editing an existing file over rewriting it; use the Edit tool for changes
  to part of a file.
- Parent directories are created automatically.
- Do not proactively create documentation files (*.md) or README files. Only create
  documentation when explicitly requested.
- Only use emojis if the user explicitly requests it.
- Text files are written as UTF-8 with \n line endings. A byte order mark already
  present in the file is preserved.]]

registry.define({
  id = "write",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path of the file to write" },
      content = { type = "string", description = "The content to write to the file" },
    },
    required = { "filePath", "content" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    local content = args.content
    if type(content) ~= "string" then
      error("The content argument is required and must be a string.", 0)
    end
    if env.isDir(path) then
      error("Path is a directory, not a file: " .. path, 0)
    end
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "writing outside " .. ctx.root)
    end
    registry.guard(ctx, "edit", { path }, { path }, "write " .. path)

    local existed = env.exists(path)
    local bom = ""
    if existed then
      local existing = env.readLimited(path, 3) or ""
      if existing:sub(1, 3) == "\239\187\191" then
        bom = "\239\187\191"
      end
    end

    if not env.mkdirs(env.dirname(path)) then
      error("Could not create the directory " .. env.dirname(path), 0)
    end
    if not env.write(path, bom .. content) then
      error("Could not write " .. path, 0)
    end

    local action = existed and "Updated" or "Created"
    return {
      title = action .. " " .. path,
      metadata = { path = path, created = not existed },
      output = string.format("%s file successfully: %s (%d bytes)", action, path, #bom + #content),
    }
  end,
})

return true

end

-- src/tool/edit.lua
__sources["tool/edit"] = function(...)
do end
-- The `edit` tool: exact string replacement.
--
-- Ports the replacer chain from opencode's edit tool. A model rarely produces a
-- byte-exact match because of indentation or line-ending drift, so the chain
-- widens the search progressively rather than failing on the first mismatch. Each
-- replacer yields candidate spans; a candidate is only accepted when it is unique
-- (unless replaceAll is set), which is what turns an ambiguous edit into an error
-- instead of a wrong write.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DESCRIPTION = [[Performs exact string replacements in files.

Usage:
- You must have read the file at least once in this conversation before editing, so
  that the content you pass in matches what is really there.
- When copying text out of Read output, keep the exact indentation that appears after
  the `N: ` line-number prefix. Never include the prefix itself in oldString or
  newString.
- Prefer editing an existing file over rewriting it. Do not create new files unless
  explicitly required.
- The edit FAILS if oldString is not found, with "Could not find oldString in the file".
- The edit FAILS if oldString appears more than once, telling you to add surrounding
  context or to set replaceAll.
- Use replaceAll for renaming a symbol across a file.]]

--- Byte offsets of every occurrence of `search` in `content`.
local function occurrences(content, search)
  local positions = {}
  if search == "" then
    return positions
  end
  local from = 1
  while true do
    local start = content:find(search, from, true)
    if not start then
      return positions
    end
    positions[#positions + 1] = start
    from = start + 1
  end
end

--- Refuse a fuzzy match that would swallow much more of the file than was asked for.
local function isDisproportionate(search, oldString)
  local oldLines = #util.lines(oldString)
  local searchLines = #util.lines(search)
  if searchLines >= math.max(oldLines + 3, oldLines * 2) then
    return true
  end
  if oldLines == 1 then
    return false
  end
  return #util.trim(search) > math.max(#util.trim(oldString) + 500, #util.trim(oldString) * 4)
end

--- Spans where `needle`'s lines match `haystack`'s lines, comparing trimmed text.
-- Returns a list of `{ start, finish }` byte ranges into `haystack`.
local function matchByTrimmedLine(haystack, needle)
  local haystackLines = util.lines(haystack)
  local needleLines = util.lines(needle)
  local spans = {}
  if #needleLines == 0 or #haystackLines < #needleLines then
    return spans
  end

  local offsets, running = {}, 1
  for _, line in ipairs(haystackLines) do
    offsets[#offsets + 1] = running
    running = running + #line + 1
  end

  for index = 1, #haystackLines - #needleLines + 1 do
    local matched = true
    for offset = 1, #needleLines do
      if util.trim(haystackLines[index + offset - 1]) ~= util.trim(needleLines[offset]) then
        matched = false
        break
      end
    end
    if matched then
      local start = offsets[index]
      local last = index + #needleLines - 1
      local finish = offsets[last] + #haystackLines[last] - 1
      spans[#spans + 1] = { start = start, finish = finish }
    end
  end
  return spans
end

--- Collapse whitespace runs, returning the collapsed text and a map back to the original.
local function collapseWhitespace(text)
  local out, map = {}, {}
  local index, count = 1, 0
  while index <= #text do
    local char = text:sub(index, index)
    if char:match("%s") then
      while index <= #text and text:sub(index, index):match("%s") do
        index = index + 1
      end
      out[#out + 1] = " "
      count = count + 1
      map[count] = index - 1
    else
      out[#out + 1] = char
      count = count + 1
      map[count] = index
      index = index + 1
    end
  end
  return table.concat(out), map
end

local function stripIndent(text)
  local lines = util.lines(text)
  local shortest = nil
  for _, line in ipairs(lines) do
    local stripped = line:match("^%s*")
    if #line > #stripped and (not shortest or #stripped < #shortest) then
      shortest = #stripped
    end
  end
  if not shortest or shortest == 0 then
    return text
  end
  local out = {}
  for _, line in ipairs(lines) do
    out[#out + 1] = line:sub(math.min(shortest + 1, #line + 1))
  end
  return table.concat(out, "\n")
end

--- Candidate spans to try, in widening order of leniency.
local function candidates(content, oldString)
  local out = {}

  for _, position in ipairs(occurrences(content, oldString)) do
    out[#out + 1] = content:sub(position, position + #oldString - 1)
  end

  for _, span in ipairs(matchByTrimmedLine(content, oldString)) do
    out[#out + 1] = content:sub(span.start, span.finish)
  end

  local collapsedOld = stripIndent(oldString)
  if collapsedOld ~= oldString then
    for _, span in ipairs(matchByTrimmedLine(content, collapsedOld)) do
      out[#out + 1] = content:sub(span.start, span.finish)
    end
  end

  local collapsedContent, map = collapseWhitespace(content)
  local collapsedNeedle = collapseWhitespace(oldString)
  local at = collapsedContent:find(collapsedNeedle, 1, true)
  if at and at > 1 then
    local start = map[at] or 1
    local finish = map[at + #collapsedNeedle - 1] or #content
    if finish >= start then
      out[#out + 1] = content:sub(start, math.min(finish, #content))
    end
  end

  return out
end

--- Replace every occurrence of `search`, treating both sides as plain text.
local function gsubLiteral(content, search, replacement)
  local escaped = search:gsub("([^%w])", "%%%1")
  local out = content:gsub(escaped, function()
    return replacement
  end)
  return out
end

--- Apply the replacement, raising a model-readable message on ambiguity.
local function replace(content, oldString, newString, replaceAll)
  if oldString == newString then
    error("No changes to apply: oldString and newString are identical.", 0)
  end
  if util.trim(oldString) == "" then
    error(
      "oldString cannot be empty when editing an existing file. Provide the exact text to replace, or use write for an intentional full-file replacement.",
      0
    )
  end

  local found, ambiguous = false, false
  for _, search in ipairs(candidates(content, oldString)) do
    local positions = occurrences(content, search)
    if #positions > 0 then
      found = true
      if isDisproportionate(search, oldString) then
        error(
          "Refusing replacement because the matched span is much larger than oldString. Re-read the file and provide the full exact oldString for the intended replacement.",
          0
        )
      end
      if replaceAll then
        return gsubLiteral(content, search, newString)
      end
      if #positions == 1 then
        local start = positions[1]
        return content:sub(1, start - 1) .. newString .. content:sub(start + #search)
      end
      ambiguous = true
    end
  end

  if ambiguous then
    error("Found multiple matches for oldString. Provide more surrounding lines in oldString to identify the correct match.", 0)
  end
  error("Could not find oldString in the file. It must match exactly, including whitespace, indentation, and line endings.", 0)
end

registry.define({
  id = "edit",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path of the file to modify" },
      oldString = { type = "string", description = "The text to replace" },
      newString = { type = "string", description = "The text to replace it with. Must differ from oldString." },
      replaceAll = { type = "boolean", description = "Replace every occurrence of oldString. Defaults to false." },
    },
    required = { "filePath", "oldString", "newString" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    local oldString, newString = args.oldString, args.newString
    if type(oldString) ~= "string" or type(newString) ~= "string" then
      error("The oldString and newString arguments are required and must be strings.", 0)
    end
    if oldString == newString then
      error("No changes to apply: oldString and newString are identical.", 0)
    end
    if env.isDir(path) then
      error("Path is a directory, not a file: " .. path, 0)
    end
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "editing outside " .. ctx.root)
    end

    if not env.exists(path) then
      if util.trim(oldString) ~= "" then
        error("File " .. path .. " not found", 0)
      end
      registry.guard(ctx, "edit", { path }, { path }, "create " .. path)
      if not env.mkdirs(env.dirname(path)) then
        error("Could not create the directory " .. env.dirname(path), 0)
      end
      env.write(path, newString)
      return { title = "Created " .. path, metadata = { path = path, created = true },
        output = "Created file successfully: " .. path }
    end

    registry.guard(ctx, "edit", { path }, { path }, "edit " .. path)

    local content = env.read(path) or ""
    local bom = ""
    if content:sub(1, 3) == "\239\187\191" then
      bom = "\239\187\191"
      content = content:sub(4)
    end

    local ending = content:find("\r\n", 1, true) and "\r\n" or "\n"
    local normalize = function(text)
      return (text:gsub("\r\n", "\n"):gsub("\n", ending))
    end

    local updated = replace(content, normalize(oldString), normalize(newString), args.replaceAll and true or false)
    if not env.write(path, bom .. updated) then
      error("Could not write " .. path, 0)
    end

    return {
      title = "Edited " .. path,
      metadata = { path = path, created = false },
      output = "Edit applied successfully.",
    }
  end,
})

return true

end

-- src/pattern.lua
__sources["pattern"] = function(...)
do end
-- Pattern matching: glob patterns and a regex-to-Lua translator.
--
-- ComputerCraft has no regex engine, so grep needs a translation layer. The
-- supported subset covers what models actually send in practice: literals,
-- character classes, the standard escapes, quantifiers, groups, alternation, and
-- anchors. Lua patterns have no upper-bounded repeat, so `{n,m}` is expanded into
-- `n` mandatory copies plus `m-n` optional ones.

local M = {}

--- Convert a glob pattern to a Lua pattern. `**` spans directory boundaries.
function M.globToPattern(glob)
  local out = { "^" }
  local index = 1
  while index <= #glob do
    local char = glob:sub(index, index)
    if char == "*" then
      if glob:sub(index, index + 1) == "**" then
        index = index + 1
        if glob:sub(index + 1, index + 1) == "/" then
          -- "**/" spans any number of directories, including none. A lazy
          -- any-character run covers both, and the separator is consumed with
          -- it; Lua has no quantifier for a group, so ".-/" is not expressible.
          out[#out + 1] = ".-"
          index = index + 1
        else
          out[#out + 1] = ".*"
        end
      else
        out[#out + 1] = "[^/]*"
      end
    elseif char == "?" then
      out[#out + 1] = "[^/]"
    elseif char == "[" then
      local close = glob:find("]", index + 2, true)
      if close then
        local body = glob:sub(index + 1, close - 1)
        if body:sub(1, 1) == "!" then
          body = "^" .. body:sub(2)
        end
        out[#out + 1] = "[" .. body .. "]"
        index = close
      else
        out[#out + 1] = "%["
      end
    else
      out[#out + 1] = char:gsub("([%^%$%(%)%%%.%[%]%+%-%*%?])", "%%%1")
    end
    index = index + 1
  end
  out[#out + 1] = "$"
  return table.concat(out)
end

--- True when a path matches a glob pattern, used by the include filters.
function M.matchesGlob(path, glob)
  return M.find({ M.globToPattern(glob) }, path) ~= nil
end

--- Regex character classes. Lua's `%w` is letters and digits only, so `\w` needs
--- the underscore spelled out to match what a model means by a word character.
local CLASSES = {
  d = "%d",
  D = "%D",
  w = "[%w_]",
  W = "[^%w_]",
  s = "%s",
  S = "%S",
  l = "%l",
  u = "%u",
  p = "%p",
  P = "%P",
}

local function escapeLiteral(char)
  return char:gsub("([%^%$%(%)%%%.%[%]%+%-%*%?])", "%%%1")
end

--- Read a `[...]` class starting at `i`, returning its text and the next index.
local function readClass(body, i)
  local close = body:find("]", i + 1, true)
  if not close then
    return nil, i + 1
  end
  local inner = body:sub(i + 1, close - 1)
  if inner:sub(1, 1) == "!" then
    inner = "^" .. inner:sub(2)
  end
  return "[" .. inner .. "]", close + 1
end

--- Read a `{...}` quantifier, returning the min/max counts and the next index.
local function readRepeat(body, i)
  local close = body:find("}", i, true)
  if not close then
    return nil, nil, i + 1
  end
  local inner = body:sub(i + 1, close - 1)
  local min, max = inner:match("^(%d*),(%d*)$")
  if not min then
    return nil, nil, i + 1
  end
  min = min == "" and 0 or tonumber(min)
  max = max == "" and math.huge or tonumber(max)
  if max < min then
    return nil, nil, i + 1
  end
  return min, max, close + 1
end

--- Expand an atom and a quantifier into plain Lua pattern fragments.
local function expand(atom, min, max)
  if min == 0 and max == math.huge then
    return atom .. "*"
  end
  if min == 1 and max == math.huge then
    return atom .. "+"
  end
  if min == 0 and max == 1 then
    return atom .. "?"
  end
  local out = {}
  for _ = 1, min do
    out[#out + 1] = atom
  end
  for _ = min + 1, math.min(max, min + 8) do
    out[#out + 1] = atom .. "?"
  end
  return table.concat(out)
end

--- True when `text` is a single translatable atom, i.e. something a Lua
--- quantifier can be attached to.
local function isSingleAtom(text)
  return #text == 1 or (text:sub(1, 1) == "[" and text:sub(-1) == "]")
end

--- Split a translated fragment into everything but its last atom and that atom
-- with any quantifier stripped, so a new quantifier can be attached to it.
local function splitLastAtom(text)
  local body = text
  while body ~= "" do
    local last = body:sub(-1)
    if last == "*" or last == "+" or last == "?" then
      body = body:sub(1, -2)
    else
      break
    end
  end
  if body:sub(-1) == "]" then
    local head = body:match("^(.*)%[")
    if head then
      return head, body:sub(#head + 1)
    end
  end
  if body:sub(-2, -2) == "%" then
    return body:sub(1, -3), body:sub(-2)
  end
  return body:sub(1, -2), body:sub(-1)
end

--- Apply a quantifier to a translated fragment, re-attaching it to the last atom
-- when the fragment is more than one atom long.
local function quantify(text, min, max)
  if min == 1 and max == 1 then
    return text
  end
  if isSingleAtom(text) then
    return expand(text, min, max)
  end
  local head, atom = splitLastAtom(text)
  return head .. expand(atom, min, max)
end

--- Index of the ')' that closes the group opened at `i`, or nil.
local function findCloseParen(body, i)
  local depth, inClass = 0, false
  local index = i
  while index <= #body do
    local char = body:sub(index, index)
    if char == "\\" then
      index = index + 2
    elseif inClass then
      if char == "]" then
        inClass = false
      end
      index = index + 1
    elseif char == "[" then
      inClass = true
      index = index + 1
    elseif char == "(" then
      depth = depth + 1
      index = index + 1
    elseif char == ")" then
      depth = depth - 1
      if depth == 0 then
        return index
      end
      index = index + 1
    else
      index = index + 1
    end
  end
  return nil
end

--- Read a `(...)` group starting at `i`, returning its body and the next index.
--
-- Handles the group prefixes models emit: capturing, `?:`, `?<name>`, inline
-- flags, and lookaround, which is dropped along with its body because Lua has
-- no lookaround.
local function readGroup(body, i)
  local index = i + 1
  if body:sub(index, index) == "?" then
    local second = body:sub(index + 1, index + 1)
    if second == ":" then
      index = index + 2
    elseif second == "<" then
      local third = body:sub(index + 2, index + 2)
      if third == "=" or third == "!" then
        local close = findCloseParen(body, index + 2)
        return close and "" or nil, close and close + 1 or #body + 1
      end
      local close = body:find(">", index + 2, true)
      index = close and close + 1 or index + 2
    else
      -- Inline flags: "(?i)" drops the flag, "(?i:...)" keeps the body.
      local close = body:find(")", index + 1, true)
      local colon = body:find(":", index + 1, true)
      if close and (not colon or close < colon) then
        return "", close + 1
      end
      if colon then
        index = colon + 1
      else
        return "", #body + 1
      end
    end
  end

  local close = findCloseParen(body, i)
  if not close then
    return nil, #body + 1
  end
  return body:sub(index, close - 1), close + 1
end

--- Translate one alternative (no top-level `|`) into a Lua pattern.
--
-- Groups are transparent: their body is inlined. A quantifier after a group
-- attaches to the group's own text when that text is a single atom, which covers
-- the common `(\w+)` case, and to its last atom otherwise. Lua patterns cannot
-- repeat a group, so `(ab)+` is an approximation of `X+` for multi-character
-- groups.
local function translateBody(body)
  local out = {}
  local index = 1

  while index <= #body do
    local char = body:sub(index, index)
    local atom, nextIndex

    -- Anchors only mean anything at the very ends. Anywhere else they are
    -- literals, and a quantifier must never be attached to one. An anchor
    -- emits its character and leaves `atom` unset, so no quantifier is applied.
    if char == "^" and index == 1 then
      out[#out + 1] = "^"
      nextIndex = 2
    elseif char == "$" and index == #body then
      out[#out + 1] = "$"
      nextIndex = #body + 1
    elseif char == "\\" then
      local escape = body:sub(index + 1, index + 1)
      atom = CLASSES[escape] or ("%" .. escape)
      nextIndex = index + 2
    elseif char == "[" then
      local text, after = readClass(body, index)
      if not text then
        atom, nextIndex = "%[", index + 1
      else
        atom, nextIndex = text, after
      end
    elseif char == "(" then
      local inner, after = readGroup(body, index)
      if inner == nil then
        atom, nextIndex = "%(", index + 1
      else
        local min, max = 1, 1
        local quantifier = body:sub(after, after)
        if quantifier == "*" or quantifier == "+" or quantifier == "?" then
          min = quantifier == "+" and 1 or 0
          max = quantifier == "?" and 1 or math.huge
          after = after + 1
        elseif quantifier == "{" then
          local repeatMin, repeatMax, afterRepeat = readRepeat(body, after)
          if repeatMin then
            min, max = repeatMin, repeatMax
            after = afterRepeat
          end
        end
        out[#out + 1] = quantify(translateBody(inner), min, max)

        -- A trailing '?' makes the group's quantifier lazy, which Lua has no syntax for.
        if body:sub(after, after) == "?" then
          after = after + 1
        end
        nextIndex = after
      end
    elseif char == "." then
      atom, nextIndex = ".", index + 1
    elseif char == "{" then
      local min, max, after = readRepeat(body, index)
      if min then
        for _ = 1, math.min(min, 8) do
          out[#out + 1] = "."
        end
        nextIndex = after
        if max > min then
          out[#out + 1] = ".*"
        end
      else
        atom, nextIndex = "%{", index + 1
      end
    elseif char == ")" then
      atom, nextIndex = "%)", index + 1
    else
      atom, nextIndex = escapeLiteral(char), index + 1
    end

    if atom then
      -- No quantifier means exactly one occurrence, not one-or-more.
      local min, max = 1, 1
      local quantifier = body:sub(nextIndex, nextIndex)
      if quantifier == "*" or quantifier == "+" or quantifier == "?" then
        min = quantifier == "+" and 1 or 0
        max = quantifier == "?" and 1 or math.huge
        nextIndex = nextIndex + 1
      elseif quantifier == "{" then
        local repeatMin, repeatMax, after = readRepeat(body, nextIndex)
        if repeatMin then
          min, max = repeatMin, repeatMax
          nextIndex = after
        end
      end
      out[#out + 1] = expand(atom, min, max)

      -- A trailing '?' makes the quantifier lazy, which Lua has no syntax for.
      if body:sub(nextIndex, nextIndex) == "?" then
        nextIndex = nextIndex + 1
      end
    end

    index = nextIndex
  end

  return table.concat(out)
end

--- Split a regex on top-level `|`, ignoring separators inside groups or classes.
local function splitAlternatives(regex)
  local parts, current = {}, {}
  local depth, inClass = 0, false
  local index = 1
  while index <= #regex do
    local char = regex:sub(index, index)
    if char == "\\" then
      current[#current + 1] = char .. regex:sub(index + 1, index + 1)
      index = index + 2
    elseif char == "[" then
      inClass = true
      current[#current + 1] = char
      index = index + 1
    elseif char == "]" then
      inClass = false
      current[#current + 1] = char
      index = index + 1
    elseif char == "(" and not inClass then
      depth = depth + 1
      current[#current + 1] = char
      index = index + 1
    elseif char == ")" and not inClass then
      depth = depth - 1
      current[#current + 1] = char
      index = index + 1
    elseif char == "|" and not inClass and depth == 0 then
      parts[#parts + 1] = table.concat(current)
      current = {}
      index = index + 1
    else
      current[#current + 1] = char
      index = index + 1
    end
  end
  parts[#parts + 1] = table.concat(current)
  return parts
end

--- Compile a regex into a list of Lua patterns, one per top-level alternative,
--- anchored so a match means the whole alternative matched.
-- Invalid patterns are skipped rather than raised, so a bad regex still greps.
function M.compile(regex)
  local out = {}
  for _, alternative in ipairs(splitAlternatives(regex or "")) do
    local translated = translateBody(alternative)
    if translated:sub(1, 1) ~= "^" then
      translated = "^" .. translated
    end
    if translated:sub(-1) ~= "$" then
      translated = translated .. "$"
    end
    if pcall(string.find, "", translated) then
      out[#out + 1] = translated
    end
  end
  return out
end

--- Compile without adding anchors, for substring searches within a line. Anchors
--- the regex wrote itself are still honoured.
function M.compilePartial(regex)
  local out = {}
  for _, alternative in ipairs(splitAlternatives(regex or "")) do
    local translated = translateBody(alternative)
    if pcall(string.find, "", translated) then
      out[#out + 1] = translated
    end
  end
  return out
end

--- Locate a match, returning start and end byte offsets, or nil.
function M.find(patterns, subject)
  for _, pattern in ipairs(patterns) do
    local ok, start, finish = pcall(string.find, subject, pattern)
    if ok and start then
      return start, finish
    end
  end
  return nil
end

--- True when any pattern matches anywhere in `subject`.
function M.test(patterns, subject)
  return M.find(patterns, subject) ~= nil
end

return M

end

