__sources["tool/glob"] = function(...)
do end
-- The `glob` tool: find files by name pattern.

local env = require("environment")
local util = require("util")
local pattern = require("pattern")
local registry = require("tool/registry")

local LIMIT = 100

local DESCRIPTION = [[Fast file pattern matching that works with any codebase size.
- Supports glob patterns such as "**/*.lua" or "/src/**/*.ts"
- Returns matching file paths
- Use this when you need to find files by name
- Issue several speculative glob calls in one message when you are unsure of the
  layout; each is cheap compared to the context a full listing would cost.]]

registry.define({
  id = "glob",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      pattern = { type = "string", description = "The glob pattern to match against file paths" },
      path = { type = "string", description = "The directory to search. Defaults to the session working directory." },
      limit = { type = "number", description = "Maximum number of results. Defaults to 100." },
    },
    required = { "pattern" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local glob = args.pattern
    if type(glob) ~= "string" or glob == "" then
      error("The pattern argument is required.", 0)
    end
    local root = args.path and env.resolve(args.path, ctx.cwd) or ctx.cwd
    local limit = math.min(tonumber(args.limit) or LIMIT, LIMIT)

    local compiled = pattern.globToPattern(util.startswith(glob, "/") and glob:sub(2) or glob)
    local matches = {}
    local total = 0

    env.walk(root, {
      onFile = function(path)
        local relative = path:sub(#root + 1)
        relative = util.startswith(relative, "/") and relative:sub(2) or relative
        if pattern.find({ compiled }, relative) then
          total = total + 1
          if #matches < limit then
            matches[#matches + 1] = path
          end
        end
      end,
    })

    table.sort(matches)
    if #matches == 0 then
      return { title = glob, metadata = { count = 0 }, output = "No files found" }
    end

    local output = table.concat(matches, "\n")
    if total > limit then
      output = output
        .. string.format(
          "\n\n(Results are truncated: showing the first %d of %d results. Use a more specific path or pattern.)",
          limit, total
        )
    end

    return { title = glob, metadata = { count = total }, output = output }
  end,
})

return true

end

-- src/tool/grep.lua
__sources["tool/grep"] = function(...)
do end
-- The `grep` tool: search file contents.
--
-- CC has no regex engine, so patterns go through the translator in
-- `src/pattern.lua`, which supports the subset models normally send.

local env = require("environment")
local util = require("util")
local pattern = require("pattern")
local registry = require("tool/registry")

local LIMIT = 100
local SKIP_DIRECTORIES = {
  [".git"] = true, [".svn"] = true, ["node_modules"] = true, [".cache"] = true,
  ["opencode"] = true, [".Trash"] = true, ["__pycache__"] = true,
}

local DESCRIPTION = [[Fast content search that works with any codebase size.
- Searches file contents using a regular expression
- Filter which files are searched with the include parameter, e.g. "*.lua" or "*.md"
- Returns file paths with line numbers and the matching lines
- Use this when you need to find code containing a specific pattern
- Run several independent searches in one message rather than guessing a single
  broad pattern; each search is cheap compared to the context a full read would cost.]]

--- True when `path` should be searched, per the include filter.
local function included(path, includes)
  if not includes then
    return true
  end
  for _, include in ipairs(includes) do
    if pattern.matchesGlob(path, include) or pattern.matchesGlob(env.basename(path), include) then
      return true
    end
  end
  return false
end

--- Split a comma separated include filter into glob patterns.
local function parseIncludes(raw)
  if type(raw) ~= "string" or raw == "" then
    return nil
  end
  local out = {}
  for piece in raw:gmatch("[^,]+") do
    local trimmed = util.trim(piece)
    if trimmed ~= "" then
      out[#out + 1] = trimmed
    end
  end
  return #out > 0 and out or nil
end

registry.define({
  id = "grep",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      pattern = { type = "string", description = "The regular expression to search for" },
      path = { type = "string", description = "The directory to search. Defaults to the session working directory." },
      include = { type = "string", description = "Comma separated glob patterns limiting which files are searched, e.g. \"*.lua\"" },
      limit = { type = "number", description = "Maximum number of matching lines to return. Defaults to 100." },
    },
    required = { "pattern" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local regex = args.pattern
    if type(regex) ~= "string" or regex == "" then
      error("The pattern argument is required.", 0)
    end
    local root = args.path and env.resolve(args.path, ctx.cwd) or ctx.cwd
    local limit = math.min(tonumber(args.limit) or LIMIT, LIMIT)
    local includes = parseIncludes(args.include)
    local compiled = pattern.compilePartial(regex)

    if #compiled == 0 then
      error("The pattern could not be compiled: " .. regex, 0)
    end

    local hits, total = {}, 0
    local truncated = false

    env.walk(root, {
      onDir = function(path)
        local name = env.basename(path)
        if name == ".git" or SKIP_DIRECTORIES[name] then
          return false
        end
        return true
      end,
      onFile = function(path)
        if truncated or not included(path, includes) then
          return
        end
        local content = env.readLimited(path, 512 * 1024)
        if not content then
          return
        end
        local matched = {}
        for number, line in ipairs(util.lines(content)) do
          if pattern.find(compiled, line) then
            total = total + 1
            if #hits < limit then
              matched[#matched + 1] = string.format("  Line %d: %s", number, util.trim(line))
            else
              truncated = true
            end
          end
        end
        if #matched > 0 then
          hits[#hits + 1] = { path = path, lines = matched }
        end
      end,
    })

    if #hits == 0 then
      return { title = regex, metadata = { count = 0 }, output = "No matches found" }
    end

    local blocks = {}
    for _, hit in ipairs(hits) do
      blocks[#blocks + 1] = hit.path .. ":\n" .. table.concat(hit.lines, "\n")
    end

    local header = truncated
        and string.format("Found %d matches (showing the first %d, more are available)", total, limit)
      or string.format("Found %d matches", total)
    local output = header .. "\n\n" .. table.concat(blocks, "\n\n")
    if truncated then
      output = output .. "\n\n(Results are truncated. Use a more specific pattern or path.)"
    end

    return { title = regex, metadata = { count = total }, output = output }
  end,
})

return true

end

-- src/tool/webfetch.lua
__sources["tool/webfetch"] = function(...)
do end
-- The `webfetch` tool: retrieve a URL and return its content as text.

local util = require("util")
local http = require("http")
local registry = require("tool/registry")

local MAX_BYTES = 5 * 1024 * 1024
local MAX_TIMEOUT = 120

local DESCRIPTION = [[Fetches content from a URL and returns it as text.

Usage notes:
  - The URL must be fully formed, including the scheme. http:// is upgraded to https://
  - The format may be "text" (default) or "html". HTML is returned as source.
  - Only the body is returned; navigation links and framing are stripped.
  - This tool is read-only and does not modify any files.
  - Large pages are truncated. Fetch a more specific URL when the result is cut off.]]

--- Very small HTML-to-text conversion: drop script/style/nav noise and tags.
local function htmlToText(html)
  local text = html
  for _, tag in ipairs({ "script", "style", "noscript", "svg", "head" }) do
    text = text:gsub("<" .. tag .. "[^>]*>.-</" .. tag .. ">", " ")
  end
  text = text:gsub("<!--.-%-%->", " ")
  text = text:gsub("<br%s*/?>", "\n")
  text = text:gsub("</p>", "\n\n")
  text = text:gsub("</h[1-6]>", "\n\n")
  text = text:gsub("</li>", "\n")
  text = text:gsub("<li[^>]*>", "- ")
  text = text:gsub("<a[^>]*href=\"([^\"]*)\"[^>]*>(.-)</a>", function(_, href, label)
    return util.trim(label) ~= "" and string.format("[%s](%s)", util.trim(label), href) or " "
  end)
  text = text:gsub("<[^>]+>", " ")
  text = text:gsub("&nbsp;", " "):gsub("&amp;", "&"):gsub("&lt;", "<")
  text = text:gsub("&gt;", ">"):gsub("&quot;", '"'):gsub("&#39;", "'")
  text = text:gsub("[ \t]+", " ")
  text = text:gsub(" *\n *", "\n")
  text = text:gsub("\n{3,}", "\n\n")
  return util.trim(text)
end

registry.define({
  id = "webfetch",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      url = { type = "string", description = "The URL to fetch" },
      format = { type = "string", description = "Either \"text\" (default) or \"html\"" },
      timeout = { type = "number", description = "Timeout in seconds, up to 120. Defaults to 30." },
    },
    required = { "url" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local url = args.url
    if type(url) ~= "string" or url == "" then
      error("The url argument is required.", 0)
    end
    if url:match("^http://") then
      url = "https://" .. url:sub(8)
    end
    if not url:match("^https://") then
      error("The url must start with http:// or https://, got: " .. args.url, 0)
    end

    local timeout = math.min(tonumber(args.timeout) or 30, MAX_TIMEOUT)
    local response, err = http.request(url, { timeout = timeout, maxBytes = MAX_BYTES })
    if not response then
      error("Could not fetch " .. url .. ": " .. tostring(err), 0)
    end
    if response.status < 200 or response.status >= 300 then
      error("Could not fetch " .. url .. ": " .. http.errorMessage(response), 0)
    end

    local body = args.format == "html" and response.body or htmlToText(response.body or "")
    if body == "" then
      body = "(empty response)"
    end

    return {
      title = url,
      metadata = { url = url, status = response.status, bytes = #(response.body or "") },
      output = string.format("<url>%s</url>\n<status>%d</status>\n<content>\n%s\n</content>", url, response.status, body),
    }
  end,
})

return true

end

-- src/tool/todowrite.lua
__sources["tool/todowrite"] = function(...)
do end
-- The `todowrite` tool: maintain a structured task list for the session.

local json = require("json")
local registry = require("tool/registry")

local DESCRIPTION = [[Create and maintain a structured task list for the current session. Tracks progress, organizes multi-step work, and surfaces status to the user.

## When to use
Use proactively when:
- The task requires 3 or more distinct steps or actions (not 3 tool calls for one conceptual step)
- The work is non-trivial and benefits from planning
- The user provides multiple tasks (numbered or comma-separated) or asks for a todo list
- New instructions arrive: capture them as todos
- You start a task: mark it in_progress (only one at a time) before working
- You finish a task: mark it completed and add any follow-ups you discovered

## When NOT to use
Skip when:
- The work is a single straightforward task (or fewer than 3 trivial steps)
- The request is purely informational or conversational
- Tracking adds no organizational value

## States
- pending: not started
- in_progress: actively working (exactly ONE at a time)
- completed: finished successfully

## Rules
- Update status in real time; do not batch completions
- Mark completed only after the work is actually done and verified, never based on intent
- Keep exactly one in_progress while work remains
- If blocked or partial, keep it in_progress and add a follow-up todo describing the blocker

## Examples

Use it:
- "Add a dark mode toggle and run the tests" -> multi-step work with explicit verification
- "Rename X to Y across the repo" -> search reveals 5 occurrences in 3 files
- "Implement authentication, catalog, cart, and checkout" -> several complex features

Skip it:
- "How do I print Hello World?" -> informational
- "Add a single comment to a function" -> one edit
- "Run npm install and report what happened" -> one command

When in doubt, use it.]]

local VALID_STATUS = { pending = true, in_progress = true, completed = true, cancelled = true }
local VALID_PRIORITY = { high = true, medium = true, low = true }

registry.define({
  id = "todowrite",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      todos = {
        type = "array",
        description = "The complete updated todo list. Send every todo, not just the ones that changed.",
        items = {
          type = "object",
          properties = {
            content = { type = "string", description = "The task description" },
            status = { type = "string", description = "One of: pending, in_progress, completed, cancelled" },
            priority = { type = "string", description = "One of: high, medium, low" },
          },
          required = { "content", "status", "priority" },
          additionalProperties = false,
        },
      },
    },
    required = { "todos" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local todos = args.todos
    if type(todos) ~= "table" then
      error("The todos argument is required and must be an array.", 0)
    end

    local normalised = {}
    local active = 0
    for index, todo in ipairs(todos) do
      if type(todo) ~= "table" or type(todo.content) ~= "string" or todo.content == "" then
        error("Each todo needs a non-empty content string; todo " .. index .. " is invalid.", 0)
      end
      local status = VALID_STATUS[todo.status] and todo.status or "pending"
      if status == "in_progress" then
        active = active + 1
      end
      normalised[#normalised + 1] = {
        content = todo.content,
        status = status,
        priority = VALID_PRIORITY[todo.priority] and todo.priority or "medium",
      }
    end

    if active > 1 then
      error("Exactly one todo may be in_progress at a time, but " .. active .. " were.", 0)
    end

    registry.guard(ctx, "todowrite", { "*" }, { "*" })
    ctx.session.todos = normalised

    return {
      title = string.format("%d todos", #normalised),
      metadata = { todos = normalised },
      output = json.encode(normalised, "  "),
    }
  end,
})

return true

end

-- src/tool/registry.lua
__sources["tool/registry"] = function(...)
do end
-- Tool registry.
--
-- A tool is `{ id, description, parameters, execute }` where `parameters` is a
-- JSON Schema object describing the tool's arguments. `execute(args, ctx)`
-- returns `{ title, metadata, output }`, or raises with a string to signal a tool
-- error that is reported back to the model.

local json = require("json")
local util = require("util")
local permission = require("permission")
local truncate = require("truncate")

local M = {}

M.builtin = {}

local BUILTIN_MODULES = {
  "tool/bash",
  "tool/read",
  "tool/write",
  "tool/edit",
  "tool/glob",
  "tool/grep",
  "tool/webfetch",
  "tool/todowrite",
}

--- Load the built-in tool modules so their `define` calls have run.
--
-- Idempotent, and deliberately not done at the bottom of this file. Each tool
-- module requires the registry back, so a tool required while the registry is
-- still loading is a require cycle: `require` marks the module it is loading with
-- a sentinel in `package.loaded` and refuses to resolve the inner call. Calling
-- this from the agent loop or `/tools` happens once the registry is complete, and
-- `M.loaded` makes even a second call a no-op.
function M.load()
  if M.loaded then
    return M.builtin
  end
  M.loaded = true
  for _, name in ipairs(BUILTIN_MODULES) do
    require(name)
  end
  return M.builtin
end

--- Declare a tool. Keeping this in one place makes the schema and the executor
--- impossible to drift apart.
function M.define(spec)
  M.builtin[#M.builtin + 1] = {
    id = spec.id,
    description = spec.description,
    parameters = spec.parameters,
    execute = spec.execute,
  }
end

--- Convert a tool into the OpenAI wire shape.
function M.toWire(tool)
  return {
    type = "function",
    ["function"] = {
      name = tool.id,
      description = tool.description,
      parameters = tool.parameters,
    },
  }
end

function M.list(enabled)
  M.load()
  if not enabled then
    return M.builtin
  end
  local out = {}
  for _, tool in ipairs(M.builtin) do
    if enabled[tool.id] ~= false then
      out[#out + 1] = tool
    end
  end
  return out
end

function M.get(id)
  M.load()
  for _, tool in ipairs(M.builtin) do
    if tool.id == id then
      return tool
    end
  end
  return nil
end

function M.ids(enabled)
  local out = {}
  for _, tool in ipairs(M.list(enabled)) do
    out[#out + 1] = tool.id
  end
  return out
end

--- Request approval for a tool action, honouring the session ruleset.
-- Returns true when allowed, or raises a permission error the model will see.
function M.guard(ctx, permissionID, patterns, always, title)
  local decision = permission.ask({
    permission = permissionID,
    patterns = patterns or { "*" },
    always = always or patterns or { "*" },
    ruleset = ctx.permission,
    session = ctx.session,
    monitor = ctx.monitor,
    title = title,
  })
  if decision == permission.ALLOW then
    return true
  end
  if util.startswith(decision, "feedback:") then
    error("Permission denied by the user: " .. decision:sub(10), 0)
  end
  error("Permission denied by the user for " .. permissionID .. ": " .. table.concat(patterns or {}, ", "), 0)
end

local truncateLimits

function M.limits(config)
  if not truncateLimits or truncateLimits.config ~= config then
    local options = (config and config.tool_output) or {}
    truncateLimits = {
      config = config,
      maxLines = options.max_lines or truncate.MAX_LINES,
      maxBytes = options.max_bytes or truncate.MAX_BYTES,
    }
  end
  return truncateLimits
end

--- Apply output limits unless the tool already reported its own truncation.
function M.finish(tool, ctx, result)
  if result.metadata and result.metadata.truncated ~= nil then
    return result
  end
  local limits = M.limits(ctx.config)
  local truncated = truncate.output(result.output, {
    maxLines = limits.maxLines,
    maxBytes = limits.maxBytes,
    direction = "head",
  })
  if truncated == result.output then
    return result
  end
  result.metadata = result.metadata or {}
  result.metadata.truncated = true
  result.output = truncated
  return result
end

--- Run one tool by id, converting failures into a structured result.
function M.execute(id, rawArguments, ctx)
  local tool = M.get(id)
  if not tool then
    return {
      status = "error",
      error = "Unknown tool '" .. id .. "'. Available tools: " .. table.concat(M.ids(ctx.enabled), ", "),
    }
  end
  local arguments = type(rawArguments) == "table" and json.dropNulls(rawArguments) or {}

  local ok, result = pcall(tool.execute, arguments, ctx)
  if not ok then
    local message = tostring(result):gsub("^.-:%d+: ", "")
    if message:find("Permission denied") then
      return { status = "denied", error = message }
    end
    return { status = "error", error = message }
  end

  result = M.finish(tool, ctx, result)
  return { status = "completed", title = result.title, output = result.output, metadata = result.metadata }
end

return M

end

-- src/prompt.lua
__sources["prompt"] = function(...)
do end
-- System prompts.
--
-- Adapted from opencode's prompt templates. The structure is preserved (tone,
-- proactiveness, conventions, task workflow, tool policy) but rewritten for the
-- ComputerCraft environment, where the shell is CC's rather than bash and the
-- files are Lua programs with a limited filesystem.

local env = require("environment")
local config = require("config")
local registry = require("tool/registry")
local truncate = require("truncate")

local M = {}

M.BASE = [[You are opencode, an interactive agent running on a ComputerCraft computer in Minecraft. You help the user with software engineering tasks using the tools available to you.

You are running inside a Lua sandbox, not a normal operating system. The rules below follow from that and matter for every task.

# Environment
- The shell is the ComputerCraft shell, not bash. It has pipes, `>` redirection, `&` for background, and `;` for sequencing. It does NOT have `&&`, `$VAR` expansion, `~`, or glob expansion. Programs are Lua files under /rom/programs or on PATH.
- Files live under the root `/` and always use absolute paths with `/` separators. There is no home directory concept beyond the root.
- Your own source is at the path shown in the environment block. Lua 5.1: no `goto` in older builds, no integer division operator, `unpack` not `table.unpack`, and no `os.execute` or `io` writes. Use `fs` and `shell` from ComputerCraft.
- Lua memory and CPU are tiny. Do not plan to process megabytes in a single Lua operation, and do not read huge files in one call; use the Read tool with offset/limit.
- There is no internet browsing other than the WebFetch tool, and no package manager. Dependencies do not exist unless they are already on the computer.

# Tone and style
Be concise and direct. Output is displayed on a terminal, so short answers are best.
- Answer questions directly. One or two sentences when that answers the question.
- Do not add preamble, postamble, or a summary of what you were about to do.
- Do not restate the user's request back to them.
- Explain what you are doing only when a command changes state or the reasoning is not obvious.
- Only use emojis if the user explicitly requests it.
- Never invent a URL unless you are confident it exists. You may use URLs the user gave you or that appear in local files.

# Code style
- IMPORTANT: do not add any comments unless asked.
- Follow the conventions of the file you are editing: match its naming, formatting, comment density, and structure. Read neighbouring code before adding to it.
- Never assume a library is available. Check that the code already uses it before relying on it.
- Never print or commit secrets, including API keys in opencode.json.
- Match the surrounding code's style even where you would have written it differently.

# Doing tasks
- Understand the code before changing it. Use Glob and Grep to locate things, and Read to read them. Batch independent searches together.
- Prefer the dedicated tools over the shell: Read and Write and Edit for files, Glob for finding, Grep for searching, WebFetch for the web, and Bash only for running programs.
- Verify your work when the project has a way to verify it. On ComputerCraft that usually means running a program or checking output.
- Do not commit, upload, or delete things the user did not ask you to delete.

# Tool usage policy
- You can call several tools in one message. Do so whenever the calls are independent.
- When you are unsure of the file layout, issue speculative searches rather than one broad scan.
- Read a file before editing it. The Edit tool needs the exact text including indentation.
- Do not use Bash with `type`, `cat`, `echo >` or `ls` for file work; use Read, Write, and Glob instead.
- If you do not need a tool, do not call it. Answer from what you already know.]]

M.PLAN = [[# Planning
You are in plan mode. Investigate and produce a plan; do not modify any files or run commands that change state.
- Read and search freely to understand the current implementation.
- Present a concrete, ordered plan and ask the user to approve it before implementing.
- When the user approves, stop planning and switch back to the agent that can edit.]]

M.EXPLORE = [[You are a read-only search agent. Find things and report what you found; do not modify anything.

- Run several independent searches in parallel where possible.
- Report file paths and line numbers so the caller can read the exact locations.
- Quote only the lines that matter, not whole files.
- If a search returns nothing, say so plainly rather than guessing.]]

M.TITLE = [[Generate a short title for a conversation. Reply with the title only, no quotes, no punctuation at the end, and at most 6 words.]]

M.COMPACTION = [[Summarize the conversation so far so it can continue in a fresh context. Preserve, in this order of priority:
1. The user's original request and any explicit constraints.
2. Decisions made and their reasons.
3. Files and functions that were created, changed, or inspected, with paths.
4. What was completed and what remains.
Write it as a dense briefing, not a narrative. Do not include pleasantries.]]

M.MAX_STEPS = [[CRITICAL - MAXIMUM STEPS REACHED

The maximum number of steps for this task has been reached. Tools are disabled until the next user input. Respond with text only.

STRICT REQUIREMENTS:
1. Do NOT make any tool calls.
2. You MUST provide a text response summarising the work done so far.
3. This constraint overrides all other instructions.

Your response must include:
- A statement that the maximum steps have been reached
- A summary of what has been accomplished
- A list of anything that remains
- A recommendation for what to do next]]

local AGENT_PROMPTS = {
  build = M.BASE,
  plan = M.BASE .. "\n" .. M.PLAN,
  general = M.BASE,
  explore = M.EXPLORE,
  title = M.TITLE,
  compaction = M.COMPACTION,
}

--- The environment block injected ahead of every request.
function M.environment(configValue, model)
  local root = env.cwd()
  return string.format(
    "You are powered by the model named %s. The exact model ID is %s/%s.\nHere is some useful information about the environment you are running in:\n<env>\n  Computer: %s\n  Working directory: %s\n  Platform: %s (ComputerCraft, Lua %s)\n  Today's date: %s\n</env>",
    model.name or model.id,
    model.providerID,
    model.id,
    env.computerLabel(),
    root,
    env.isCC and "ComputerCraft" or "host",
    _VERSION or "5.1",
    env.today()
  )
end

--- The current tool list, so the prompt never names a tool that is disabled.
function M.tools(enabled)
  local names = registry.ids(enabled)
  return "Available tools: " .. table.concat(names, ", ") .. "."
end

--- Output limits, so the bash and read prompts quote the real numbers.
function M.limits()
  local options = config.DEFAULTS.tool_output
  return string.format(
    "Tool output is truncated past %d lines or %d bytes; the full text is written to a file you can grep or read with offset/limit.",
    options.max_lines,
    options.max_bytes
  )
end

--- The full system prompt for one request.
function M.system(configValue, agent, model, enabled)
  local base = (configValue.agent or {})[agent] and (configValue.agent[agent].prompt)
    or AGENT_PROMPTS[agent]
    or AGENT_PROMPTS.build
  return table.concat({
    base,
    M.environment(configValue, model),
    M.limits(),
    M.tools(enabled),
  }, "\n\n")
end

return M

end

-- src/session.lua
__sources["session"] = function(...)
do end
-- Session message storage.
--
-- A session is a list of messages; each message has a list of parts. The part
-- union mirrors opencode's schema closely enough to keep the model wire format
-- correct: text, reasoning, tool (with a pending/running/completed/error state),
-- step-start, and step-finish.

local json = require("json")
local util = require("util")
local env = require("environment")

local M = {}

local function newSession(id, title)
  return {
    id = id,
    title = title,
    created = os.time(),
    messages = {},
    todos = {},
    permission = {},
  }
end

--- The title a session has until one is generated for it.
M.DEFAULT_TITLE = "New session"

function M.new(title)
  return newSession(util.id("ses"), title or M.DEFAULT_TITLE)
end

function M.latestUserMessage(session)
  for index = #session.messages, 1, -1 do
    if session.messages[index].role == "user" then
      return session.messages[index]
    end
  end
  return nil
end

function M.latestAssistantMessage(session)
  for index = #session.messages, 1, -1 do
    if session.messages[index].role == "assistant" then
      return session.messages[index]
    end
  end
  return nil
end

--- True when the most recent assistant reply belongs to the newest user message
--- and left nothing outstanding.
--
-- The parent check is what makes a second `agent.run` on the same session do
-- something: after a finished turn there *is* an assistant message, so without it
-- a follow-up question would look like a completed turn and the loop would exit
-- before making a request.
function M.isTurnComplete(session)
  local user = M.latestUserMessage(session)
  if not user then
    return true
  end
  local assistant = M.latestAssistantMessage(session)
  if not assistant or assistant.parentID ~= user.id or not assistant.finish then
    return false
  end
  if assistant.finish == "tool-calls" or assistant.finish == "unknown" then
    return false
  end
  for _, part in ipairs(assistant.parts) do
    if part.type == "tool" and not part.state.providerExecuted and part.state.status ~= "error" then
      return false
    end
  end
  return true
end

function M.addUser(session, text)
  local message = { id = util.id("msg"), role = "user", time = { created = os.time() }, parts = { { type = "text", text = text } } }
  session.messages[#session.messages + 1] = message
  return message
end

--- The first thing the user asked, which is what a session title is built from.
function M.firstUserMessage(session)
  for _, message in ipairs(session.messages) do
    if message.role == "user" and not message.summary then
      return message
    end
  end
  return nil
end

--- The concatenated text of a message, or the empty string.
function M.text(message)
  if not message then
    return ""
  end
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

function M.addAssistant(session, model)
  local user = M.latestUserMessage(session)
  local message = {
    id = util.id("msg"),
    role = "assistant",
    -- Which user turn this replies to, so a finished turn is not mistaken for an
    -- answer to the next question.
    parentID = user and user.id or nil,
    time = { created = os.time() },
    model = model,
    parts = {},
    cost = 0,
    tokens = { input = 0, output = 0, reasoning = 0, cacheRead = 0, cacheWrite = 0, total = 0 },
  }
  message.parts[#message.parts + 1] = { type = "step-start", time = { start = os.time() } }
  session.messages[#session.messages + 1] = message
  return message
end

function M.addText(message, text)
  local part = { type = "text", text = text, time = { start = os.time() } }
  message.parts[#message.parts + 1] = part
  return part
end

function M.addReasoning(message, text)
  local part = { type = "reasoning", text = text, time = { start = os.time() } }
  message.parts[#message.parts + 1] = part
  return part
end

function M.addToolPart(message, call)
  local part = {
    type = "tool",
    callID = call.id or util.id("call"),
    tool = call.name,
    state = { status = "pending", input = {}, raw = call.arguments or "" },
  }
  message.parts[#message.parts + 1] = part
  return part
end

function M.startTool(part, input)
  part.state.status = "running"
  part.state.input = input
  part.state.time = { start = os.time() }
end

function M.completeTool(part, result)
  part.state.status = "completed"
  part.state.output = result.output
  part.state.title = result.title
  part.state.metadata = result.metadata or {}
  part.state.time = part.state.time or { start = os.time() }
  part.state.time["end"] = os.time()
end

function M.failTool(part, message)
  part.state.status = "error"
  part.state.error = message
  part.state.metadata = part.state.metadata or {}
  part.state.time = part.state.time or { start = os.time() }
  part.state.time["end"] = os.time()
end

function M.finishStep(message, finish, usage)
  message.finish = finish
  if usage then
    message.tokens = usage
  end
  message.parts[#message.parts + 1] = { type = "step-finish", reason = finish, tokens = message.tokens }
  message.time.completed = os.time()
  return message
end

--- Concatenated assistant text across every step of a message.
function M.messageText(message)
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

--- True when the message is mostly tool bookkeeping and carries no user-facing text.
function M.isSilent(message)
  return #M.messageText(message) == 0
end

local function serialisable(session)
  return {
    id = session.id,
    title = session.title,
    created = session.created,
    todos = session.todos,
    permission = session.permission,
    messages = session.messages,
  }
end

function M.directory()
  return env.combine(env.cwd(), "opencode", "session")
end

function M.save(session)
  local path = env.combine(M.directory(), session.id .. ".json")
  if not env.mkdirs(env.dirname(path)) then
    return nil, "could not create " .. env.dirname(path)
  end
  local encoded = json.encode(serialisable(session), "  ")
  if not encoded then
    return nil, "could not encode the session"
  end
  if not env.write(path, encoded) then
    return nil, "could not write " .. path
  end
  return path
end

function M.load(id)
  local path = env.combine(M.directory(), id .. ".json")
  local content = env.read(path)
  if not content then
    return nil
  end
  local decoded = json.decode(content)
  if type(decoded) ~= "table" then
    return nil
  end
  decoded.permission = decoded.permission or {}
  return decoded
end

--- Every saved session id, newest first.
function M.list()
  local ids = {}
  for _, name in ipairs(env.listDir(M.directory())) do
    local id = name:match("^(ses_[%w]+)%.json$")
    if id then
      ids[#ids + 1] = id
    end
  end
  table.sort(ids, function(a, b) return a > b end)
  return ids
end

return M

end

-- src/agent.lua
__sources["agent"] = function(...)
do end
-- The agent loop.
--
-- One iteration is one provider turn: lower the session into OpenAI wire
-- messages, call the model, run whatever tools it asked for, append the results,
-- and repeat until the model stops calling tools. The loop mirrors opencode's
-- `runLoop`, including the max-steps guard and the doom-loop check that stops a
-- model from repeating the same failing call forever.

local json = require("json")
local util = require("util")
local llm = require("llm")
local prompt = require("prompt")
local session = require("session")
local registry = require("tool/registry")
local permission = require("permission")
local config = require("config")
local provider = require("provider")

local M = {}

local DOOM_LOOP_THRESHOLD = 3
local DEFAULT_STEPS = 25

M.COMPACT_MAX_TOKENS = 1024

--- Resolve the step budget for an agent from config, then the built-in defaults.
local function maxStepsFor(configValue, agent)
  local configured = (configValue.agent or {})[agent]
  if configured and configured.steps then
    return configured.steps
  end
  local fallback = (config.DEFAULTS.agent or {})[agent]
  return fallback and fallback.steps or DEFAULT_STEPS
end

--- Concatenate the text parts of a message.
local function textOf(message)
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

--- Lower one assistant message and its tool results into wire messages.
local function lowerAssistant(message, out)
  local text = textOf(message)
  local reasoning = ""
  local toolParts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "reasoning" then
      reasoning = reasoning .. part.text
    elseif part.type == "tool" then
      toolParts[#toolParts + 1] = part
    end
  end

  if text == "" and reasoning == "" and #toolParts == 0 then
    return
  end

  local wire = { role = "assistant", content = text ~= "" and text or json.null }
  if reasoning ~= "" then
    wire.reasoning_content = reasoning
  end
  if #toolParts > 0 then
    wire.tool_calls = {}
    for index, part in ipairs(toolParts) do
      wire.tool_calls[index] = {
        id = part.callID,
        type = "function",
        ["function"] = { name = part.tool, arguments = json.encode(part.state.input or {}) },
      }
    end
  end
  out[#out + 1] = wire

  for _, part in ipairs(toolParts) do
    local content
    if part.state.status == "completed" then
      content = part.state.output
    elseif part.state.status == "error" then
      content = "Error: " .. (part.state.error or "the tool failed")
    else
      content = "Error: the tool was interrupted before it finished"
    end
    out[#out + 1] = { role = "tool", tool_call_id = part.callID, content = content }
  end
end

--- Build the full OpenAI wire message list for a request.
function M.lower(current, system, trailer)
  local messages = {}
  if system and system ~= "" then
    messages[1] = { role = "system", content = system }
  end
  for _, message in ipairs(current.messages) do
    if message.role == "user" then
      messages[#messages + 1] = { role = "user", content = textOf(message) }
    else
      lowerAssistant(message, messages)
    end
  end
  if trailer then
    messages[#messages + 1] = { role = "assistant", content = trailer }
  end
  return messages
end

--- True when the newest assistant turn left work for the model to pick up.
function M.hasPendingWork(current)
  return not session.isTurnComplete(current)
end

--- Raise unless the operator wants the repeated call to continue.
local function doomLoopCheck(ctx, part, history)
  history[#history + 1] = part.tool .. ":" .. json.encode(part.state.input or {})
  if #history < DOOM_LOOP_THRESHOLD then
    return
  end
  for index = #history - DOOM_LOOP_THRESHOLD + 2, #history - 1 do
    if history[index] ~= history[#history] then
      return
    end
  end

  local decision = permission.ask({
    permission = "doom_loop",
    patterns = { part.tool },
    always = { part.tool },
    ruleset = ctx.permission,
    session = ctx.session,
    monitor = ctx.monitor,
    title = string.format(
      "The same %s call has run %d times in a row with identical arguments. Continue?",
      part.tool,
      DOOM_LOOP_THRESHOLD
    ),
  })
  if decision == permission.ALLOW then
    return
  end
  error(
    "The same " .. part.tool .. " call was repeated with identical arguments, so it was stopped. "
      .. "Change the arguments or take a different approach.",
    0
  )
end

--- Run every tool the model asked for in this turn, appending results.
local function runTools(ctx, message, calls, history)
  for _, call in ipairs(calls) do
    if ctx.aborted() then
      return
    end

    local part = session.addToolPart(message, call)

    local arguments, parseError = llm.parseArguments(call.arguments)
    if parseError then
      session.failTool(part, "The " .. call.name .. " tool was called with invalid arguments: " .. parseError
        .. ". Rewrite the input so it matches the tool's schema.")
      ctx.on({ type = "tool_start", part = part })
      ctx.on({ type = "tool_end", part = part })
    else
      -- The start event goes out once the arguments are on the part, so a
      -- listener can say what the model is about to do rather than just naming
      -- the tool.
      session.startTool(part, arguments)
      ctx.on({ type = "tool_start", part = part })
      local outcome = registry.execute(call.name, arguments, ctx)
      if outcome.status == "completed" then
        session.completeTool(part, outcome)
      else
        session.failTool(part, outcome.error)
        if outcome.status == "denied" then
          ctx.blocked = true
        end
      end

      if part.state.status == "completed" then
        local ok, err = pcall(doomLoopCheck, ctx, part, history)
        if not ok then
          session.failTool(part, tostring(err))
        end
      end

      ctx.on({ type = "tool_end", part = part })
    end
  end
end

--- Run the agent loop until the model stops calling tools.
--
-- `ctx` supplies: session, config, model, agent, root, cwd, permission, enabled
-- (tool toggles), monitor, on (event sink), and aborted (a predicate).
function M.run(ctx, options)
  options = options or {}
  local current = ctx.session
  local maxSteps = maxStepsFor(ctx.config, ctx.agent)
  local step = 0
  local history = {}

  while true do
    if ctx.aborted() then
      ctx.on({ type = "aborted" })
      return nil, "aborted"
    end
    if not M.hasPendingWork(current) then
      break
    end

    step = step + 1
    if step > maxSteps then
      return session.latestAssistantMessage(current),
        string.format("reached the maximum of %d steps for agent '%s'", maxSteps, ctx.agent)
    end

    local isLastStep = step == maxSteps
    ctx.on({ type = "step", step = step, max = maxSteps })

    -- Once per step, before the request is built, so the request that would have
    -- been too large never goes out.
    local summary = M.compact(ctx)
    if summary then
      ctx.on({ type = "compacted", text = summary })
    end

    local message = session.addAssistant(current, ctx.model)
    local system = prompt.system(ctx.config, ctx.agent, ctx.model, ctx.enabled)
    local messages = M.lower(current, system, isLastStep and prompt.MAX_STEPS or nil)

    local tools = {}
    for _, tool in ipairs(registry.list(ctx.enabled)) do
      tools[#tools + 1] = registry.toWire(tool)
    end

    local textPart
    local onDelta = nil
    if ctx.stream then
      onDelta = function(delta)
        if not textPart then
          textPart = session.addText(message, "")
        end
        textPart.text = textPart.text .. delta
        ctx.on({ type = "text", delta = delta })
      end
    end

    local result, err = llm.chat({
      model = ctx.model,
      messages = messages,
      tools = #tools > 0 and tools or nil,
      tool_choice = isLastStep and "none" or nil,
      stream = ctx.stream and true or false,
    }, { timeout = ctx.timeout, onDelta = onDelta })

    if not result then
      message.parts[#message.parts + 1] = { type = "step-finish", reason = "error" }
      message.time.completed = os.time()
      message.error = err
      ctx.on({ type = "error", message = err })
      return message, err
    end

    if not textPart and result.content ~= "" then
      session.addText(message, result.content)
      ctx.on({ type = "text", delta = result.content })
    end
    if result.reasoning ~= "" then
      session.addReasoning(message, result.reasoning)
      ctx.on({ type = "reasoning", text = result.reasoning })
    end

    runTools(ctx, message, result.toolCalls, history)
    session.finishStep(message, result.finish, result.usage)
    ctx.on({ type = "step_end", message = message })

    if options.onStepEnd then
      options.onStepEnd(message)
    end
    if ctx.aborted() then
      ctx.on({ type = "aborted" })
      return message, "aborted"
    end
    if ctx.blocked then
      return message
    end
    if result.finish ~= "tool-calls" then
      break
    end
  end

  return session.latestAssistantMessage(current)
end

--- Ask the small model for a session title. Failures are silent.
function M.title(ctx, text)
  if not ctx.smallModel or not text or #text < 4 then
    return nil
  end
  local result = llm.chat({
    model = ctx.smallModel,
    messages = {
      { role = "system", content = prompt.TITLE },
      { role = "user", content = text },
    },
    generation = { maxTokens = 24 },
  }, { timeout = 20 })
  if not result or not result.content then
    return nil
  end
  return util.trim(result.content:gsub("[\"'`]", ""))
end

-- Compaction
--
-- Every turn resends the whole conversation, so a long session eventually asks
-- for more than a ComputerCraft computer can hold in one request. Compaction
-- replaces the older messages with a summary written by the small model, which
-- is what keeps a session usable past a few dozen turns.

--- Roughly how many bytes the conversation occupies.
--
-- An estimate is enough to decide when to compact, and this is cheap: it adds up
-- strings that are already in memory. Encoding every message to JSON on every
-- step would cost more than the compaction it is trying to avoid.
local function conversationBytes(current)
  local total = 0
  for _, message in ipairs(current.messages or {}) do
    -- Room for the envelope: role, ids, timestamps, usage.
    total = total + 96
    for _, part in ipairs(message.parts or {}) do
      if type(part.text) == "string" then
        total = total + #part.text
      elseif part.type == "tool" then
        local state = part.state or {}
        total = total + 96
        for _, key in ipairs({ "output", "error" }) do
          if type(state[key]) == "string" then
            total = total + #state[key]
          end
        end
      end
    end
  end
  return total
end

--- The first message of the conversation that must be kept.
--
-- Compaction drops messages from the front, and the newest user and assistant
-- messages are what tell the loop whether the turn is finished
-- (`session.isTurnComplete`), so the cut has to be in front of both.
local function keepFromIndex(current)
  local latestUser, latestAssistant
  for index = #current.messages, 1, -1 do
    if not latestUser and current.messages[index].role == "user" then
      latestUser = index
    elseif not latestAssistant and current.messages[index].role == "assistant" then
      latestAssistant = index
    end
  end
  local first = latestUser or latestAssistant
  if latestUser and latestAssistant then
    first = math.min(latestUser, latestAssistant)
  end
  return first
end

--- Replace the older part of the conversation with a one-message summary.
--
-- Returns the summary, or nil when there was nothing to do: the conversation
-- still fits, compaction is switched off, there is no small model to write the
-- summary, or the summary request failed. A failure leaves the conversation
-- exactly as it was, so the next request fails with the provider's own size
-- error rather than a silently truncated history.
function M.compact(ctx)
  local settings = ctx.config.compaction or {}
  if settings.auto == false or not ctx.smallModel then
    return nil
  end
  local limit = (ctx.model and ctx.model.limit and ctx.model.limit.context)
    or provider.DEFAULT_LIMIT.context
  local reserved = settings.reserved or config.DEFAULTS.compaction.reserved
  if conversationBytes(ctx.session) + reserved < limit then
    return nil
  end

  local current = ctx.session
  local cut = keepFromIndex(current)
  if not cut or cut < 2 then
    -- Nothing older than the current turn: there is no history to summarise, and
    -- dropping the turn itself would lose the question.
    return nil
  end

  local older = {}
  for index = 1, cut - 1 do
    older[#older + 1] = current.messages[index]
  end
  local transcript = json.encode(M.lower({ messages = older }, nil, nil), "  ")

  local result, err = llm.chat({
    model = ctx.smallModel,
    messages = {
      { role = "system", content = prompt.COMPACTION },
      { role = "user", content = transcript },
    },
    generation = { maxTokens = M.COMPACT_MAX_TOKENS },
  }, { timeout = 30 })
  if not result or not result.content or util.trim(result.content) == "" then
    ctx.on({ type = "error", message = "could not compact the conversation: " .. tostring(err or "the model said nothing") })
    return nil
  end

  for index = #older, 1, -1 do
    table.remove(current.messages, index)
  end
  table.insert(current.messages, 1, {
    id = util.id("msg"),
    role = "user",
    time = { created = os.time() },
    summary = true,
    parts = { { type = "text", text = "Summary of the conversation so far:\n\n" .. util.trim(result.content) } },
  })
  return result.content
end

return M

end

-- src/ui.lua
__sources["ui"] = function(...)
do end
-- The interactive screen: a bounded GUI over the computer's own terminal.
--
-- The plain screen -- `environment.screen` -- is a printer's adapter: everything
-- handed to `write` goes onto the hardware, wrapped, in order, and there is no way
-- back to change any of it. That is enough for `opencode "what is 2 + 2"`, which
-- prints an answer and exits, and not much else. A REPL on a 51-column screen
-- scrolls a conversation off the top and keeps none of it, and nothing on the
-- screen can be scrolled back through, re-read, or pointed at.
--
-- This module is the other kind of screen. It keeps the conversation, wraps it to
-- the width it actually has, and shows a window of it: a title bar, a scrollback
-- pane, a hint line, and an input field. It is deliberately a drop-in for the
-- plain one -- `write`, `setTextColor`, `getSize` and the rest mean what they
-- always did -- so the agent, the tools and the permission prompt are written once
-- and do not know which screen they are drawing on.
--
-- ## Where it draws, and why not a monitor
--
-- On the terminal, always. CraftOS's keyboard belongs to the terminal, so a
-- screenful of controls drawn on a monitor is a screenful of controls nobody can
-- reach: `read` reads the terminal whatever the program is drawing on, and an
-- input field on a monitor cannot be typed into. `M.open` therefore takes the
-- console. A monitor is still what the plain screen prefers, and `--plain` is how
-- you get that instead.
--
-- ## What comes from CC-GUI, and what does not
--
-- The widgets are CC-GUI's: `GUI.createInput` owns the text, the caret and the
-- scroll window, `GUI.createButton` is a button, and `GUI.handleEvent` does the
-- editing and the hit-testing, so the field behaves as the library's own demos
-- do. What is here is everything around them.
--
-- The drawing is ours, and that is the point. CC-GUI does not enforce its own
-- boundaries: `GUI.drawText` writes whatever text it is handed at whatever
-- position it is handed, so a label one column wider than its column runs off the
-- edge, and `GUI.drawAll` clears every screen once per control in `pairs` order,
-- redrawing overlapping widgets in whatever order the hash table happens to
-- produce. On a real terminal a write past the right edge carries onto the next
-- row, so the damage is not a clipped label; it is the title bar drawn over the
-- transcript. So every draw here goes through `blit`, which clips to the box and
-- then to the screen, or `fill`, which clamps its box, and the layout is computed
-- rather than guessed. `GUI.drawText` and `GUI.fillRegion` are still what put the
-- characters down; they are simply never called with an argument that can escape.
--
-- The transcript is not a CC-GUI `List`. A list is an array of fixed rows in one
-- colour with a click-driven selection, and a conversation is none of those: its
-- rows are wrapped on the way in, each carries the colour the renderer chose for
-- it, it grows a piece at a time while a reply streams in, and it is capped. It
-- is a scrollback buffer, so that is what it is.

local util = require("util")
local env = require("environment")

local M = {}

--- CC-GUI, if it is installed.
--
-- An external file, like any other dependency, and optional in the sense that a
-- missing one is survivable: `M.open` answers nil and a reason, and the entry
-- point says the reason and falls back to the plain screen. A computer with no
-- `GUI.lua` beside the program gets a working program with a plainer screen, which
-- is a good deal better than a working program that dies on a require.
local haveGUI, GUI = pcall(require, "GUI")
M.GUI = haveGUI and GUI or nil

-- A computer's terminal is 51x19, and that is the size this has to look right at.
-- A screen smaller than this gets the plain screen instead: a title bar, a hint
-- line and an input field with two rows of conversation between them is a layout
-- nobody can read, which is worse than the plain one.
M.MIN_WIDTH = 24
M.MIN_HEIGHT = 8

-- How much conversation is kept. ComputerCraft's memory is the scarce resource
-- here, and a scrollback that grows for the life of a long session is the one
-- thing in this program that could bring it down. 1000 lines is a session's worth;
-- what falls off the top is counted and said on screen rather than lost quietly.
M.MAX_LINES = 1000
-- Trimmed in batches, because dropping one line at a time from a thousand-line
-- table is a thousand copies of a thousand entries.
M.TRIM_SLACK = 100

-- How many submitted lines the up and down keys walk through.
M.HISTORY = 50

-- How often the screen is repainted while text is arriving on its own.
--
-- A streamed reply comes in as a few hundred pieces, and a full repaint of a 51x19
-- screen is a few thousand cell writes, so repainting on each one would spend more
-- time drawing the answer than receiving it. Twenty a second is faster than the
-- eye can see a line appear, and costs one repaint in fifty pieces. Without a clock
-- to measure against -- a CraftOS too old for `os.timer`, or the test harness --
-- every write repaints, which is slower and never wrong.
M.REDRAW_INTERVAL = 0.05

-- Colour is used sparingly, as everywhere else in this project. The title bar and
-- the hint line are the two bars, and the buttons are lighter than the bar they sit
-- on so that they read as something to press rather than as more of the row.
--
-- The greys are chosen for contrast rather than for looks: CraftOS's `gray` is a
-- mid grey, `lightGray` a pale one and `darkGray` a near-black, so a title bar wants
-- `gray` under white text and a hint bar wants `darkGray` under `lightGray`.
local WHITE, BLACK = colors.white, colors.black
local LIGHT_GRAY, GRAY = colors.lightGray, colors.gray
local DARK_GRAY = colors.darkGray
local ACCENT = colors.lightBlue
local RED = colors.red

-- CraftOS key codes. The numbers are the stable part; `keys.getName` is consulted
-- afterwards for anything not in the table, so a binding survives a CraftOS that
-- spells its key names differently.
local KEY = {
  enter = 28,
  backspace = 14,
  tab = 43,
  del = 12,
  up = 208,
  down = 209,
  left = 210,
  right = 211,
  lshift = 256,
  rshift = 257,
  lctrl = 258,
  rctrl = 259,
  home = 274,
  fin = 275,
  pageup = 278,
  pagedown = 279,
}

-- CC-GUI names its keys through `keys.getName`, which spells some of these
-- differently, so both spellings are accepted. Every name compared against goes
-- through this.
local KEY_ALIASES = {
  ["page up"] = "pageup",
  ["page down"] = "pagedown",
  pageUp = "pageup",
  pageDown = "pagedown",
  pgup = "pageup",
  pgdn = "pagedown",
  ["return"] = "enter",
  escape = "esc",
  delete = "del",
  back = "backspace",
  shift = "lshift",
  ctrl = "lctrl",
}

-- CC-GUI redraws every control itself when it handles an event, with the unclipped
-- drawing described above. The redraw is the only part to neutralise: the click
-- dispatch and the input editing it does are both wanted, and this module redraws
-- the whole screen straight afterwards anyway.
local function noop() end

--- The first `width` bytes of `text`, never splitting a UTF-8 character.
--
-- A model writes prose, and prose is not always ASCII. Cutting a line at a byte in
-- the middle of a multi-byte character leaves the replacement glyph on screen,
-- which on a font with one is a black box at the end of every wrapped line. A
-- continuation byte is `10xxxxxx`, so walking back while the byte after the cut is
-- one lands on the start of the character instead.
local function cut(text, width)
  text = tostring(text or "")
  if #text <= width then
    return text
  end
  if width < 1 then
    return ""
  end
  local at = width
  while at > 1 do
    local byte = string.byte(text, at + 1)
    if not byte or byte < 0x80 or byte >= 0xC0 then
      break
    end
    at = at - 1
  end
  return text:sub(1, at)
end

--- `text` clipped to a box `width` wide and `height` rows tall.
--
-- A row too wide is cut and a row past the bottom is left out, which is what keeps
-- a widget inside its own space: nothing here can produce a string wider than
-- `width` or taller than `height` rows.
local function clip(text, width, height)
  if width < 1 or height < 1 then
    return ""
  end
  local rows, at = {}, 1
  while at <= #text and #rows < height do
    local stop = text:find("\n", at, true)
    rows[#rows + 1] = cut(stop and text:sub(at, stop - 1) or text:sub(at), width)
    if not stop then
      break
    end
    at = stop + 1
  end
  return table.concat(rows, "\n")
end

--- Break `text` to `width` columns, hanging the continuation lines under it.
--
-- The tool log indents its lines -- `"  * read /very/long/path"` -- and a wrapped
-- tool call whose every continuation lands back in column one reads as though the
-- model had said four separate things. So the line's own leading whitespace
-- becomes a hanging indent, widened by two. `util.wrap` does the breaking; this
-- only says where the pieces go.
local function wrapText(text, width)
  text = tostring(text or "")
  local indent = text:match("^[ \t]*") or ""
  local hanging = indent .. "  "
  local pieces = util.wrap(text:sub(#indent + 1), math.max(width - #indent, 8))
  local out = {}
  for index, piece in ipairs(pieces) do
    out[index] = (index == 1 and indent or hanging) .. piece
  end
  return out
end

local U = {}
U.__index = U

--- A UI over `raw`, or nil plus the reason there cannot be one.
--
-- The reasons are worth keeping apart, because they want different answers: no
-- `GUI.lua` is an install problem, a screen that is too small is a monitor that
-- is too small for this, and neither should stop the program running.
function M.open(raw, options)
  options = options or {}
  if not M.GUI then
    return nil, "CC-GUI (GUI.lua) is not installed beside the program"
  end
  if not raw or type(raw.getSize) ~= "function" then
    return nil, "there is no terminal to draw on"
  end
  local width, height = raw.getSize()
  if type(width) ~= "number" or type(height) ~= "number" then
    return nil, "the terminal did not report a size"
  end
  if width < M.MIN_WIDTH or height < M.MIN_HEIGHT then
    return nil, string.format("the terminal is only %dx%d, too small for the interface", width, height)
  end
  local system = env.system()
  if not system.pullEvent then
    return nil, "there is no event queue to read the keyboard from"
  end

  local self = setmetatable({}, U)
  self.screen = raw
  self.raw = raw -- so `environment.screen` hands a UI back unchanged
  self.system = system
  self.maxLines = options.maxLines or M.MAX_LINES
  self.historyLimit = options.history or M.HISTORY
  -- Whatever this machine calls the time. Read once here rather than per write,
  -- since the whole point is that the answer has to come from the same place every
  -- time, and `os.timer` is the wall clock where it exists and `os.clock` is not.
  self.now = system.timer or system.clock
  self.lastPaint = nil

  -- The transcript. `lines` are the logical ones, as the renderer produced them;
  -- `vlines` are the same conversation after wrapping, which is what the viewport
  -- indexes. Both are kept because wrapping is the expensive half: a redraw
  -- happens on every keystroke, and re-wrapping a thousand lines each time would
  -- make the interface slower than the program it is watching. A new line appends to
  -- both, `vstart` says where in `vlines` the logical one begins, and `trim` moves
  -- both together so the buffer stays as long as the cap says it is.
  self.lines = {}
  self.vlines = {}
  self.vcount = 0
  self.dropped = 0
  self.pending = { text = "", colour = WHITE }
  self.tail = nil -- the pending line, wrapped; nil when out of date
  self.bodyWidth = width
  self.fg, self.bg = WHITE, BLACK
  self.top = 1 -- first visible row of the buffer
  self.follow = true -- whether the viewport is pinned to the newest line
  self.history = {}
  self.historyIndex = 0
  self.stash = "" -- what was being typed when the operator reached for history

  self.prompt = "> "
  self.status = nil
  self.title = "opencode"
  self.subtitle = ""
  self.buttons = {}
  self.controls = {}
  self.modal = nil
  self.answer = nil
  self.clicked = nil
  self.choices = nil

  -- The screen surface, called with a dot or a colon.
  --
  -- ComputerCraft calls a screen's methods with a dot — `term.write(text)`, not
  -- `term:write(text)` — and so does the adapter this object is standing in for,
  -- which is the contract every caller in this program is already written against.
  -- The implementations stay on the metatable, where they read as methods and can
  -- reach the state; what goes on the instance is a closure that passes it on. One
  -- table, so a caller can hold it as a screen and as the thing that has a
  -- `readLine`, and neither of those is a different object from the other.
  --
  -- Both call forms are taken, because only one of them working is how `ui:write`
  -- ends up appending the word "table" to a conversation: the first argument of a
  -- colon call is the screen itself, and a text argument is a string, so one
  -- pointer comparison tells them apart. It is the same answer either way, which is
  -- the point -- a screen's methods are called both ways in the wild, and the one
  -- that quietly did nothing was the reason this needed finding.
  for name in pairs({
    write = true,
    clear = true,
    scroll = true,
    setCursorBlink = true,
    setCursorPos = true,
    getCursorPos = true,
    getSize = true,
    setTextColor = true,
    setBackgroundColor = true,
  }) do
    local method = U[name]
    self[name] = function(...)
      local first = ...
      if first == self then
        return method(self, select(2, ...))
      end
      return method(self, ...)
    end
  end
  -- A field, not a method, because the adapter's is a field too and this stands in
  -- for it. False is the whole of the answer: a GUI on a monitor is a GUI nobody
  -- can type into.
  self.isMonitor = false

  -- CC-GUI's input field. Its `textOffset` is the start of the visible window, so
  -- the field draws itself as a window onto whatever is typed, and this module only
  -- has to say how wide that window is.
  self.field = GUI.createInput("", 1, 1, 1, 1, BLACK, WHITE)
  self.field.borderColor = BLACK -- the library's border is a row either side, and
  -- the rows either side of this one are the hint line and the bottom of the screen
  self.field.monitor = raw
  self.field.cursorPos = 1

  self:relayout()
  return self
end

--- Whether this screen is a UI, so a caller can branch on the two at once.
function M.isUI(screen)
  return getmetatable(screen) == U
end

-- The screen surface
--
-- Below here is what the rest of the program sees. These are the methods
-- `environment.screen` produces, meaning what they always meant -- and they are
-- also how the transcript is filled, because `write` is the whole of it.

--- Append `text` to the conversation, honouring the newlines in it.
--
-- The tail with no newline after it is held back rather than committed, because a
-- streamed reply arrives in pieces and committing each one would put a line break
-- in the middle of every sentence. It is drawn as the live end of the
-- conversation instead, so the answer appears as it is written and still ends up
-- one line when it is finished.
function U:write(text)
  if text == nil then
    return nil
  end
  text = tostring(text)
  local at = 1
  while true do
    local stop = text:find("\n", at, true)
    self:append(stop and text:sub(at, stop - 1) or text:sub(at))
    if not stop then
      break
    end
    self:commit()
    at = stop + 1
  end
  -- Not `draw`: nothing here is waiting for a key, so there is nothing to force a
  -- repaint, and the whole reason a streamed answer appears as it is written is
  -- that this happens while the turn is still running.
  self:touch()
  return true
end

--- Repaint, unless one happened very recently.
--
-- Called from `write` rather than from the event loop because the two are not the
-- same: the event loop runs when the operator does something, and a reply that
-- arrives over the network arrives with nobody having touched anything. The clock
-- is what tells the two apart, and a machine without one simply repaints every
-- time.
function U:touch()
  if self.lastPaint and self.now() - self.lastPaint < M.REDRAW_INTERVAL then
    return false
  end
  self:draw()
  return true
end

--- Add to the line being built, breaking it if the colour changed.
--
-- A colour change is a line break, because that is what it is on a terminal: the
-- renderer writes the tool log in grey and the answer in white, and the whole point
-- of the two is that they are two different lines.
function U:append(piece)
  if piece == "" then
    return
  end
  if #self.pending.text > 0 and self.pending.colour ~= self.fg then
    self:commit()
  end
  self.pending.colour = self.fg
  self.pending.text = self.pending.text .. piece
  self.tail = nil
end

--- Finish the line being built, and start the next.
function U:commit()
  local line = { text = self.pending.text, colour = self.pending.colour, vstart = self.vcount + 1 }
  self.lines[#self.lines + 1] = line
  for _, piece in ipairs(wrapText(line.text, self.bodyWidth)) do
    self.vcount = self.vcount + 1
    self.vlines[self.vcount] = { text = piece, colour = line.colour }
  end
  self.pending.text = ""
  self.tail = nil
  self:trim()
end

--- Drop the oldest lines once there are enough of them to be worth the shifting.
--
-- Both tables move, and the second one is the reason. `vlines` is the larger of the
-- two -- a line of prose is often two or three rows -- so leaving the dropped rows in
-- it would mean the cap bounds the smaller table and a session that ran for hours
-- grew without limit in the one place the cap exists to stop it. So the rows go too,
-- and the line that says which row of the buffer each logical line starts at is
-- renumbered to match.
--
-- `lines` is left dense as well, which is not tidiness. `#` on a table with a hole
-- at the front returns whatever border the interpreter finds, and both this
-- function and the caller that wants the newest line want a count: with a hole,
-- `#self.lines` is 120 where there are 1000 lines, and nothing here can be trusted.
function U:trim()
  local count = #self.lines
  if count <= self.maxLines + M.TRIM_SLACK then
    return
  end
  local drop = count - self.maxLines
  local kept = count - drop
  -- How many rows the dropped lines took, which is how far everything moves up.
  local shift = self.lines[drop + 1].vstart - 1

  for index = 1, kept do
    self.lines[index] = self.lines[index + drop]
  end
  for index = kept + 1, count do
    self.lines[index] = nil
  end
  for _, line in ipairs(self.lines) do
    line.vstart = line.vstart - shift
  end

  local rows = self.vcount - shift
  for index = 1, rows do
    self.vlines[index] = self.vlines[index + shift]
  end
  for index = rows + 1, self.vcount do
    self.vlines[index] = nil
  end
  self.vcount = rows

  self.dropped = self.dropped + drop
  self.top = math.max(self.top, 1)
end

--- The conversation still being written, wrapped, as the rows it takes on screen.
--
-- Cached, because the tail is re-wrapped on every redraw otherwise and it is the
-- one part of the buffer that changes as the model speaks.
function U:tailLines()
  if self.pending.text == "" then
    return {}
  end
  if not self.tail then
    self.tail = {}
    for _, piece in ipairs(wrapText(self.pending.text, self.bodyWidth)) do
      self.tail[#self.tail + 1] = { text = piece, colour = self.pending.colour }
    end
  end
  return self.tail
end

--- Row `index` of the whole conversation, tail included.
function U:row(index)
  local line = self.vlines[index]
  if line then
    return line
  end
  return self:tailLines()[index - self.vcount]
end

--- How many rows the whole conversation takes.
--
-- Named for what it counts rather than what it is: `self.rows` is the layout, and
-- a method of the same name on the same object is the one that gets called.
function U:rowCount()
  return self.vcount + #self:tailLines()
end

--- Re-wrap everything, after the screen changed width.
--
-- A monitor can be resized while a program is running, and a transcript wrapped for
-- the old width would keep the old line breaks. Everything else about the layout is
-- recomputed on each redraw; this is the one part that is stored wrapped, so it is
-- the one part that has to be told.
function U:rewrap()
  self.vlines = {}
  self.vcount = 0
  for _, line in ipairs(self.lines) do
    line.vstart = self.vcount + 1
    for _, piece in ipairs(wrapText(line.text, self.bodyWidth)) do
      self.vcount = self.vcount + 1
      self.vlines[self.vcount] = { text = piece, colour = line.colour }
    end
  end
  self.tail = nil
  self.top = math.max(self.top, 1)
end

--- Forget the conversation, for `/clear` and for a fresh session.
function U:clearTranscript()
  self.lines = {}
  self.vlines = {}
  self.vcount = 0
  self.dropped = 0
  self.pending.text = ""
  self.tail = nil
  self.top = 1
  self.follow = true
end

--- The screen surface, as ComputerCraft and the adapter both call it.
--
-- These take `self` and are reached through the wrappers `M.open` puts on the
-- instance, so that `monitor.write(text)` finds a function whose only argument is
-- `text`. The wrappers are the boundary: a screen's methods are called with a dot --
-- `term.write(text)`, not `term:write(text)` -- and so are the adapter's, and this
-- object is standing in for one. Everything else in this module is called with a
-- colon, as the rest of Lua is.
--
-- `scroll` answers nil rather than scrolling, and that is not a gap: the
-- conversation is a buffer windowed onto the screen, so there is no scrolled-off
-- hardware state here to scroll, and a caller that asks is asking a question this
-- screen has a different word for.

function U:scroll()
  return nil
end

function U:clear()
  return self.screen.clear and self.screen.clear()
end

function U:setCursorBlink(state)
  return self.screen.setCursorBlink and self.screen.setCursorBlink(state)
end

function U:setCursorPos(x, y)
  return self.screen.setCursorPos and self.screen.setCursorPos(x, y)
end

function U:getCursorPos()
  return self.screen.getCursorPos()
end

function U:getSize()
  return self.screen.getSize()
end

function U:setTextColor(colour)
  self.fg = colour
end

function U:setBackgroundColor(colour)
  self.bg = colour
end

-- Chrome
--
-- What the operator sees around the conversation. All of it is a function of the
-- current size and the current state, and none of it is stored, so a redraw after a
-- resize comes out the same as a redraw after a keystroke.

--- Work out where everything goes, and how wide the input field is.
function U:relayout()
  local width, height = self.screen.getSize()
  local moved = width ~= self.width or height ~= self.height
  self.width, self.height = width, height
  self.rows = {
    header = 1,
    view = 2,
    -- Three rows are chrome: the title bar, the hint line, and the input. A
    -- computer's terminal is 19 rows, so the conversation gets 16 of them, which is
    -- most of a screen and rather more than the plain screen ever showed at once.
    viewHeight = math.max(height - 3, 1),
    hint = height - 1,
    input = height,
  }
  self.bodyWidth = width
  -- After the new width, not before. `rewrap` measures against `bodyWidth`, so
  -- calling it on the way in re-wraps the transcript to the width the screen just
  -- stopped being -- which looks correct until the next resize, where it is one
  -- size behind again and stays there.
  if moved then
    self:rewrap()
  end
  self:placeButtons()
  self:placeField()
end

--- The buttons on the hint line, right-aligned, created once and then moved.
--
-- Created once because CC-GUI keeps every control it has ever made in one list and
-- walks it on every click, so a button rebuilt on every redraw would make each
-- click slower than the last, without end. Dropped whole when they would leave no
-- room for the hint: half a row of buttons is half a row of buttons with no room
-- in them to read the labels.
function U:placeButtons()
  self.buttons = {}
  local wanted = {
    { label = "New", command = "/new" },
    { label = "Save", command = "/save" },
    { label = "Help", command = "/help" },
    { label = "Exit", command = "/exit" },
  }
  local needed = 0
  for _, button in ipairs(wanted) do
    needed = needed + #button.label + 3
  end
  needed = needed - 1
  -- Recorded rather than recomputed, because `drawHint` has to leave exactly the
  -- space the buttons took and a second count of the same thing is a second chance
  -- to get it wrong by a column.
  self.buttonsWidth = needed
  if needed + 12 > self.width then
    self.buttonsWidth = 0
    return
  end
  if #self.controls ~= #wanted then
    self.controls = {}
    for index, button in ipairs(wanted) do
      -- At rest `lightGray` on the `darkGray` bar, which is the one pairing on this
      -- screen with enough contrast to read at 51 columns; pressed, the other way
      -- round, so a press is visible while the timer that un-presses it runs.
      local control = GUI.createButton(button.label, 1, 1, #button.label + 2, 1,
        BLACK, LIGHT_GRAY, WHITE, GRAY)
      control.toggle = false -- a press, not a switch: it flashes and lets go
      control.timeout = 0.4
      control.monitor = self.screen
      control.onClick = function()
        self.clicked = wanted[index].command
      end
      self.controls[index] = control
    end
  end
  local x = self.width - needed + 1
  for index, button in ipairs(wanted) do
    local control = self.controls[index]
    control.x, control.y = x, self.rows.hint
    control.w, control.h = #button.label + 2, 1
    self.buttons[#self.buttons + 1] = {
      control = control,
      command = button.command,
      x = x,
      y = self.rows.hint,
      w = control.w,
      h = 1,
    }
    x = x + control.w + 1
  end
end

--- Put the input field after the prompt marker, running to the right edge.
--
-- The field's own width is what CC-GUI measures the text against, so it has to be
-- the real remaining width or its scroll window is off by the length of the marker.
function U:placeField()
  local marker = #self.prompt
  self.field.x = 1 + marker
  self.field.y = self.rows.input
  self.field.w = math.max(self.width - marker, 1)
  self.field.monitor = self.screen
end

--- The title bar: the program, what it is talking to, and what it is doing.
function U:drawHeader()
  local width = self.width
  self:fill(1, 1, width, 1, GRAY)

  -- The status is what changes and what is a guess about how long it will last, so
  -- it is what gets cut when the row is too narrow. Losing the middle of a model
  -- name is better than losing the word that says the program is still working.
  local status = self.status
  local statusText = status and (status.text or "") or ""
  local right = math.min(#statusText, math.floor(width / 2))
  local room = math.max(width - right - 1, 0)

  -- On a computer's terminal the model id is longer than the row, and the title
  -- would be the first thing to go: what the program is talking to is the useful
  -- half and the name is already in the shell's history and in the banner.
  local left = self.title
  if #left + 2 + #self.subtitle > room then
    left = ""
  end
  if left ~= "" then
    self:blit(1, 1, #left, 1, left, WHITE, GRAY)
  end
  if self.subtitle ~= "" and room > 4 then
    self:blit(#left + 2, 1, room - #left - 1, 1, self.subtitle, LIGHT_GRAY, GRAY)
  end
  if right > 0 then
    self:blit(width - right + 1, 1, right, 1, statusText, status and status.colour or WHITE, GRAY)
  end
end

--- The conversation, windowed.
function U:drawTranscript()
  local rows = self.rows
  local height = rows.viewHeight

  -- How many lines fell off the top is said on screen, in the one row that is about
  -- it, rather than the transcript simply starting in the middle of itself.
  local used = 0
  if self.dropped > 0 then
    used = 1
    self:blit(1, rows.view, self.width, 1,
      string.format("... %d earlier lines dropped", self.dropped), LIGHT_GRAY, BLACK)
  end

  local top = self:viewportTop(height - used)
  for offset = used, height - 1 do
    local line = self:row(top + offset - used)
    if not line then
      break
    end
    self:blit(1, rows.view + offset, self.width, 1, line.text, line.colour, BLACK)
  end
end

--- The hint line: what the keys do, and the buttons.
--
-- The bar under it is `darkGray` and the buttons on it are `lightGray`, the other
-- way round from the title bar. A `gray` bar with `gray` buttons on it is one grey
-- row with no distinction in it, and the point of the buttons is that they are the
-- parts of this screen you can press.
function U:drawHint()
  local row = self.rows.hint
  self:fill(1, row, self.width, row, DARK_GRAY)
  local room = math.max(self.width - self.buttonsWidth - 1, 0)
  if room > 0 then
    self:blit(1, row, room, 1, self:hint(), GRAY, DARK_GRAY)
  end
  for _, button in ipairs(self.buttons) do
    local control = button.control
    local background = control.state and control.activeBackgroundColor or control.backgroundColor
    local foreground = control.state and control.activeTextColor or control.textColor
    self:fill(button.x, button.y, button.x + button.w - 1, button.y, background)
    self:blit(button.x + 1, button.y, #control.text, 1, control.text, foreground, background)
  end
end

--- The text under the operator's hands, and the caret in it.
function U:drawInput()
  local row = self.rows.input
  self:fill(1, row, self.width, row, BLACK)
  self:blit(1, row, #self.prompt, 1, self.prompt, ACCENT, BLACK)

  local field = self.field
  -- CC-GUI keeps the scroll window itself, and walks it back while the caret moves
  -- left, so it can go negative before the caret reaches the start. Reading it
  -- clamped is cheaper than trying to follow the library's arithmetic.
  local offset = math.min(math.max(field.textOffset or 0, 0), math.max(#field.text - 1, 0))
  field.textOffset = offset
  local visible = cut(field.text:sub(offset + 1), field.w)
  if visible ~= "" then
    self:blit(field.x, row, field.w, 1, visible, field.textColor, field.backgroundColor)
  end

  -- The caret as a block, rather than as the terminal's own blinking cursor: the
  -- screen's cursor belongs to whatever drew last, and a field redrawn on every
  -- keystroke has no way to keep it still.
  local caret = math.min(math.max(field.cursorPos or 1, 1), #field.text + 1)
  local column = field.x + (caret - 1 - offset)
  if column >= field.x and column <= self.width then
    local char = field.text:sub(caret, caret)
    self:fill(column, row, column, row, field.textColor)
    self:blit(column, row, 1, 1, char == "" and " " or char, field.backgroundColor, field.textColor)
  end
  self.screen.setCursorPos(math.min(math.max(column, 1), self.width), row)
end

--- Where the permission dialog sits, and how big it is.
--
-- In one place, because the drawing and the click hit-test have to agree on it, and
-- a click test that is one row out would answer a different question from the one
-- on screen.
function U:modalBox()
  local modal = self.modal
  if not modal then
    return nil
  end
  local width, height = self.width, self.height
  local boxWidth = math.max(math.min(width - 4, 64), math.min(width, 16))
  local available = math.max(height - 3, 3)
  local contentRows = math.max(math.min(#modal.lines, available - 2), 1)
  local boxHeight = contentRows + 3 -- header, content, gap, choices
  local left = math.max(math.floor((width - boxWidth) / 2) + 1, 1)
  local top = math.max(math.min(math.floor((height - boxHeight) / 2), height - boxHeight), 1)
  return {
    left = left,
    top = top,
    right = left + boxWidth - 1,
    bottom = top + boxHeight - 1,
    width = boxWidth,
    contentTop = top + 1,
    contentRows = contentRows,
    choicesRow = top + boxHeight - 1,
  }
end

--- The dialog's own buttons, across its bottom row.
function U:modalChoices(box)
  local wanted = { { label = "y once", value = "y" }, { label = "a always", value = "a" }, { label = "n no", value = "n" } }
  local needed = 0
  for _, choice in ipairs(wanted) do
    needed = needed + #choice.label + 2
  end
  if needed > box.width - 2 then
    -- Too narrow for the words, so the letters alone; the hint line under the
    -- dialog says what each of them does.
    wanted = { { label = "y", value = "y" }, { label = "a", value = "a" }, { label = "n", value = "n" } }
    needed = 0
    for _, choice in ipairs(wanted) do
      needed = needed + #choice.label + 2
    end
  end
  local at = box.left + 1
  for _, choice in ipairs(wanted) do
    if at + #choice.label - 1 > box.right then
      break
    end
    choice.x, choice.y = at, box.choicesRow
    self.choices[#self.choices + 1] = choice
    at = at + #choice.label + 2
  end
end

--- The permission question, over the conversation.
function U:drawModal()
  local box = self:modalBox()
  if not box then
    return
  end
  local modal = self.modal

  self:fill(box.left, box.top, box.right, box.bottom, BLACK)
  self:fill(box.left, box.top, box.right, box.top, GRAY)
  self:blit(box.left + 1, box.top, box.width - 2, 1, modal.title, WHITE, GRAY)

  -- The question scrolls rather than being cut, and says how much is below,
  -- because a permission question whose patterns are off the bottom of a dialog is a
  -- question that gets answered without being read.
  local first = math.min(modal.scroll, math.max(#modal.lines - box.contentRows + 1, 1))
  for offset = 0, box.contentRows - 1 do
    local line = modal.lines[first + offset]
    if not line then
      break
    end
    self:blit(box.left + 1, box.contentTop + offset, box.width - 2, 1, line, WHITE, BLACK)
  end
  if #modal.lines > box.contentRows then
    local below = #modal.lines - (first + box.contentRows - 1)
    self:blit(box.left + 1, box.contentTop + box.contentRows - 1, box.width - 2, 1,
      string.format("... %d more line(s) below", below), LIGHT_GRAY, BLACK)
  end

  self.choices = {}
  self:modalChoices(box)
  self:fill(box.left, box.choicesRow, box.right, box.choicesRow, GRAY)
  for _, choice in ipairs(self.choices) do
    self:blit(choice.x, choice.y, #choice.label, 1, choice.label, BLACK, LIGHT_GRAY)
  end
  if modal.note and modal.note ~= "" then
    self:blit(box.left + 1, box.choicesRow - 1, box.width - 2, 1, modal.note, LIGHT_GRAY, BLACK)
  end
end

--- Everything, in order.
function U:draw()
  -- Recorded here rather than in `touch`, so that a repaint the event loop asked
  -- for counts as a repaint and `touch` does not immediately add a second one on
  -- top of it.
  self.lastPaint = self.now and self.now() or nil
  self:relayout()
  self.screen.clear()
  self.screen.setTextColor(WHITE)
  self.screen.setBackgroundColor(BLACK)
  self:drawHeader()
  self:drawTranscript()
  self:drawHint()
  self:drawInput()
  self:drawModal()
end

-- Bounded drawing
--
-- The two primitives everything above goes through, and the whole of the boundary
-- rule CC-GUI does not have. Both take already-bounded arguments, so a mistake in
-- the layout costs a truncated label rather than a screenful of somebody else's
-- text.

--- Write `text` at (x, y), inside a box `width` wide and `height` rows tall.
--
-- Clipped to the box first, so a widget cannot spill into its neighbour, and then
-- to the screen: an origin off the edge is dropped outright rather than clamped,
-- because a clamped origin would put the text somewhere the layout did not intend
-- and a write past the right edge carries onto the next row on a real terminal.
function U:blit(x, y, width, height, text, foreground, background)
  local screenWidth, screenHeight = self.width, self.height
  x, y = math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0)
  if x < 1 or y < 1 or x > screenWidth or y > screenHeight then
    return false
  end
  width = math.min(math.floor(width or 0), screenWidth - x + 1)
  height = math.min(math.floor(height or 0), screenHeight - y + 1)
  local clipped = clip(text, width, height)
  if clipped == "" then
    return false
  end
  GUI.drawText(self.screen, x, y, foreground or WHITE, background or BLACK, clipped)
  return true
end

--- Fill a box, clamped to the screen.
function U:fill(x1, y1, x2, y2, colour)
  local width, height = self.width, self.height
  x1, x2 = math.min(x1, x2), math.max(x1, x2)
  y1, y2 = math.min(y1, y2), math.max(y1, y2)
  x1, y1 = math.max(x1, 1), math.max(y1, 1)
  x2, y2 = math.min(x2, width), math.min(y2, height)
  if x1 > x2 or y1 > y2 then
    return false
  end
  GUI.fillRegion(self.screen, x1, y1, x2, y2, colour)
  return true
end

-- The viewport
--
-- Which rows of the conversation are on screen, and how the operator moves through
-- them. `follow` is the whole of it: pinned to the newest row, so a reply that is
-- arriving stays in view, and released as soon as the operator scrolls back.

--- The newest row a viewport `height` rows tall can start at.
--
-- One definition, because the two places that need it have to agree. `drawTranscript`
-- worked this out as `rowCount() - height + 1` and the scroll arithmetic as
-- `rowCount() - (height - 1) + 1`, which is a different row: scrolling down to the
-- bottom of a full conversation then moved the view one row past it and said the
-- conversation was not scrolled when it was, so the next line to arrive pulled the
-- screen away from the answer.
function U:bottomRow(height)
  return math.max(self:rowCount() - math.max(height, 1) + 1, 1)
end

--- The first visible row of a viewport `height` rows tall.
--
-- The viewport is allowed to run past the end of the conversation -- there is
-- nothing to draw down there -- so a short one sits at the top of its space rather
-- than being stretched to fill it.
function U:viewportTop(height)
  if self.follow then
    return self:bottomRow(height)
  end
  return math.min(math.max(self.top, 1), self:bottomRow(height))
end

--- Move the viewport by `delta` rows.
function U:scrollBy(delta)
  local last = self:bottomRow(self.rows.viewHeight)
  if self.follow then
    self.top = last
  end
  self.top = math.min(math.max(self.top + delta, 1), last)
  -- Past the newest row is not "scrolled": the conversation is pinned again, so the
  -- next line to arrive stays in view.
  self.follow = self.top >= last
end

function U:scrollToEnd()
  self.follow = true
end

function U:scrollToStart()
  self.follow = false
  self.top = 1
end

-- State the rest of the program sets

--- What the title bar says the program is doing.
function U:setStatus(text, colour)
  if text == nil then
    self.status = nil
  else
    self.status = { text = tostring(text), colour = colour or LIGHT_GRAY }
  end
end

--- The model and the agent, beside the title.
function U:setSubtitle(text)
  self.subtitle = tostring(text or "")
end

function U:setTitle(text)
  self.title = tostring(text or "")
end

--- The hint line. A method, so a dialog can say what it wants instead.
function U:hint()
  if self.modal then
    return "y / a / n, or type why not"
  end
  if self.follow then
    return "enter sends  /help lists  pgup scrolls"
  end
  return "pgdn follows  enter sends  /help lists"
end

-- The field

function U:inputText()
  return self.field.text
end

function U:setInputText(text)
  self.field.text = text or ""
  self.field.textOffset = 0
  self.field.cursorPos = 1
end

function U:resetInput()
  self:setInputText("")
end

function U:submittedText()
  return util.trim(self.field.text)
end

-- Events

--- The name of a key code: the table first, `keys.getName` second.
--
-- The table is first because the numbers are documented and the names are a
-- convenience that spells half of them differently.
function U:keyName(code)
  for name, value in pairs(KEY) do
    if value == code then
      return name
    end
  end
  local name
  if self.system.keyName then
    local ok, named = pcall(self.system.keyName, code)
    if ok then
      name = named
    end
  end
  if name and name ~= "unknown" then
    return KEY_ALIASES[name] or name
  end
  return nil
end

--- Hand one event to CC-GUI, with its redraw switched off.
--
-- The click dispatch and the input editing are wanted; the redraw is not, because it
-- would repaint the screen with the unclipped drawing described at the top of this
-- file. `pcall` because a library error on a keystroke should show up on the screen
-- rather than take the program down in the middle of a conversation.
function U:delegate(event)
  local drawAll = GUI.drawAll
  GUI.drawAll = noop
  local ok, err = pcall(GUI.handleEvent, event)
  GUI.drawAll = drawAll
  if not ok then
    self:setStatus("input error: " .. tostring(err), RED)
    return false
  end
  return true
end

--- One event, and what it means here.
--
-- Returns a table with an `action`, or nil. The keys this screen has an opinion
-- about are answered here; everything else goes to CC-GUI, which owns the text in
-- the field. The result is a table rather than a loose value because there are six
-- different things an event can turn out to be, and a number that means "scroll
-- up" and a string that means "scroll up" are not distinguishable at the call site.
function U:handle(event)
  local name = event[1]

  if name == "mouse_click" then
    local x, y = event[3], event[4]
    for _, choice in ipairs(self.choices or {}) do
      if x >= choice.x and x < choice.x + #choice.label and y == choice.y then
        self.answer = choice.value
        return { action = "submit" }
      end
    end
    self.clicked = nil
    if not self:hitButton(x, y) then
      return nil
    end
    self:delegate(event)
    return self.clicked and { action = "command", text = self.clicked } or nil
  end

  if name == "monitor_touch" then
    -- The interface is on the terminal, so a touch on some other screen is not ours.
    -- CC-GUI would try to match the monitor against every widget's screen, find
    -- they differ, and dispatch nothing -- which is right, but for a long reason.
    return nil
  end

  if name == "key" or name == "key_up" then
    local key = self:keyName(event[2])
    -- On the press, never on the release. ComputerCraft sends both, and a key
    -- handled on both is a key that happens twice: holding the up arrow walks back
    -- through the history two entries per press, and holding enter submits the empty
    -- line twice. The release is CC-GUI's, and CC-GUI is the only thing that wants
    -- it -- it does the text editing on `key_up` and ignores `key` altogether.
    if name == "key_up" then
      self:delegate(event)
      return nil
    end
    if key == "enter" then
      return { action = "submit" }
    elseif key == "up" then
      return { action = "history", direction = -1 }
    elseif key == "down" then
      return { action = "history", direction = 1 }
    elseif key == "pageup" then
      return { action = "scroll", delta = -math.max(self.rows.viewHeight - 1, 1) }
    elseif key == "pagedown" then
      return { action = "scroll", delta = math.max(self.rows.viewHeight - 1, 1) }
    elseif key == "home" or key == "lctrl" or key == "rctrl" then
      return { action = "start" }
    elseif key == "fin" then
      return { action = "end" }
    end
    -- Every other key press goes to CC-GUI, which owns the text editing.
    self:delegate(event)
    return nil
  end

  if name == "char" or name == "timer" then
    -- Timers are forwarded because that is how CC-GUI un-presses a button.
    self:delegate(event)
    return nil
  end

  return nil
end

--- True when (x, y) is one of this screen's own buttons.
--
-- Checked here as well as inside CC-GUI, whose hit test is one column and one row
-- wider than the button it drew. That extra column is the gap between two buttons,
-- and letting it through would mean a click in the gap could press the button to
-- the left of it.
function U:hitButton(x, y)
  for _, button in ipairs(self.buttons) do
    if x >= button.x and x < button.x + button.w and y >= button.y and y < button.y + button.h then
      return true
    end
  end
  return false
end

--- One blocking wait for something to happen, or nil if there will not be one.
--
-- Nil is the end of input, which is what CraftOS's `read` reports and what the REPL
-- exits on. A hand-rolled key loop has to be able to hear it too, or a terminal that
-- has gone away leaves the loop spinning on a nil event forever -- and the only thing
-- that tells a program from a program that is stuck is whether it comes back.
function U:pull()
  local event = { self.system.pullEvent() }
  if event[1] == nil then
    return nil
  end
  return event
end

--- Move through the submitted lines with the up and down keys.
--
-- Not CraftOS's history -- `read` is not used here, so there is no history to have.
-- This is a ring of what this session has been asked, which is the part of it worth
-- having. The entry being typed is stashed, so walking to the oldest and back again
-- does not lose it.
function U:historyStep(direction)
  local count = #self.history
  if count == 0 then
    return
  end
  -- Each end of the walk is its own end. Up at the oldest entry and down at the
  -- line being typed are both already as far as it goes, and one clamp serving both
  -- directions turns the walk into a ring: up past the oldest drops the operator out
  -- of the history and back onto the stashed line, and down onto the stashed line
  -- throws it away and steps into the history a second time.
  if self.historyIndex == 0 then
    if direction > 0 then
      return
    end
    self.stash = self.field.text
    self.historyIndex = 1
    self:setInputText(self.history[1])
    return
  end
  local next = self.historyIndex + (direction < 0 and 1 or -1)
  -- Down to nothing is the line being typed, which sits outside the history
  -- entirely; up past the oldest stays on the oldest. Both ends are a step too far,
  -- and the direction says which end it is -- so reading the direction rather than
  -- the index is what keeps a single clamp from serving both.
  if next < 1 then
    self.historyIndex = 0
    self:setInputText(self.stash)
    return
  end
  if next > count then
    self.historyIndex = count
    self:setInputText(self.history[count])
    return
  end
  self.historyIndex = next
  self:setInputText(self.history[next])
end

--- Remember a submitted line, newest first, without repeats.
function U:pushHistory(text)
  if text == nil or text == "" then
    return
  end
  for index = #self.history, 1, -1 do
    if self.history[index] == text then
      table.remove(self.history, index)
    end
  end
  table.insert(self.history, 1, text)
  while #self.history > self.historyLimit do
    table.remove(self.history)
  end
  self.historyIndex = 0
end

--- Run until the operator submits. Returns the text, or nil if the program is closing.
--
-- This is the `read` the plain screen uses, with the same job and none of the
-- terminal echo, so the field, the caret and the history are drawn where they can
-- be seen. A clicked button answers with the command it stands for, so there is one
-- implementation of `/help` rather than two.
function U:readLine(options)
  options = options or {}
  self.mode = "prompt"
  self.modal = nil
  self.answer = nil
  self.prompt = options.prompt or "> "
  self.choices = {}
  self:relayout()
  self:resetInput()
  if options.text then
    self:setInputText(options.text)
  end
  self.historyIndex = 0
  self:scrollToEnd()
  self:draw()

  while true do
    local event = self:pull()
    if not event then
      -- The terminal is gone, so there is nobody left to answer. The field is
      -- cleared and the conversation left as it is, because the REPL's exit path
      -- runs on this nil and a screen with the last line still in it is what the
      -- operator last saw.
      self:relayout()
      self:resetInput()
      self:draw()
      return nil
    end
    local result = self:handle(event)
    local action = result and result.action
    if action == "submit" then
      local text = self.field.text
      self:pushHistory(text)
      self:relayout()
      self:resetInput()
      self:draw()
      return text
    elseif action == "command" then
      self:relayout()
      self:resetInput()
      self:draw()
      return result.text
    elseif action == "history" then
      self:historyStep(result.direction)
    elseif action == "scroll" then
      self:scrollBy(result.delta)
    elseif action == "start" then
      self:scrollToStart()
    elseif action == "end" then
      self:scrollToEnd()
    end
    self:draw()
  end
end

--- Put the permission question on screen and wait for an answer.
--
-- `spec` is what the permission module would otherwise print, and the answer is the
-- same string `read` would have produced: `"y"`, `"a"`, `"n"`, or
-- `"feedback:<what the operator said>"`. Asking it here rather than through `read`
-- is what puts the question on the screen the operator is looking at: `read`
-- prints nothing, so the question went to a monitor nobody was reading while the
-- answer was typed blind at the terminal.
function U:ask(spec)
  spec = spec or {}
  self.mode = "ask"
  self.answer = nil
  self.modal = {
    title = string.format("Permission: %s", spec.permission or "?"),
    lines = self:questionLines(spec),
    note = spec.title,
    scroll = 1,
  }
  self.prompt = "> "
  self.choices = {}
  self:relayout()
  self:resetInput()
  self:draw()

  while true do
    local event = self:pull()
    if not event then
      -- Nobody left to ask, and the question cannot be answered. The dialog is taken
      -- off the screen and the empty answer goes back, which the permission module
      -- reads as a refusal: the safe direction to fail unattended.
      self.modal = nil
      self.choices = {}
      self:relayout()
      self:resetInput()
      self:draw()
      return ""
    end
    local result = self:handle(event)
    local action = result and result.action
    if action == "submit" then
      local reply = self.answer or self:submittedText()
      self.modal = nil
      self.answer = nil
      self.choices = {}
      self:relayout()
      self:resetInput()
      self:draw()
      return reply
    elseif action == "history" then
      -- Up and down scroll the question rather than the conversation behind it,
      -- because the part of the question that is off the bottom is the part being
      -- asked about.
      self.modal.scroll = math.max(1, self.modal.scroll + (result.direction < 0 and 1 or -1))
    elseif action == "scroll" then
      self.modal.scroll = math.max(1, self.modal.scroll + (result.delta < 0 and 1 or -1))
    end
    self:draw()
  end
end

--- The question, as the wrapped lines the dialog shows.
function U:questionLines(spec)
  local width = math.max(math.min(self.width - 6, 58), 10)
  local lines = {}
  local patterns = spec.patterns
  if patterns == nil or #patterns == 0 then
    patterns = { "*" }
  end
  for index, pattern in ipairs(patterns) do
    if index > 6 then
      lines[#lines + 1] = string.format("  ...and %d more", #patterns - 6)
      break
    end
    for _, piece in ipairs(wrapText("  " .. pattern, width)) do
      lines[#lines + 1] = piece
    end
  end
  return lines
end

return M

end

-- init.lua
__sources["cli"] = function(...)
do end
-- opencode for ComputerCraft: the entry point.
--
-- Two ways to use it:
--
--   opencode                     interactive, on the computer's own terminal
--   opencode "list the programs" one turn, print the answer, exit
--   opencode run "..."           the same, spelled out
--
-- The interactive session draws itself with CC-GUI: a title bar, the conversation,
-- a hint line and an input field, with the conversation kept so it can be scrolled
-- back through. `--plain` is the screen that was here before -- printed text,
-- wrapped, on a monitor if one is attached -- and it is still what a one-shot
-- `opencode "<question>"` uses, because the point of a one-shot is the output that
-- is left on the terminal when the program exits.
--
-- Everything below is presentation: argument parsing, the REPL, and rendering the
-- agent's events onto a screen. The work itself is in src/agent.lua.

--- Locate the library relative to this program, so the modular checkout and the
--- single-file bundle both work without editing `package.path` by hand.
--
-- ComputerCraft hands every program its own `require` and its own `package`, and it
-- resolves relative search patterns against *the program's own directory*. That
-- directory is wherever the program was found, which is not wherever its library
-- is: `init.lua` sits beside `src/`, one level above the modules. So a plain
-- `require("util")` looks for `<dir>/util.lua`, finds nothing, and the program dies
-- before it can print a word.
--
-- Three absolute entries fix it, and the absoluteness is the whole of the fix. CC
-- reads `package.path` each time it looks a name up, so rebinding the field is
-- enough; and a pattern beginning with `/` is used as written, which is the one
-- case where the program directory is not joined onto the front of it. Without that
-- the entries would be resolved against the directory they were meant to get away
-- from.
--
-- The `src/` prefix cannot be a fourth entry, because a `src/?.lua` pattern only
-- answers to a name spelled `src/util` -- and spelling it that way on every require
-- would leave the bundle to unspell it. A path entry is the only way to say it.
--
-- A bundled program needs none of this: the bundle installs every module into
-- `package.preload` under its bare name, so the first searcher answers before the
-- path is ever consulted.
--
-- Once, too. The path is prepended, so a second call would prepend it again -- no
-- harm on a computer, which runs this once, but a test suite that loads the entry
-- point twenty times would leave twenty copies behind it.
local located = false

local function bootstrap()
  if located then
    return
  end
  located = true

  local program = (shell and shell.getRunningProgram and shell.getRunningProgram()) or ""
  local directory = program:match("^(.*)/[^/]*$")
  -- A program at the root matches as the empty string, which is already the one
  -- separator a path needs -- `"" .. "/?.lua"` is `/?.lua`. So only a program with
  -- no directory in it at all falls back to a relative path, and a doubled separator
  -- in the name is collapsed rather than joined.
  if not directory then
    directory = "."
  elseif directory == "/" then
    directory = ""
  end
  package.path = table.concat({
    directory .. "/?.lua",
    directory .. "/src/?.lua",
    directory .. "/src/?/init.lua",
    package.path,
  }, ";")
end

bootstrap()

local env = require("environment")
local config = require("config")
local provider = require("provider")
local session = require("session")
local agent = require("agent")
local registry = require("tool/registry")
local permission = require("permission")
local ui = require("ui")

local M = {}

M.AGENTS = { "build", "general", "plan", "explore" }

-- Colour is used sparingly: a monitor in a dark room does not need decoration, and
-- the light palette is a guess that is wrong about half the time anyway.
local WHITE, LIGHT_GRAY, YELLOW, RED = colors.white, colors.lightGray, colors.yellow, colors.red

--- Everything one invocation needs, rebuilt when /model or /agent changes it.
M.state = {}

local function out(monitor, text, colour)
  if not monitor then
    return
  end
  if colour then
    monitor.setTextColor(colour)
  end
  monitor.write(text)
  monitor.setTextColor(WHITE)
end

-- The screen wraps whatever it is given, so this only adds the newline. The
-- wrapping used to live here, which left the answer itself unwrapped: it arrives
-- as one delta and was written straight out, so a reply that was a list of file
-- paths lost everything past the right edge. It belongs on the screen instead,
-- where the REPL, the tool log and the permission prompt all pass through.
local function line(monitor, text, colour)
  out(monitor, tostring(text) .. "\n", colour)
end

--- Shorten a tool's input to one line, for the activity log.
local function summarise(part)
  local input = part.state.input or {}
  for _, key in ipairs({ "filePath", "path", "pattern", "command", "url" }) do
    if type(input[key]) == "string" then
      local value = input[key]:gsub("\n", " ")
      if #value > 48 then
        value = value:sub(1, 45) .. "..."
      end
      return value
    end
  end
  for key, value in pairs(input) do
    if type(value) ~= "table" then
      return tostring(key) .. "=" .. tostring(value)
    end
  end
  return ""
end

--- The GUI the interactive session is drawing on, or nil.
--
-- A lookup rather than a parameter, because the whole program draws on one screen
-- and threading it through the agent loop to reach a title bar would be threading
-- a screen through the agent loop to reach a title bar.
local function screenUI()
  return M.state and M.state.ui
end

--- Render the agent's events. This is the whole UI: one line per tool call, the
--- answer as it arrives, and a usage footer.
local function renderer(monitor)
  -- What the title bar says is happening. A no-op on a plain screen, which has no
  -- title bar, and cheap enough to be called for every delta of a streamed reply.
  local function status(text, colour)
    local screen = screenUI()
    if screen then
      screen:setStatus(text, colour)
    end
  end

  return function(event)
    if event.type == "text" then
      out(monitor, event.delta)
      status("writing", LIGHT_GRAY)
    elseif event.type == "reasoning" then
      line(monitor, "(reasoning) " .. event.text, LIGHT_GRAY)
      status("thinking", LIGHT_GRAY)
    elseif event.type == "step" then
      status(string.format("step %d/%d", event.step, event.max), LIGHT_GRAY)
    elseif event.type == "tool_start" then
      local part = event.part
      line(monitor, "  * " .. part.tool .. " " .. summarise(part), LIGHT_GRAY)
      status(part.tool, LIGHT_GRAY)
    elseif event.type == "tool_end" then
      local part = event.part
      -- The bar goes quiet once a tool is done, so a long run shows a tool name
      -- while it is working and nothing at all while the answer is being written.
      status(nil)
      if part.state.status == "error" then
        line(monitor, "    ! " .. tostring(part.state.error), RED)
        status("error", RED)
      else
        -- A tool whose title is the thing the start line already named — read
        -- and webfetch, mostly — has nothing to add by repeating it.
        local detail = part.state.title or ""
        if detail ~= "" and detail ~= summarise(part) then
          line(monitor, "    " .. detail, LIGHT_GRAY)
        end
      end
    elseif event.type == "step_end" then
      local tokens = event.message.tokens
      if tokens and tokens.input and tokens.input > 0 then
        line(monitor, string.format("  (%d in, %d out)", tokens.input, tokens.output), LIGHT_GRAY)
      end
    elseif event.type == "compacted" then
      -- The conversation was summarised, so an answer may now rest on the
      -- summary. Saying so beats silently losing the detail.
      line(monitor, "(summarised the earlier conversation to fit the context window)", LIGHT_GRAY)
    elseif event.type == "error" then
      line(monitor, tostring(event.message), RED)
      status("error", RED)
    elseif event.type == "aborted" then
      line(monitor, "(aborted)", YELLOW)
    end
  end
end

--- Resolve the configured model, returning nil plus the reason it cannot be used.
local function resolveModel(current)
  local resolved, err = provider.resolve(current.config, current.config.model)
  if not resolved then
    return nil, err
  end
  return resolved
end

--- Build the run context from the current state.
local function buildContext(monitor)
  local current = M.state
  return {
    session = current.session,
    config = current.config,
    model = current.model,
    smallModel = current.smallModel,
    agent = current.agent,
    root = current.root,
    cwd = current.cwd,
    permission = permission.ruleset(current.config.permission),
    enabled = current.enabled,
    monitor = monitor,
    stream = current.stream,
    on = renderer(monitor),
    -- ComputerCraft gives a program no way to be interrupted while it runs, so
    -- this never fires. It is here so the loop has one place to ask.
    aborted = function()
      return false
    end,
  }
end

-- Slash commands

local function banner(monitor, current)
  line(monitor, "opencode for ComputerCraft", LIGHT_GRAY)
  line(monitor, string.format("model: %s   agent: %s   dir: %s", current.config.model, current.agent, current.cwd), LIGHT_GRAY)
  line(monitor, "Type a question, or /help for commands.", LIGHT_GRAY)
end

local function help(monitor)
  line(monitor, "Commands:")
  line(monitor, "  /help           this list", LIGHT_GRAY)
  line(monitor, "  /model          show the current model", LIGHT_GRAY)
  line(monitor, "  /model <id>     switch to provider/model", LIGHT_GRAY)
  line(monitor, "  /models         models the config can reach", LIGHT_GRAY)
  line(monitor, "  /providers      the known providers and their keys", LIGHT_GRAY)
  line(monitor, "  /agent          show the current agent", LIGHT_GRAY)
  line(monitor, "  /agent <name>   switch agent (" .. table.concat(M.AGENTS, ", ") .. ")", LIGHT_GRAY)
  line(monitor, "  /tools          list the available tools", LIGHT_GRAY)
  line(monitor, "  /new            start a new session", LIGHT_GRAY)
  line(monitor, "  /save           save the session to disk", LIGHT_GRAY)
  line(monitor, "  /exit           quit", LIGHT_GRAY)
  line(monitor, "Anything else is sent to the model.", LIGHT_GRAY)
end

--- `/models` shows what the config can actually reach. A provider with no `models`
--- block cannot be listed, because nothing in the config says which model ids it
--- serves, so the hint points at the file rather than guessing.
--
--- The defaults declare one model, so this is not what a fresh install shows any
--- more. It is kept as a guard: `merge` only ever adds keys, so a config cannot
--- undeclare the default, but a future default that shipped none would otherwise
--- print an empty list and say nothing about why.
local function listModels(monitor, current)
  local models = provider.availableModels(current.config)
  if #models == 0 then
    line(monitor, "No models are listed in the config.", YELLOW)
    line(monitor, 'Add one under "provider" in opencode.json:', LIGHT_GRAY)
    line(monitor, '  "provider": {"groq": {"models": {"llama-3.3-70b": {"name": "Llama 3.3 70B"}}}}', LIGHT_GRAY)
    return
  end
  for _, entry in ipairs(models) do
    local note = entry.available and "" or "  (no api key)"
    line(monitor, string.format("  %-36s %-16s%s", entry.id, entry.provider, note), entry.available and WHITE or LIGHT_GRAY)
  end
end

local function listProviders(monitor, current)
  local providers = provider.list(current.config)
  local ids = {}
  for id in pairs(providers) do
    ids[#ids + 1] = id
  end
  table.sort(ids)
  for _, id in ipairs(ids) do
    local entry = providers[id]
    local key = provider.apiKey(current.config, entry)
    local note = key and "" or "  (no api key)"
    line(monitor, string.format("  %-12s %-14s %s%s", id, entry.name or id, entry.base or "(no base url)", note),
      key and WHITE or LIGHT_GRAY)
  end
end

local function listTools(monitor, current)
  for _, tool in ipairs(registry.list(current.enabled)) do
    line(monitor, "  " .. tool.id)
  end
end

--- Give the session a generated name, once, just before it is saved.
--
-- The first question makes a far better title than "New session", but naming
-- costs a request, so it happens on save rather than on every turn. A failure
-- leaves the default title: a session with an unhelpful name is a minor
-- inconvenience, not a broken run, so nothing is reported.
local function nameSession(monitor)
  local current = M.state
  if current.config.title == false or current.session.title ~= session.DEFAULT_TITLE then
    return
  end
  local name = agent.title(buildContext(monitor), session.text(session.firstUserMessage(current.session)))
  if name and name ~= "" then
    current.session.title = name
  end
end

--- Write the session to disk, naming it first if it still has no name.
local function save(monitor)
  nameSession(monitor)
  local path, err = session.save(M.state.session)
  if path then
    line(monitor, "saved " .. path, LIGHT_GRAY)
  else
    line(monitor, "could not save: " .. tostring(err), RED)
  end
end

--- Handle a slash command. Returns false when the REPL should stop.
local function command(monitor, input)
  local current = M.state
  local verb, rest = input:match("^/(%S+)%s*(.*)$")
  if not verb then
    return true
  end
  rest = rest:gsub("^%s+", ""):gsub("%s+$", "")

  if verb == "exit" or verb == "quit" then
    return false
  elseif verb == "help" then
    help(monitor)
  elseif verb == "model" then
    if rest == "" then
      line(monitor, current.config.model)
    else
      local resolved, err = provider.resolve(current.config, rest)
      if not resolved then
        line(monitor, err, RED)
      else
        current.config.model = rest
        current.model = resolved
        line(monitor, "model: " .. rest)
      end
    end
  elseif verb == "models" then
    listModels(monitor, current)
  elseif verb == "providers" then
    listProviders(monitor, current)
  elseif verb == "agent" then
    if rest == "" then
      line(monitor, current.agent)
    else
      local known = false
      for _, name in ipairs(M.AGENTS) do
        known = known or name == rest
      end
      if not known then
        line(monitor, "Unknown agent '" .. rest .. "'. Try: " .. table.concat(M.AGENTS, ", "), RED)
      else
        current.agent = rest
        line(monitor, "agent: " .. rest)
      end
    end
  elseif verb == "tools" then
    listTools(monitor, current)
  elseif verb == "new" then
    current.session = session.new()
    line(monitor, "new session " .. current.session.id, LIGHT_GRAY)
  elseif verb == "save" then
    save(monitor)
  else
    line(monitor, "Unknown command /" .. verb .. ". Try /help.", RED)
  end
  return true
end

-- Turns

--- Run one user turn, printing the result. Returns the message, or nil plus the
--- reason the run stopped early.
local function turn(monitor, text)
  local current = M.state
  session.addUser(current.session, text)
  return agent.run(buildContext(monitor))
end

--- Report whatever ended the run other than a normal finish.
local function reportStop(monitor, message, reason)
  if reason == nil or reason == "aborted" then
    return
  end
  if message and message.error then
    return
  end
  line(monitor, tostring(reason), YELLOW)
end

--- Read one line from the operator, or nil at end of input.
--
-- Two implementations, and the choice is the screen rather than a preference. On a
-- plain screen this hands the question to CraftOS's `read`: the cursor and the line
-- editing are `read`'s own business there, and it echoes what is typed and leaves
-- the cursor wherever the operator finished, which the screen's wrapping knows
-- nothing about — so the blank line the loop writes before the next prompt is what
-- puts the two back in agreement.
--
-- On a GUI it is the screen's own field, which is drawn where it can be seen and
-- has the history and the caret drawn with it. `read` cannot be used there: the
-- GUI has taken the screen, so what `read` echoes lands on top of the conversation
-- and then scrolls away with the next repaint.
local function prompt()
  local screen = screenUI()
  if screen then
    return screen:readLine()
  end
  return env.readLine()
end

local function finish(monitor)
  if M.state.autoSave then
    save(monitor)
  end
end

--- The interactive loop.
local function repl(monitor)
  local screen = screenUI()
  banner(monitor, M.state)
  if screen then
    -- What is in the banner is what the title bar has room for, and the title bar
    -- is what is in view when the conversation has scrolled: the model and the
    -- agent, not the line of text that is already on screen.
    screen:setSubtitle(string.format("%s  %s", M.state.config.model, M.state.agent))
    screen:setStatus("idle")
  end
  while true do
    if not screen then
      line(monitor, "")
      out(monitor, "> ", LIGHT_GRAY)
    end
    local input = prompt()
    if input == nil then
      return
    end
    input = input:gsub("^%s+", ""):gsub("%s+$", "")
    if input == "" then
      -- nothing typed; ask again
    elseif input:sub(1, 1) == "/" then
      if not command(monitor, input) then
        finish(monitor)
        return
      end
    elseif M.state.model == nil then
      line(monitor, "No usable model. Try /model, or fix the config.", RED)
    else
      reportStop(monitor, turn(monitor, input))
    end
  end
end

--- One turn and out, for `opencode "<question>"`.
local function once(monitor, text)
  if M.state.model == nil then
    line(monitor, M.state.error or "No model configured.", RED)
    return 1
  end
  local message, reason = turn(monitor, text)
  line(monitor, "")
  reportStop(monitor, message, reason)
  finish(monitor)
  -- A turn that ended in a provider or transport error is a failed run, and a
  -- caller watching the exit code should be able to tell.
  if not message or message.error or reason then
    return 1
  end
  return 0
end

-- Argument parsing

local function usage(monitor)
  line(monitor, "opencode for ComputerCraft")
  line(monitor, "")
  line(monitor, "  opencode                    interactive session", LIGHT_GRAY)
  line(monitor, "  opencode <question>         one turn, then exit", LIGHT_GRAY)
  line(monitor, "  opencode run <question>     the same, spelled out", LIGHT_GRAY)
  line(monitor, "")
  line(monitor, "Options:")
  line(monitor, "  --model <id>     provider/model to use", LIGHT_GRAY)
  line(monitor, "  --agent <name>   " .. table.concat(M.AGENTS, ", "), LIGHT_GRAY)
  line(monitor, "  --dir <path>     working directory (default: the shell's)", LIGHT_GRAY)
  line(monitor, "  --save           save the session when it ends", LIGHT_GRAY)
  line(monitor, "  --stream         ask the provider for a stream", LIGHT_GRAY)
  line(monitor, "  --plain          the plain screen: no GUI, prints and wraps", LIGHT_GRAY)
  line(monitor, "  --help           this list", LIGHT_GRAY)
end

--- Split the program's arguments. `run` is accepted and ignored so the one-shot
--- form can be spelled out.
local function parse(argv)
  local options = { save = false, stream = false, help = false, plain = false }
  local rest = {}
  local index = 1
  while index <= #argv do
    local item = argv[index]
    if item == "--model" or item == "--agent" or item == "--dir" then
      options[item:sub(3)] = argv[index + 1]
      index = index + 2
    elseif item == "--save" then
      options.save = true
      index = index + 1
    elseif item == "--stream" then
      options.stream = true
      index = index + 1
    elseif item == "--plain" then
      options.plain = true
      index = index + 1
    elseif item == "--help" or item == "-h" then
      options.help = true
      index = index + 1
    elseif item == "run" and #rest == 0 then
      index = index + 1
    else
      rest[#rest + 1] = item
      index = index + 1
    end
  end
  options.question = table.concat(rest, " ")
  return options
end

--- Build the run state from parsed arguments. Split out so the REPL, one-shot
--- mode, and the test harness all start from the same place.
function M.setup(argv, monitor)
  local options = parse(argv or {})
  local cwd = options.dir and env.resolve(options.dir, env.cwd()) or env.cwd()

  local overrides = {}
  if options.model then
    overrides.model = options.model
  end

  local current = {
    config = config.load(cwd, overrides),
    cwd = cwd,
    root = cwd,
    agent = options.agent or "build",
    session = session.new(),
    monitor = monitor,
    autoSave = options.save,
    stream = options.stream,
    enabled = nil,
    -- The GUI, once one has been built. Nil here on purpose rather than left over
    -- from a previous call: this table is replaced on every run, and a stale `ui`
    -- here would have the second run drawing on a screen the first one closed.
    ui = nil,
  }
  current.enabled = current.config.tools

  current.model, current.error = resolveModel(current)
  if current.model then
    local small = provider.resolve(current.config, current.config.small_model)
    -- Falling back to the main model beats refusing to name a session at all.
    current.smallModel = small or current.model
  end

  M.state = current
  return current, options
end

--- The screen an interactive session draws on: the GUI, or the plain one.
--
-- Returns the screen, and the reason for not having a GUI when there is one to
-- give. The reason is said out loud rather than swallowed, because every way of
-- getting here is something the person in front of the computer can fix: a
-- `GUI.lua` that was not installed, a terminal too small for a title bar and a hint
-- line, a CraftOS with no event queue to read the keyboard from. Saying which one
-- it was is the difference between "the interface is broken" and "copy GUI.lua".
--
-- `--plain` gives no reason: it is the screen being asked for by name, not a
-- fallback, and saying so would read as an apology.
--
-- The GUI is always drawn on the terminal, whatever screen the caller passed. CraftOS
-- sends the keyboard to the terminal and `read` reads the terminal, so a field on a
-- monitor is a field nobody can reach, and the conversation is no use if the
-- answer cannot be typed.
local function interactiveScreen(options, fallback)
  if options.plain then
    return fallback
  end
  local screen, reason = ui.open(env.console())
  if not screen then
    return fallback, reason
  end
  M.state.ui = screen
  return screen
end

--- Program entry point. Returns the shell exit code.
function M.main(argv, monitor)
  -- Adapted here as well as in `env.terminal`, so that a caller who passes a
  -- screen of their own cannot end up with output that is not wrapped. A screen
  -- ComputerCraft has already given us is wrapped by the same code either way.
  monitor = env.screen(monitor or env.terminal())
  if not monitor then
    return 1
  end

  local state, options = M.setup(argv, monitor)
  if options.help then
    usage(monitor)
    return 0
  end
  if state.model == nil and state.error then
    -- Not fatal in the REPL: /model can still fix it, and the message says what is
    -- wrong. In one-shot mode `once` reports it instead, so it is not said twice.
    if options.question == "" then
      line(monitor, state.error, YELLOW)
    end
  end

  if options.question ~= "" then
    -- Deliberately the plain screen even with a GUI available. A one-shot's output
    -- is whatever is on the terminal when the program exits, and a screen that
    -- clears itself and keeps a scrollback nobody can reach once the program has
    -- gone is a worse answer to `opencode "what is 2 + 2"` than printed text.
    return once(monitor, options.question)
  end

  local screen, reason = interactiveScreen(options, monitor)
  if reason then
    line(monitor, "plain screen: " .. reason, LIGHT_GRAY)
  end
  repl(screen)
  return 0
end

--- Whether this file is the program being run, rather than a library that something
--- else loaded.
--
-- `require` and "run this file" look identical from inside the chunk, and a
-- computer has no `debug.getinfo` to tell them apart. `shell.getRunningProgram`
-- can: it names whichever program CC actually started, and `require` leaves it
-- alone. So a program that loads this one as a library does not get a REPL as a
-- side effect, which is the only reason this is worth asking.
--
-- The cost is a name, so it starts under the two names the installer writes. Rename
-- the file and it becomes a library, to be driven through `M.main`.
local function isProgram()
  local running = (shell and shell.getRunningProgram and shell.getRunningProgram()) or ""
  local name = running:match("([^/]+)$") or ""
  return name == "init.lua" or name == "opencode.lua"
end

if isProgram() then
  -- CC hands a program its command line as the chunk's varargs, so
  -- `shell.run("init.lua what is 2 + 2")` arrives here as one question.
  return M.main({ ... }, env.terminal())
end

return M

end
-- Module loading.
--
-- This deliberately does not read `package.loaded` to decide whether a module is
-- loaded. ComputerCraft's `require` marks the module it is loading with a
-- light-userdata sentinel, so a "is it already there?" check sees the sentinel
-- and hands that back to the caller in place of the module. `require` does its
-- own caching, so there is nothing to check.
local __loading = {}

local function __require(name, ...)
  local source = __sources[name]
  if not source then
    error("opencode: '" .. tostring(name) .. "' is not part of this bundle", 0)
  end
  if __loading[name] then
    -- The modules require each other, but never while one of them is still
    -- running: `tool/registry` pulls its tools in from `load()`, which is only
    -- called once the registry itself is complete. If this fires, it is a real
    -- require cycle and there is no way to guess the intended order.
    error("opencode: '" .. name .. "' is required while it is still loading, which cannot be resolved", 0)
  end
  __loading[name] = true
  local ok, result = pcall(source, name, ...)
  __loading[name] = nil
  if not ok then
    error("opencode: '" .. name .. "' failed to load: " .. tostring(result), 0)
  end
  package.loaded[name] = result == nil and true or result
  return result
end

for name in pairs(__sources) do
  package.preload[name] = __require
end

-- Run. On a computer the entry point has already run itself, and its return value
-- -- the shell's exit code -- is what requiring it produced. ComputerCraft hands a
-- program's return to nobody and passes `arg` in as a global, so `opencode
-- <question>` arrives the same way it does for the modular version.
--
-- When the bundle is loaded by something else, as the test suite does, the entry
-- came back as a library instead, and `main` is still waiting to be called. That is
-- the only place this return value is read.
local cli = __require("cli")
if type(cli) == "table" then
  return cli.main(arg or {}, nil)
end
return cli
